/** Generated by `npm run build:evidence` from MedQuAD. Do not edit by hand. */
export default [{"id": "medquad-CDC-0000090-1", "topic": "fatigue", "intent": "general-health", "type": "public-health", "org": "CDC", "title": "What is (are) Chronic Fatigue Syndrome (CFS)?", "url": "https://www.cdc.gov/cfs", "retrieved": "2026-08-14", "body": "Chronic fatigue syndrome, or CFS, is a devastating and complex disorder. People with CFS have overwhelming fatigue and a host of other symptoms that are not improved by bed rest and that can get worse after physical activity or mental exertion. They often function at a substantially lower level of activity than they were capable of before they became ill. Besides severe fatigue, other symptoms include muscle pain, impaired memory or mental concentration, insomnia, and post-exertion malaise lasting more than 24 hours. In some cases, CFS can persist for years. Researchers have not yet identified what causes CFS, and there are no tests to diagnose CFS.", "cues": ["what is (are) chronic fatigue syndrome (cfs)?", "chronic fatigue syndrome (cfs) information"]}, {"id": "medquad-CDC-0000090-2", "topic": "fatigue", "intent": "symptom", "type": "public-health", "org": "CDC", "title": "What causes Chronic Fatigue Syndrome (CFS)?", "url": "https://www.cdc.gov/cfs", "retrieved": "2026-08-14", "body": "Despite a vigorous search, scientists have not yet identified what causes CFS. While a single cause for CFS may yet be identified, another possibility is that CFS has multiple causes. Conditions that have been studied to determine if they cause or trigger the development of CFS include infections, immune disorders, stress, trauma, and toxins. Infection Various types of infections have been studied to determine if they might cause or trigger CFS: - Candida albicans, a fungus that causes yeast infections - Mycoplasma, a cause of atypical pneumonia - Ross River virus, which causes Ross River Fever, a mosquito-borne tropical disease Could One Type of Infection Lead to CFS?", "cues": ["what causes chronic fatigue syndrome (cfs)?", "chronic fatigue syndrome (cfs) causes"]}, {"id": "medquad-CDC-0000090-3", "topic": "fatigue", "intent": "general-health", "type": "public-health", "org": "CDC", "title": "How to diagnose Chronic Fatigue Syndrome (CFS)?", "url": "https://www.cdc.gov/cfs", "retrieved": "2026-08-14", "body": "Diagnostic Challenges For doctors, diagnosing chronic fatigue syndrome (CFS) can be complicated by a number of factors: - There's no lab test or biomarker for CFS. - Fatigue and other symptoms of CFS are common to many illnesses. - For some CFS patients, it may not be obvious to doctors that they are ill. - The illness has a pattern of remission and relapse. - Symptoms vary from person to person in type, number, and severity. These factors have contributed to a low diagnosis rate. Of the one to four million Americans who have CFS, less than 20% have been diagnosed.", "cues": ["how to diagnose chronic fatigue syndrome (cfs)?", "chronic fatigue syndrome (cfs) exams and tests"]}, {"id": "medquad-CDC-0000090-5", "topic": "fatigue", "intent": "symptom", "type": "public-health", "org": "CDC", "title": "What are the symptoms of Chronic Fatigue Syndrome (CFS)?", "url": "https://www.cdc.gov/cfs", "retrieved": "2026-08-14", "body": "Chronic fatigue syndrome can be misdiagnosed or overlooked because its symptoms are similar to so many other illnesses. Fatigue, for instance, can be a symptom for hundreds of illnesses. Looking closer at the nature of the symptoms though, can help a doctor distinguish CFS from other illnesses. Primary Symptoms As the name chronic fatigue syndrome suggests, fatigue is one part of this illness. With CFS, however, the fatigue is accompanied by other symptoms. In addition, the fatigue is not the kind you might feel after a particularly busy day or week, after a sleepless night, or after a single stressful event.", "cues": ["what are the symptoms of chronic fatigue syndrome (cfs)?", "chronic fatigue syndrome (cfs) symptoms"]}, {"id": "medquad-CDC-0000272-1", "topic": "fever", "intent": "preventive", "type": "public-health", "org": "CDC", "title": "Who is at risk for Marburg hemorrhagic fever (Marburg HF)??", "url": "https://www.cdc.gov/vhf/marburg/", "retrieved": "2026-08-14", "body": "It is unknown how Marburg virus first transmits from its animal host to humans; however, for the 2 cases in tourists visiting Uganda in 2008, unprotected contact with infected bat feces or aerosols are the most likely routes of infection. After this initial crossover of virus from host animal to humans, transmission occurs through person-to-person contact. This may happen in several ways: direct contact to droplets of body fluids from infected persons, or contact with equipment and other objects contaminated with infectious blood or tissues.", "cues": ["who is at risk for marburg hemorrhagic fever (marburg hf)??", "marburg hemorrhagic fever (marburg hf) susceptibility"]}, {"id": "medquad-CDC-0000438-2", "topic": "fever", "intent": "general-health", "type": "public-health", "org": "CDC", "title": "What is (are) Yellow Fever Vaccination?", "url": "https://www.cdc.gov/vaccines/vpd-vac/yf/default.htm", "retrieved": "2026-08-14", "body": "If you continue to live or travel in yellow fever-endemic areas, you should receive a booster dose of yellow fever vaccine after 10 years. After receiving the vaccine, you should receive an International Certificate of Vaccination (yellow card) that has been validated by the vaccination center. This Certificate becomes valid 10 days after vaccination and lasts for 10 years. You will need this card as proof of vaccination to enter certain countries.", "cues": ["what is (are) yellow fever vaccination?", "yellow fever vaccination information"]}, {"id": "medquad-MPlusHealthTopics-0000002-1", "topic": "abdominal pain", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Abdominal Pain?", "url": "https://www.nlm.nih.gov/medlineplus/abdominalpain.html", "retrieved": "2026-08-14", "body": "Your abdomen extends from below your chest to your groin. Some people call it the stomach, but your abdomen contains many other important organs. Pain in the abdomen can come from any one of them. The pain may start somewhere else, such as your chest. Severe pain doesn't always mean a serious problem. Nor does mild pain mean a problem is not serious. Call your healthcare provider if mild pain lasts a week or more or if you have pain with other symptoms.", "cues": ["what is (are) abdominal pain?", "abdominal pain information"]}, {"id": "medquad-MPlusHealthTopics-0000005-1", "topic": "acne", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Acne?", "url": "https://www.nlm.nih.gov/medlineplus/acne.html", "retrieved": "2026-08-14", "body": "Acne is a common skin disease that causes pimples. Pimples form when hair follicles under your skin clog up. Most pimples form on the face, neck, back, chest, and shoulders. Anyone can get acne, but it is common in teenagers and young adults. It is not serious, but it can cause scars. No one knows exactly what causes acne. Hormone changes, such as those during the teenage years and pregnancy, probably play a role. There are many myths about what causes acne. Chocolate and greasy foods are often blamed, but there is little evidence that foods have much effect on acne in most people. Another common myth is that dirty skin causes acne; however, blackheads and pimples are not caused by dirt.", "cues": ["what is (are) acne?", "acne information"]}, {"id": "medquad-MPlusHealthTopics-0000008-1", "topic": "bronchitis", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Acute Bronchitis?", "url": "https://www.nlm.nih.gov/medlineplus/acutebronchitis.html", "retrieved": "2026-08-14", "body": "Bronchitis is an inflammation of the bronchial tubes, the airways that carry air to your lungs. It causes a cough that often brings up mucus. It can also cause shortness of breath, wheezing, a low fever, and chest tightness. There are two main types of bronchitis: acute and chronic. Most cases of acute bronchitis get better within several days. But your cough can last for several weeks after the infection is gone. The same viruses that cause colds and the flu often cause acute bronchitis. These viruses spread through the air when people cough, or though physical contact (for example, on unwashed hands).", "cues": ["what is (are) acute bronchitis?", "acute bronchitis information"]}, {"id": "medquad-MPlusHealthTopics-0000020-1", "topic": "alcohol", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Alcohol", "url": "https://www.nlm.nih.gov/medlineplus/alcohol.html", "retrieved": "2026-08-14", "body": "Summary : If you are like many Americans, you drink alcohol at least occasionally. For many people, moderate drinking is probably safe. It may even have health benefits, including reducing your risk of certain heart problems. For most women and for most people over 65, moderate drinking is no more than three drinks a day or seven drinks per week. For men under 65, it is no more than four drinks a day or 14 drinks per week. Some people should not drink at all, including alcoholics, children, pregnant women, people taking certain medicines, and people with certain medical conditions. If you have questions about whether it is safe for you to drink, speak with your health care provider.", "cues": ["do you have information about alcohol", "alcohol information"]}, {"id": "medquad-MPlusHealthTopics-0000021-1", "topic": "alcohol", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Alcoholism and Alcohol Abuse?", "url": "https://www.nlm.nih.gov/medlineplus/alcoholismandalcoholabuse.html", "retrieved": "2026-08-14", "body": "For most adults, moderate alcohol use is probably not harmful. However, about 18 million adult Americans have an alcohol use disorder. This means that their drinking causes distress and harm. It includes alcoholism and alcohol abuse. Alcoholism, or alcohol dependence, is a disease that causes - Craving - a strong need to drink - Loss of control - not being able to stop drinking once you've started - Physical dependence - withdrawal symptoms - Tolerance - the need to drink more alcohol to feel the same effect With alcohol abuse, you are not physically dependent, but you still have a serious problem. The drinking may cause problems at home, work, or school.", "cues": ["what is (are) alcoholism and alcohol abuse?", "alcoholism and alcohol abuse information"]}, {"id": "medquad-MPlusHealthTopics-0000022-1", "topic": "allergy", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Allergy?", "url": "https://www.nlm.nih.gov/medlineplus/allergy.html", "retrieved": "2026-08-14", "body": "An allergy is a reaction by your immune system to something that does not bother most other people. People who have allergies often are sensitive to more than one thing. Substances that often cause reactions are - Pollen - Dust mites - Mold spores - Pet dander - Food - Insect stings - Medicines Normally, your immune system fights germs. It is your body's defense system. In most allergic reactions, however, it is responding to a false alarm. Genes and the environment probably both play a role. Allergies can cause a variety of symptoms such as a runny nose, sneezing, itching, rashes, swelling, or asthma. Allergies can range from minor to severe.", "cues": ["what is (are) allergy?", "allergy information"]}, {"id": "medquad-MPlusHealthTopics-0000034-1", "topic": "anemia", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Anemia?", "url": "https://www.nlm.nih.gov/medlineplus/anemia.html", "retrieved": "2026-08-14", "body": "If you have anemia, your blood does not carry enough oxygen to the rest of your body. The most common cause of anemia is not having enough iron. Your body needs iron to make hemoglobin. Hemoglobin is an iron-rich protein that gives the red color to blood. It carries oxygen from the lungs to the rest of the body. Anemia has three main causes: blood loss, lack of red blood cell production, and high rates of red blood cell destruction.", "cues": ["what is (are) anemia?", "anemia information"]}, {"id": "medquad-MPlusHealthTopics-0000048-1", "topic": "anxiety", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Anxiety?", "url": "https://www.nlm.nih.gov/medlineplus/anxiety.html", "retrieved": "2026-08-14", "body": "Fear and anxiety are part of life. You may feel anxious before you take a test or walk down a dark street. This kind of anxiety is useful - it can make you more alert or careful. It usually ends soon after you are out of the situation that caused it. But for millions of people in the United States, the anxiety does not go away, and gets worse over time. They may have chest pains or nightmares. They may even be afraid to leave home. These people have anxiety disorders. Types include - Panic disorder - Obsessive-compulsive disorder - Post-traumatic stress disorder - Phobias - Generalized anxiety disorder Treatment can involve medicines, therapy or both. NIH: National Institute of Mental Health", "cues": ["what is (are) anxiety?", "anxiety information"]}, {"id": "medquad-MPlusHealthTopics-0000051-1", "topic": "anemia", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Aplastic Anemia?", "url": "https://www.nlm.nih.gov/medlineplus/aplasticanemia.html", "retrieved": "2026-08-14", "body": "Aplastic anemia is a rare but serious blood disorder. If you have it, your bone marrow doesn't make enough new blood cells. Causes include - Toxic substances, such as pesticides, arsenic, and benzene - Radiation therapy and chemotherapy for cancer - Certain medicines - Infections such as hepatitis, Epstein-Barr virus, or HIV - Autoimmune disorders - Certain inherited conditions - Pregnancy In many people, the cause is unknown. Symptoms include fatigue, weakness, dizziness, and shortness of breath. It can cause heart problems such as an irregular heartbeat, an enlarged heart, and heart failure. You may also have frequent infections and bleeding.", "cues": ["what is (are) aplastic anemia?", "aplastic anemia information"]}, {"id": "medquad-MPlusHealthTopics-0000057-1", "topic": "arthritis", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Arthritis?", "url": "https://www.nlm.nih.gov/medlineplus/arthritis.html", "retrieved": "2026-08-14", "body": "If you feel pain and stiffness in your body or have trouble moving around, you might have arthritis. Most kinds of arthritis cause pain and swelling in your joints. Joints are places where two bones meet, such as your elbow or knee. Over time, a swollen joint can become severely damaged. Some kinds of arthritis can also cause problems in your organs, such as your eyes or skin. Types of arthritis include - Osteoarthritis is the most common type of arthritis. It's often related to aging or to an injury. - Autoimmune arthritis happens when your body's immune system attacks healthy cells in your body by mistake. Rheumatoid arthritis is the most common form of this kind of arthritis.", "cues": ["what is (are) arthritis?", "arthritis information"]}, {"id": "medquad-MPlusHealthTopics-0000065-1", "topic": "asthma", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Asthma?", "url": "https://www.nlm.nih.gov/medlineplus/asthma.html", "retrieved": "2026-08-14", "body": "Asthma is a chronic disease that affects your airways. Your airways are tubes that carry air in and out of your lungs. If you have asthma, the inside walls of your airways become sore and swollen. That makes them very sensitive, and they may react strongly to things that you are allergic to or find irritating. When your airways react, they get narrower and your lungs get less air. Symptoms of asthma include - Wheezing - Coughing, especially early in the morning or at night - Chest tightness - Shortness of breath Not all people who have asthma have these symptoms. Having these symptoms doesn't always mean that you have asthma.", "cues": ["what is (are) asthma?", "asthma information"]}, {"id": "medquad-MPlusHealthTopics-0000066-1", "topic": "asthma", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Asthma in Children?", "url": "https://www.nlm.nih.gov/medlineplus/asthmainchildren.html", "retrieved": "2026-08-14", "body": "Asthma is a chronic disease that affects your airways. Your airways are tubes that carry air in and out of your lungs. If you have asthma, the inside walls of your airways become sore and swollen. In the United States, about 20 million people have asthma. Nearly 9 million of them are children. Children have smaller airways than adults, which makes asthma especially serious for them. Children with asthma may experience wheezing, coughing, chest tightness, and trouble breathing, especially early in the morning or at night.", "cues": ["what is (are) asthma in children?", "asthma in children information"]}, {"id": "medquad-MPlusHealthTopics-0000078-1", "topic": "back pain", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Back Pain?", "url": "https://www.nlm.nih.gov/medlineplus/backpain.html", "retrieved": "2026-08-14", "body": "If you've ever groaned, \"Oh, my aching back!\", you are not alone. Back pain is one of the most common medical problems, affecting 8 out of 10 people at some point during their lives. Back pain can range from a dull, constant ache to a sudden, sharp pain. Acute back pain comes on suddenly and usually lasts from a few days to a few weeks. Back pain is called chronic if it lasts for more than three months. Most back pain goes away on its own, though it may take awhile. Taking over-the-counter pain relievers and resting can help. However, staying in bed for more than 1 or 2 days can make it worse.", "cues": ["what is (are) back pain?", "back pain information"]}, {"id": "medquad-MPlusHealthTopics-0000093-1", "topic": "bipolar", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Bipolar Disorder?", "url": "https://www.nlm.nih.gov/medlineplus/bipolardisorder.html", "retrieved": "2026-08-14", "body": "Bipolar disorder is a serious mental illness. People who have it go through unusual mood changes. They go from very happy, \"up,\" and active to very sad and hopeless, \"down,\" and inactive, and then back again. They often have normal moods in between. The up feeling is called mania. The down feeling is depression. The causes of bipolar disorder aren't always clear. It runs in families. Abnormal brain structure and function may also play a role. Bipolar disorder often starts in a person's late teen or early adult years. But children and adults can have bipolar disorder too. The illness usually lasts a lifetime. If you think you may have it, tell your health care provider.", "cues": ["what is (are) bipolar disorder?", "bipolar disorder information"]}, {"id": "medquad-MPlusHealthTopics-0000094-1", "topic": "flu", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Bird Flu?", "url": "https://www.nlm.nih.gov/medlineplus/birdflu.html", "retrieved": "2026-08-14", "body": "Birds, just like people, get the flu. Bird flu viruses infect birds, including chickens, other poultry, and wild birds such as ducks. Most bird flu viruses can only infect other birds. However, bird flu can pose health risks to people. The first case of a bird flu virus infecting a person directly, H5N1, was in Hong Kong in 1997. Since then, the bird flu virus has spread to birds in countries in Asia, Africa, the Middle East, and Europe. Human infection is still very rare, but the virus that causes the infection in birds might change, or mutate, to more easily infect humans. This could lead to a pandemic, a worldwide outbreak of the illness.", "cues": ["what is (are) bird flu?", "bird flu information"]}, {"id": "medquad-MPlusHealthTopics-0000097-1", "topic": "weight", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Birth Weight", "url": "https://www.nlm.nih.gov/medlineplus/birthweight.html", "retrieved": "2026-08-14", "body": "Summary : Birth weight is the first weight of your baby, taken just after he or she is born. A low birth weight is less than 5.5 pounds. A high birth weight is more than 8.8 pounds. A low birth weight baby can be born too small, too early (premature), or both. This can happen for many different reasons. They include health problems in the mother, genetic factors, problems with the placenta and substance abuse by the mother. Some low birth weight babies may be more at risk for certain health problems. Some may become sick in the first days of life or develop infections. Others may suffer from longer-term problems such as delayed motor and social development or learning disabilities.", "cues": ["do you have information about birth weight", "birth weight information"]}, {"id": "medquad-MPlusHealthTopics-0000111-1", "topic": "weight", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Body Weight", "url": "https://www.nlm.nih.gov/medlineplus/bodyweight.html", "retrieved": "2026-08-14", "body": "Summary : Do you know if your current weight is healthy? \"Underweight\", \"normal\", \"overweight\", and \"obese\" are all labels for ranges of weight. Obese and overweight mean that your weight is greater than it should be for your health. Underweight means that it is lower than it should be for your health. Your healthy body weight depends on your sex and height. For children, it also depends on your age. A sudden, unexpected change in weight can be a sign of a medical problem.", "cues": ["do you have information about body weight", "body weight information"]}, {"id": "medquad-MPlusHealthTopics-0000136-1", "topic": "burns", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Burns?", "url": "https://www.nlm.nih.gov/medlineplus/burns.html", "retrieved": "2026-08-14", "body": "A burn is damage to your body's tissues caused by heat, chemicals, electricity, sunlight or radiation. Scalds from hot liquids and steam, building fires and flammable liquids and gases are the most common causes of burns. Another kind is an inhalation injury, caused by breathing smoke. There are three types of burns: - First-degree burns damage only the outer layer of skin - Second-degree burns damage the outer layer and the layer underneath - Third-degree burns damage or destroy the deepest layer of skin and tissues underneath Burns can cause swelling, blistering, scarring and, in serious cases, shock and even death.", "cues": ["what is (are) burns?", "burns information"]}, {"id": "medquad-MPlusHealthTopics-0000138-1", "topic": "caffeine", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Caffeine", "url": "https://www.nlm.nih.gov/medlineplus/caffeine.html", "retrieved": "2026-08-14", "body": "Summary : Caffeine is a bitter substance found in coffee, tea, soft drinks, chocolate, kola nuts, and certain medicines. It has many effects on the body's metabolism, including stimulating the central nervous system. This can make you more alert and give you a boost of energy. For most people, the amount of caffeine in two to four cups of coffee a day is not harmful. However, too much caffeine can cause problems. It can - Make you jittery and shaky - Make it hard to fall asleep or stay asleep - Cause headaches or dizziness - Make your heart beat faster or cause abnormal heart rhythms - Cause dehydration - Make you dependent on it so you need to take more of it.", "cues": ["do you have information about caffeine", "caffeine information"]}, {"id": "medquad-MPlusHealthTopics-0000171-1", "topic": "pain", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Chest Pain?", "url": "https://www.nlm.nih.gov/medlineplus/chestpain.html", "retrieved": "2026-08-14", "body": "Having a pain in your chest can be scary. It does not always mean that you are having a heart attack. There can be many other causes, including - Other heart problems, such as angina - Panic attacks - Digestive problems, such as heartburn or esophagus disorders - Sore muscles - Lung diseases, such as pneumonia, pleurisy, or pulmonary embolism - Costochondritis - an inflammation of joints in your chest Some of these problems can be serious. Get immediate medical care if you have chest pain that does not go away, crushing pain or pressure in the chest, or chest pain along with nausea, sweating, dizziness or shortness of breath. Treatment depends on the cause of the pain.", "cues": ["what is (are) chest pain?", "chest pain information"]}, {"id": "medquad-MPlusHealthTopics-0000180-1", "topic": "mental health", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Child Mental Health", "url": "https://www.nlm.nih.gov/medlineplus/childmentalhealth.html", "retrieved": "2026-08-14", "body": "Summary : It's important to recognize and treat mental illnesses in children early on. Once mental illness develops, it becomes a regular part of your child's behavior and is more difficult to treat. But it's not always easy to know when your child has a serious problem. Everyday stresses can cause changes in your child's behavior. For example, getting a new brother or sister or going to a new school may cause a child to temporarily act out.", "cues": ["do you have information about child mental health", "child mental health information"]}, {"id": "medquad-MPlusHealthTopics-0000187-1", "topic": "immunization", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Childhood Immunization", "url": "https://www.nlm.nih.gov/medlineplus/childhoodimmunization.html", "retrieved": "2026-08-14", "body": "Summary : Today, children in the United States routinely get vaccines that protect them from more than a dozen diseases such as measles, polio, tetanus, diphtheria, and pertussis (whooping cough). Most of these diseases are now at their lowest levels in history, thanks to years of immunization. Children must get at least some vaccines before they may attend school. Vaccines help make you immune to serious diseases without getting sick first. Without a vaccine, you must actually get a disease in order to become immune to the germ that causes it. Vaccines work best when they are given at certain ages. For example, children don't receive measles vaccine until they are at least one year old.", "cues": ["do you have information about childhood immunization", "childhood immunization information"]}, {"id": "medquad-MPlusHealthTopics-0000195-1", "topic": "cholesterol", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Cholesterol", "url": "https://www.nlm.nih.gov/medlineplus/cholesterol.html", "retrieved": "2026-08-14", "body": "Summary : Cholesterol is a waxy, fat-like substance that occurs naturally in all parts of the body. Your body needs some cholesterol to work properly. But if you have too much in your blood, it can combine with other substances in the blood and stick to the walls of your arteries. This is called plaque. Plaque can narrow your arteries or even block them. High levels of cholesterol in the blood can increase your risk of heart disease. Your cholesterol levels tend to rise as you get older. There are usually no signs or symptoms that you have high blood cholesterol, but it can be detected with a blood test.", "cues": ["do you have information about cholesterol", "cholesterol information"]}, {"id": "medquad-MPlusHealthTopics-0000197-1", "topic": "bronchitis", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Chronic Bronchitis?", "url": "https://www.nlm.nih.gov/medlineplus/chronicbronchitis.html", "retrieved": "2026-08-14", "body": "Bronchitis is an inflammation of the bronchial tubes, the airways that carry air to your lungs. It causes a cough that often brings up mucus. It can also cause shortness of breath, wheezing, a low fever, and chest tightness. There are two main types of bronchitis: acute and chronic. Chronic bronchitis is one type of COPD (chronic obstructive pulmonary disease). The inflamed bronchial tubes produce a lot of mucus. This leads to coughing and difficulty breathing. Cigarette smoking is the most common cause. Breathing in air pollution, fumes, or dust over a long period of time may also cause it.", "cues": ["what is (are) chronic bronchitis?", "chronic bronchitis information"]}, {"id": "medquad-MPlusHealthTopics-0000198-1", "topic": "fatigue", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Chronic Fatigue Syndrome?", "url": "https://www.nlm.nih.gov/medlineplus/chronicfatiguesyndrome.html", "retrieved": "2026-08-14", "body": "Chronic fatigue syndrome (CFS) is a disorder that causes extreme fatigue. This fatigue is not the kind of tired feeling that goes away after you rest. Instead, it lasts a long time and limits your ability to do ordinary daily activities. The main symptom of CFS is severe fatigue that lasts for 6 months or more. You also have at least four of these other symptoms: - Feeling unwell for more than 24 hours after physical activity - Muscle pain - Memory problems - Headaches - Pain in multiple joints - Sleep problems - Sore throat - Tender lymph nodes CFS is hard to diagnose. There are no tests for it, and other illnesses can cause similar symptoms.", "cues": ["what is (are) chronic fatigue syndrome?", "chronic fatigue syndrome information"]}, {"id": "medquad-MPlusHealthTopics-0000202-1", "topic": "pain", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Chronic Pain?", "url": "https://www.nlm.nih.gov/medlineplus/chronicpain.html", "retrieved": "2026-08-14", "body": "Pain is a feeling set off in the nervous system. Acute pain lets you know that you may be injured or have a problem you need to take care of. Chronic pain is different. The pain signals go on for weeks, months, or even years. The original cause may have been an injury or infection. There may be an ongoing cause of pain, such as arthritis or cancer. But in some cases there is no clear cause. Problems that cause chronic pain include - Headache - Low back strain - Cancer - Arthritis - Pain from nerve damage Chronic pain usually cannot be cured. But treatments can help. They include medicines, acupuncture, electrical stimulation and surgery.", "cues": ["what is (are) chronic pain?", "chronic pain information"]}, {"id": "medquad-MPlusHealthTopics-0000212-1", "topic": "ear", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Cochlear Implants", "url": "https://www.nlm.nih.gov/medlineplus/cochlearimplants.html", "retrieved": "2026-08-14", "body": "Summary : A cochlear implant is a small, complex electronic device that can help to provide a sense of sound. People who are profoundly deaf or severely hard-of-hearing can get help from them. The implant consists of two parts. One part sits on the outside of the body, behind the ear. A second part is surgically placed under the skin. An implant does not restore normal hearing. It can help a person understand speech. Children and adults can benefit from them. National Institute on Deafness and Other Communication Disorders", "cues": ["do you have information about cochlear implants", "cochlear implants information"]}, {"id": "medquad-MPlusHealthTopics-0000213-1", "topic": "cold", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Cold and Cough Medicines", "url": "https://www.nlm.nih.gov/medlineplus/coldandcoughmedicines.html", "retrieved": "2026-08-14", "body": "Summary : Sneezing, sore throat, a stuffy nose, coughing -- everyone knows the symptoms of the common cold. It is probably the most common illness. In the course of a year, people in the United States suffer 1 billion colds. What can you do for your cold or cough symptoms? Besides drinking plenty of fluids and getting plenty of rest, you may want to take medicines. There are lots of different cold and cough medicines, and they do different things.", "cues": ["do you have information about cold and cough medicines", "cold and cough medicines information"]}, {"id": "medquad-MPlusHealthTopics-0000214-1", "topic": "cold", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Cold Sores?", "url": "https://www.nlm.nih.gov/medlineplus/coldsores.html", "retrieved": "2026-08-14", "body": "Cold sores are caused by a contagious virus called herpes simplex virus (HSV). There are two types of HSV. Type 1 usually causes oral herpes, or cold sores. Type 1 herpes virus infects more than half of the U.S. population by the time they reach their 20s. Type 2 usually affects the genital area Some people have no symptoms from the infection. But others develop painful and unsightly cold sores. Cold sores usually occur outside the mouth, on or around the lips. When they are inside the mouth, they are usually on the gums or the roof of the mouth. They are not the same as canker sores, which are not contagious. There is no cure for cold sores.", "cues": ["what is (are) cold sores?", "cold sores information"]}, {"id": "medquad-MPlusHealthTopics-0000223-1", "topic": "cold", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Common Cold?", "url": "https://www.nlm.nih.gov/medlineplus/commoncold.html", "retrieved": "2026-08-14", "body": "Sneezing, sore throat, a stuffy nose, coughing - everyone knows the symptoms of the common cold. It is probably the most common illness. In the course of a year, people in the United States suffer 1 billion colds. You can get a cold by touching your eyes or nose after you touch surfaces with cold germs on them. You can also inhale the germs. Symptoms usually begin 2 or 3 days after infection and last 2 to 14 days. Washing your hands and staying away from people with colds will help you avoid colds. There is no cure for the common cold.", "cues": ["what is (are) common cold?", "common cold information"]}, {"id": "medquad-MPlusHealthTopics-0000226-1", "topic": "pain", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Complex Regional Pain Syndrome?", "url": "https://www.nlm.nih.gov/medlineplus/complexregionalpainsyndrome.html", "retrieved": "2026-08-14", "body": "Complex regional pain syndrome (CRPS) is a chronic pain condition. It causes intense pain, usually in the arms, hands, legs, or feet. It may happen after an injury, either to a nerve or to tissue in the affected area. Rest and time may only make it worse. Symptoms in the affected area are - Dramatic changes in skin temperature, color, or texture - Intense burning pain - Extreme skin sensitivity - Swelling and stiffness in affected joints - Decreased ability to move the affected body part The cause of CRPS is unknown. There is no specific diagnostic test. Your doctor will diagnose CRPS based on your signs and symptoms. There is no cure.", "cues": ["what is (are) complex regional pain syndrome?", "complex regional pain syndrome information"]}, {"id": "medquad-MPlusHealthTopics-0000228-1", "topic": "concussion", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Concussion?", "url": "https://www.nlm.nih.gov/medlineplus/concussion.html", "retrieved": "2026-08-14", "body": "A concussion is a type of brain injury. It's the most minor form. Technically, a concussion is a short loss of normal brain function in response to a head injury. But people often use it to describe any minor injury to the head or brain. Concussions are a common type of sports injury. You can also have one if you suffer a blow to the head or hit your head after a fall. Symptoms of a concussion may not start right away; they may start days or weeks after the injury. Symptoms may include a headache or neck pain. You may also have nausea, ringing in your ears, dizziness, or tiredness. You may feel dazed or not your normal self for several days or weeks after the injury.", "cues": ["what is (are) concussion?", "concussion information"]}, {"id": "medquad-MPlusHealthTopics-0000229-1", "topic": "heart", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Congenital Heart Defects?", "url": "https://www.nlm.nih.gov/medlineplus/congenitalheartdefects.html", "retrieved": "2026-08-14", "body": "A congenital heart defect is a problem with the structure of the heart. It is present at birth. Congenital heart defects are the most common type of birth defect. The defects can involve the walls of the heart, the valves of the heart, and the arteries and veins near the heart. They can disrupt the normal flow of blood through the heart. The blood flow can slow down, go in the wrong direction or to the wrong place, or be blocked completely. Doctors use a physical exam and special heart tests to diagnose congenital heart defects. They often find severe defects during pregnancy or soon after birth.", "cues": ["what is (are) congenital heart defects?", "congenital heart defects information"]}, {"id": "medquad-MPlusHealthTopics-0000231-1", "topic": "constipation", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Constipation?", "url": "https://www.nlm.nih.gov/medlineplus/constipation.html", "retrieved": "2026-08-14", "body": "Constipation means that a person has three or fewer bowel movements in a week. The stool can be hard and dry. Sometimes it is painful to pass. At one time or another, almost everyone gets constipated. In most cases, it lasts a short time and is not serious. There are many things you can do to prevent constipation.", "cues": ["what is (are) constipation?", "constipation information"]}, {"id": "medquad-MPlusHealthTopics-0000239-1", "topic": "infection", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Coronavirus Infections?", "url": "https://www.nlm.nih.gov/medlineplus/coronavirusinfections.html", "retrieved": "2026-08-14", "body": "Coronaviruses are common viruses that most people get some time in their life. They are common throughout the world, and they can infect people and animals. Several different coronaviruses can infect people and make them sick. They usually cause mild to moderate upper-respiratory illness. But, some coronaviruses can cause severe illness. Coronaviruses probably spread through the air by coughing or sneezing, or by close personal contact.", "cues": ["what is (are) coronavirus infections?", "coronavirus infections information"]}, {"id": "medquad-MPlusHealthTopics-0000242-1", "topic": "cough", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Cough?", "url": "https://www.nlm.nih.gov/medlineplus/cough.html", "retrieved": "2026-08-14", "body": "Coughing is a reflex that keeps your throat and airways clear. Although it can be annoying, coughing helps your body heal or protect itself. Coughs can be either acute or chronic. Acute coughs begin suddenly and usually last no more than 2 to 3 weeks. Acute coughs are the kind you most often get with a cold, flu, or acute bronchitis. Chronic coughs last longer than 2 to 3 weeks.", "cues": ["what is (are) cough?", "cough information"]}, {"id": "medquad-MPlusHealthTopics-0000255-1", "topic": "diet", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about DASH Diet", "url": "https://www.nlm.nih.gov/medlineplus/dashdiet.html", "retrieved": "2026-08-14", "body": "Summary : DASH stands for Dietary Approaches to Stop Hypertension. It is an eating plan that is based on research studies sponsored by the National Heart, Lung, and Blood Institute (NHLBI). These studies showed that DASH lowers high blood pressure and improves levels of cholesterol. This reduces your risk of getting heart disease. The DASH Diet - Emphasizes vegetables, fruits, and fat-free or low-fat dairy products. - Includes whole grains, fish, poultry, beans, seeds, nuts, and vegetable oils. - Limits sodium, sweets, sugary beverages, and red meats. Along with DASH, other lifestyle changes can help lower your blood pressure.", "cues": ["do you have information about dash diet", "dash diet information"]}, {"id": "medquad-MPlusHealthTopics-0000258-1", "topic": "dehydration", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Dehydration?", "url": "https://www.nlm.nih.gov/medlineplus/dehydration.html", "retrieved": "2026-08-14", "body": "When you're dehydrated, your body doesn't have enough fluid to work properly. An average person on an average day needs about 3 quarts of water. But if you're out in the hot sun, you'll need a lot more than that. Most healthy bodies are very good at regulating water. Elderly people, young children and some special cases - like people taking certain medications - need to be a little more careful.", "cues": ["what is (are) dehydration?", "dehydration information"]}, {"id": "medquad-MPlusHealthTopics-0000264-1", "topic": "depression", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Depression?", "url": "https://www.nlm.nih.gov/medlineplus/depression.html", "retrieved": "2026-08-14", "body": "Depression is a serious medical illness. It's more than just a feeling of being sad or \"blue\" for a few days. If you are one of the more than 19 million teens and adults in the United States who have depression, the feelings do not go away. They persist and interfere with your everyday life. Symptoms can include - Feeling sad or \"empty\" - Loss of interest in favorite activities - Overeating, or not wanting to eat at all - Not being able to sleep, or sleeping too much - Feeling very tired - Feeling hopeless, irritable, anxious, or guilty - Aches or pains, headaches, cramps, or digestive problems - Thoughts of death or suicide Depression is a disorder of the brain.", "cues": ["what is (are) depression?", "depression information"]}, {"id": "medquad-MPlusHealthTopics-0000266-1", "topic": "diabetes", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Diabetes?", "url": "https://www.nlm.nih.gov/medlineplus/diabetes.html", "retrieved": "2026-08-14", "body": "Diabetes is a disease in which your blood glucose, or blood sugar, levels are too high. Glucose comes from the foods you eat. Insulin is a hormone that helps the glucose get into your cells to give them energy. With type 1 diabetes, your body does not make insulin. With type 2 diabetes, the more common type, your body does not make or use insulin well. Without enough insulin, the glucose stays in your blood. You can also have prediabetes. This means that your blood sugar is higher than normal but not high enough to be called diabetes. Having prediabetes puts you at a higher risk of getting type 2 diabetes. Over time, having too much glucose in your blood can cause serious problems.", "cues": ["what is (are) diabetes?", "diabetes information"]}, {"id": "medquad-MPlusHealthTopics-0000267-1", "topic": "diabetes", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Diabetes and Pregnancy?", "url": "https://www.nlm.nih.gov/medlineplus/diabetesandpregnancy.html", "retrieved": "2026-08-14", "body": "Diabetes is a disease in which your blood glucose, or blood sugar, levels are too high. When you are pregnant, high blood sugar levels are not good for your baby. About seven out of every 100 pregnant women in the United States get gestational diabetes. Gestational diabetes is diabetes that happens for the first time when a woman is pregnant. Most of the time, it goes away after you have your baby. But it does increase your risk for developing type 2 diabetes later on. Your child is also at risk for obesity and type 2 diabetes. Most women get a test to check for diabetes during their second trimester of pregnancy. Women at higher risk may get a test earlier.", "cues": ["what is (are) diabetes and pregnancy?", "diabetes and pregnancy information"]}, {"id": "medquad-MPlusHealthTopics-0000270-1", "topic": "diabetes", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Diabetes Insipidus?", "url": "https://www.nlm.nih.gov/medlineplus/diabetesinsipidus.html", "retrieved": "2026-08-14", "body": "Diabetes insipidus (DI) causes frequent urination. You become extremely thirsty, so you drink. Then you urinate. This cycle can keep you from sleeping or even make you wet the bed. Your body produces lots of urine that is almost all water. DI is different from diabetes mellitus (DM), which involves insulin problems and high blood sugar. The symptoms can be similar. However, DI is related to how your kidneys handle fluids. It's much less common than DM. Urine and blood tests can show which one you have. Usually, DI is caused by a problem with your pituitary gland or your kidneys. Treatment depends on the cause of the problem. Medicines can often help.", "cues": ["what is (are) diabetes insipidus?", "diabetes insipidus information"]}, {"id": "medquad-MPlusHealthTopics-0000271-1", "topic": "diabetes", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Diabetes Medicines", "url": "https://www.nlm.nih.gov/medlineplus/diabetesmedicines.html", "retrieved": "2026-08-14", "body": "Summary : Diabetes means your blood glucose, or blood sugar, levels are too high. If you can't control your diabetes with wise food choices and physical activity, you may need diabetes medicines. The kind of medicine you take depends on your type of diabetes, your schedule, and your other health conditions. With type 1 diabetes, your pancreas does not make insulin. Insulin is a hormone that helps glucose get into your cells to give them energy. Without insulin, too much glucose stays in your blood. If you have type 1 diabetes, you will need to take insulin. Type 2 diabetes, the most common type, can start when the body doesn't use insulin as it should.", "cues": ["do you have information about diabetes medicines", "diabetes medicines information"]}, {"id": "medquad-MPlusHealthTopics-0000272-1", "topic": "diabetes", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Diabetes Type 1?", "url": "https://www.nlm.nih.gov/medlineplus/diabetestype1.html", "retrieved": "2026-08-14", "body": "Diabetes means your blood glucose, or blood sugar, levels are too high. With type 1 diabetes, your pancreas does not make insulin. Insulin is a hormone that helps glucose get into your cells to give them energy. Without insulin, too much glucose stays in your blood. Over time, high blood glucose can lead to serious problems with your heart, eyes, kidneys, nerves, and gums and teeth. Type 1 diabetes happens most often in children and young adults but can appear at any age.", "cues": ["what is (are) diabetes type 1?", "diabetes type 1 information"]}, {"id": "medquad-MPlusHealthTopics-0000273-1", "topic": "diabetes", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Diabetes Type 2?", "url": "https://www.nlm.nih.gov/medlineplus/diabetestype2.html", "retrieved": "2026-08-14", "body": "Diabetes means your blood glucose, or blood sugar, levels are too high. With type 2 diabetes, the more common type, your body does not make or use insulin well. Insulin is a hormone that helps glucose get into your cells to give them energy. Without insulin, too much glucose stays in your blood. Over time, high blood glucose can lead to serious problems with your heart, eyes, kidneys, nerves, and gums and teeth. You have a higher risk of type 2 diabetes if you are older, obese, have a family history of diabetes, or do not exercise. Having prediabetes also increases your risk. Prediabetes means that your blood sugar is higher than normal but not high enough to be called diabetes.", "cues": ["what is (are) diabetes type 2?", "diabetes type 2 information"]}, {"id": "medquad-MPlusHealthTopics-0000274-1", "topic": "diet", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Diabetic Diet", "url": "https://www.nlm.nih.gov/medlineplus/diabeticdiet.html", "retrieved": "2026-08-14", "body": "Summary : If you have diabetes, your body cannot make or properly use insulin. This leads to high blood glucose, or blood sugar, levels. Healthy eating helps keep your blood sugar in your target range. It is a critical part of managing your diabetes, because controlling your blood sugar can prevent the complications of diabetes. A registered dietitian can help make an eating plan just for you. It should take into account your weight, medicines, lifestyle, and other health problems you have.", "cues": ["do you have information about diabetic diet", "diabetic diet information"]}, {"id": "medquad-MPlusHealthTopics-0000275-1", "topic": "eye", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Diabetic Eye Problems?", "url": "https://www.nlm.nih.gov/medlineplus/diabeticeyeproblems.html", "retrieved": "2026-08-14", "body": "If you have diabetes, your blood glucose, or blood sugar, levels are too high. Over time, this can damage your eyes. The most common problem is diabetic retinopathy. It is a leading cause of blindness in American adults. Your retina is the light-sensitive tissue at the back of your eye. You need a healthy retina to see clearly. Diabetic retinopathy damages the tiny blood vessels inside your retina. You may not notice it at first.", "cues": ["what is (are) diabetic eye problems?", "diabetic eye problems information"]}, {"id": "medquad-MPlusHealthTopics-0000277-1", "topic": "heart", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Diabetic Heart Disease?", "url": "https://www.nlm.nih.gov/medlineplus/diabeticheartdisease.html", "retrieved": "2026-08-14", "body": "If you have diabetes or pre-diabetes you have an increased risk for heart disease. Diabetic heart disease can be coronary heart disease (CHD), heart failure, and diabetic cardiomyopathy. Diabetes by itself puts you at risk for heart disease. Other risk factors include - Family history of heart disease - Carrying extra weight around the waist - Abnormal cholesterol levels - High blood pressure - Smoking Some people who have diabetic heart disease have no signs or symptoms of heart disease. Others have some or all of the symptoms of heart disease. Treatments include medications to treat heart damage or to lower your blood glucose (blood sugar), blood pressure, and cholesterol.", "cues": ["what is (are) diabetic heart disease?", "diabetic heart disease information"]}, {"id": "medquad-MPlusHealthTopics-0000282-1", "topic": "diarrhea", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Diarrhea?", "url": "https://www.nlm.nih.gov/medlineplus/diarrhea.html", "retrieved": "2026-08-14", "body": "Diarrhea means that you have loose, watery stools more than three times in one day. You may also have cramps, bloating, nausea and an urgent need to have a bowel movement. Causes of diarrhea include bacteria, viruses or parasites, certain medicines, food intolerances and diseases that affect the stomach, small intestine or colon. In many cases, no cause can be found. Although usually not harmful, diarrhea can become dangerous or signal a more serious problem. You should talk to your doctor if you have a strong pain in your abdomen or rectum, a fever, blood in your stools, severe diarrhea for more than three days or symptoms of dehydration.", "cues": ["what is (are) diarrhea?", "diarrhea information"]}, {"id": "medquad-MPlusHealthTopics-0000283-1", "topic": "diet", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Dietary Fats", "url": "https://www.nlm.nih.gov/medlineplus/dietaryfats.html", "retrieved": "2026-08-14", "body": "Summary : Fat is a type of nutrient. You need some fat in your diet but not too much. Fats give you energy and help your body absorb vitamins. Dietary fat also plays a major role in your cholesterol levels. But not all fats are the same. You should try to avoid - Saturated fats such as butter, solid shortening, and lard - Trans fats. These are found in vegetable shortenings, some margarines, crackers, cookies, snack foods, and other foods made with or fried in partially hydrogenated oils (PHOs). By 2018, most U.S. companies will not be allowed to add PHOs to food. Try to replace them with oils such as canola, olive, safflower, sesame, or sunflower.", "cues": ["do you have information about dietary fats", "dietary fats information"]}, {"id": "medquad-MPlusHealthTopics-0000284-1", "topic": "diet", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Dietary Fiber", "url": "https://www.nlm.nih.gov/medlineplus/dietaryfiber.html", "retrieved": "2026-08-14", "body": "Summary : Fiber is a substance in plants. Dietary fiber is the kind you eat. It's a type of carbohydrate. You may also see it listed on a food label as soluble fiber or insoluble fiber. Both types have important health benefits. Good sources of dietary fiber include - Whole grains - Nuts and seeds - Fruit and vegetables Dietary fiber adds bulk to your diet and makes you feel full faster, helping you control your weight. It helps digestion and helps prevent constipation. Most Americans don't eat enough dietary fiber. But add it to your diet slowly. Increasing dietary fiber too quickly can lead to gas, bloating, and cramps. Centers for Disease Control and Prevention", "cues": ["do you have information about dietary fiber", "dietary fiber information"]}, {"id": "medquad-MPlusHealthTopics-0000285-1", "topic": "diet", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Dietary Proteins", "url": "https://www.nlm.nih.gov/medlineplus/dietaryproteins.html", "retrieved": "2026-08-14", "body": "Summary : Protein is in every cell in the body. Our bodies need protein from the foods we eat to build and maintain bones, muscles and skin. We get proteins in our diet from meat, dairy products, nuts, and certain grains and beans. Proteins from meat and other animal products are complete proteins. This means they supply all of the amino acids the body can't make on its own. Plant proteins are incomplete. You must combine different types of plant proteins to get all of the amino acids your body needs. It is important to get enough dietary protein. You need to eat protein every day, because your body doesn't store it the way it stores fats or carbohydrates.", "cues": ["do you have information about dietary proteins", "dietary proteins information"]}, {"id": "medquad-MPlusHealthTopics-0000295-1", "topic": "dizziness", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Dizziness and Vertigo?", "url": "https://www.nlm.nih.gov/medlineplus/dizzinessandvertigo.html", "retrieved": "2026-08-14", "body": "When you're dizzy, you may feel lightheaded or lose your balance. If you feel that the room is spinning, you have vertigo. A sudden drop in blood pressure or being dehydrated can make you dizzy. Many people feel lightheaded if they get up too quickly from sitting or lying down. Dizziness usually gets better by itself or is easily treated. However, it can be a symptom of other disorders. Medicines may cause dizziness, or problems with your ear. Motion sickness can also make you dizzy. There are many other causes. If you are dizzy often, you should see your health care provider to find the cause.", "cues": ["what is (are) dizziness and vertigo?", "dizziness and vertigo information"]}, {"id": "medquad-MPlusHealthTopics-0000298-1", "topic": "water", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Drinking Water", "url": "https://www.nlm.nih.gov/medlineplus/drinkingwater.html", "retrieved": "2026-08-14", "body": "Summary : We all need to drink water. How much you need depends on your size, activity level, and the weather where you live. The water you drink is a combination of surface water and groundwater. Surface water includes rivers, lakes and reservoirs. Groundwater comes from underground. The United States has one of the safest water supplies in the world, but drinking water quality can vary from place to place. It depends on the condition of the source water and the treatment it receives. Treatment may include adding fluoride to prevent cavities and chlorine to kill germs. Your water supplier must give you annual reports on drinking water.", "cues": ["do you have information about drinking water", "drinking water information"]}, {"id": "medquad-MPlusHealthTopics-0000310-1", "topic": "ear", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Ear Disorders?", "url": "https://www.nlm.nih.gov/medlineplus/eardisorders.html", "retrieved": "2026-08-14", "body": "Your ear has three main parts: outer, middle and inner. You use all of them in hearing. Sound waves come in through your outer ear. They reach your middle ear, where they make your eardrum vibrate. The vibrations are transmitted through three tiny bones, called ossicles, in your middle ear. The vibrations travel to your inner ear, a snail-shaped organ. The inner ear makes the nerve impulses that are sent to the brain. Your brain recognizes them as sounds. The inner ear also controls balance. A variety of conditions may affect your hearing or balance: - Ear infections are the most common illness in infants and young children.", "cues": ["what is (are) ear disorders?", "ear disorders information"]}, {"id": "medquad-MPlusHealthTopics-0000311-1", "topic": "ear", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Ear Infections?", "url": "https://www.nlm.nih.gov/medlineplus/earinfections.html", "retrieved": "2026-08-14", "body": "Ear infections are the most common reason parents bring their child to a doctor. Three out of four children will have at least one ear infection by their third birthday. Adults can also get ear infections, but they are less common. The infection usually affects the middle ear and is called otitis media. The tubes inside the ears become clogged with fluid and mucus. This can affect hearing, because sound cannot get through all that fluid.", "cues": ["what is (are) ear infections?", "ear infections information"]}, {"id": "medquad-MPlusHealthTopics-0000312-1", "topic": "ear", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Earthquakes?", "url": "https://www.nlm.nih.gov/medlineplus/earthquakes.html", "retrieved": "2026-08-14", "body": "An earthquake happens when two blocks of the earth suddenly slip past one another. Earthquakes strike suddenly, violently, and without warning at any time of the day or night. If an earthquake occurs in a populated area, it may cause property damage, injuries, and even deaths. If you live in a coastal area, there is the possibility of a tsunami. Damage from earthquakes can also lead to floods or fires. Although there are no guarantees of safety during an earthquake, you can take actions to protect yourself. You should have a disaster plan. Being prepared can help reduce fear, anxiety, and losses. If you do experience a disaster, it is normal to feel stressed.", "cues": ["what is (are) earthquakes?", "earthquakes information"]}, {"id": "medquad-MPlusHealthTopics-0000315-1", "topic": "pregnancy", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Ectopic Pregnancy?", "url": "https://www.nlm.nih.gov/medlineplus/ectopicpregnancy.html", "retrieved": "2026-08-14", "body": "The uterus, or womb, is the place where a baby grows when a woman is pregnant. If you have an ectopic pregnancy, the fertilized egg grows in the wrong place, outside the uterus, usually in the fallopian tubes. The result is usually a miscarriage. Ectopic pregnancy can be a medical emergency if it ruptures. Signs of ectopic pregnancy include - Abdominal pain - Shoulder pain - Vaginal bleeding - Feeling dizzy or faint Get medical care right away if you have these signs. Doctors use drugs or surgery to remove the ectopic tissue so it doesn't damage your organs. Many women who have had ectopic pregnancies go on to have healthy pregnancies later. Dept.", "cues": ["what is (are) ectopic pregnancy?", "ectopic pregnancy information"]}, {"id": "medquad-MPlusHealthTopics-0000316-1", "topic": "eczema", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Eczema?", "url": "https://www.nlm.nih.gov/medlineplus/eczema.html", "retrieved": "2026-08-14", "body": "Eczema is a term for several different types of skin swelling. Eczema is also called dermatitis. Most types cause dry, itchy skin and rashes on the face, inside the elbows and behind the knees, and on the hands and feet. Scratching the skin can cause it to turn red, and to swell and itch even more. Eczema is not contagious. The cause is not known. It is likely caused by both genetic and environmental factors. Eczema may get better or worse over time, but it is often a long-lasting disease. People who have it may also develop hay fever and asthma. The most common type of eczema is atopic dermatitis. It is most common in babies and children but adults can have it too.", "cues": ["what is (are) eczema?", "eczema information"]}, {"id": "medquad-MPlusHealthTopics-0000331-1", "topic": "mental health", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Environmental Health", "url": "https://www.nlm.nih.gov/medlineplus/environmentalhealth.html", "retrieved": "2026-08-14", "body": "Summary : Our environment affects our health. If parts of the environment, like the air, water, or soil become polluted, it can lead to health problems. For example, asthma pollutants and chemicals in the air or in the home can trigger asthma attacks. Some environmental risks are a part of the natural world, like radon in the soil. Others are the result of human activities, like lead poisoning from paint, or exposure to asbestos or mercury from mining or industrial use. NIH: National Institute of Environmental Health Sciences", "cues": ["do you have information about environmental health", "environmental health information"]}, {"id": "medquad-MPlusHealthTopics-0000339-1", "topic": "exercise", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Exercise and Physical Fitness", "url": "https://www.nlm.nih.gov/medlineplus/exerciseandphysicalfitness.html", "retrieved": "2026-08-14", "body": "Summary : Regular physical activity is one of the most important things you can do for your health. It can help - Control your weight - Lower your risk of heart disease - Lower your risk for type 2 diabetes and metabolic syndrome - Lower your risk of some cancers - Strengthen your bones and muscles - Improve your mental health and mood - Improve your ability to do daily activities and prevent falls, if you're an older adult - Increase your chances of living longer Fitting regular exercise into your daily schedule may seem difficult at first. But even ten minutes at a time is fine. The key is to find the right exercise for you. It should be fun and should match your abilities.", "cues": ["do you have information about exercise and physical fitness", "exercise and physical fitness information"]}, {"id": "medquad-MPlusHealthTopics-0000340-1", "topic": "exercise", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Exercise for Children", "url": "https://www.nlm.nih.gov/medlineplus/exerciseforchildren.html", "retrieved": "2026-08-14", "body": "Summary : Like adults, kids need exercise. Most children need at least an hour of physical activity every day. Regular exercise helps children - Feel less stressed - Feel better about themselves - Feel more ready to learn in school - Keep a healthy weight - Build and keep healthy bones, muscles and joints - Sleep better at night As kids spend more time watching TV, they spend less time running and playing. Parents should limit TV, video game and computer time. Parents can set a good example by being active themselves. Exercising together can be fun for everyone. Competitive sports can help kids stay fit.", "cues": ["do you have information about exercise for children", "exercise for children information"]}, {"id": "medquad-MPlusHealthTopics-0000341-1", "topic": "exercise", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Exercise for Seniors", "url": "https://www.nlm.nih.gov/medlineplus/exerciseforseniors.html", "retrieved": "2026-08-14", "body": "Summary : Exercise and physical activity are good for just about everyone, including older adults. There are four main types and each type is different. Doing them all will give you more benefits. - Endurance, or aerobic, activities increase your breathing and heart rate. Brisk walking or jogging, dancing, swimming, and biking are examples. - Strength exercises make your muscles stronger. Lifting weights or using a resistance band can build strength. - Balance exercises help prevent falls - Flexibility exercises stretch your muscles and can help your body stay limber NIH: National Institute on Aging", "cues": ["do you have information about exercise for seniors", "exercise for seniors information"]}, {"id": "medquad-MPlusHealthTopics-0000342-1", "topic": "eye", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Eye Cancer?", "url": "https://www.nlm.nih.gov/medlineplus/eyecancer.html", "retrieved": "2026-08-14", "body": "Cancer of the eye is uncommon. It can affect the outer parts of the eye, such as the eyelid, which are made up of muscles, skin and nerves. If the cancer starts inside the eyeball it's called intraocular cancer. The most common intraocular cancers in adults are melanoma and lymphoma. The most common eye cancer in children is retinoblastoma, which starts in the cells of the retina. Cancer can also spread to the eye from other parts of the body. Treatment for eye cancer varies by the type and by how advanced it is. It may include surgery, radiation therapy, freezing or heat therapy, or laser therapy.", "cues": ["what is (are) eye cancer?", "eye cancer information"]}, {"id": "medquad-MPlusHealthTopics-0000343-1", "topic": "eye", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Eye Diseases?", "url": "https://www.nlm.nih.gov/medlineplus/eyediseases.html", "retrieved": "2026-08-14", "body": "Some eye problems are minor and don't last long. But some can lead to a permanent loss of vision. Common eye problems include - Refractive errors - Cataracts - clouded lenses - Glaucoma - a disorder caused by damage to the optic nerve - Retinal disorders - problems with the nerve layer at the back of the eye - Macular degeneration - a disease that destroys sharp, central vision - Diabetic eye problems - Conjunctivitis - an infection also known as pinkeye Your best defense is to have regular checkups, because eye diseases do not always have symptoms. Early detection and treatment could prevent vision loss.", "cues": ["what is (are) eye diseases?", "eye diseases information"]}, {"id": "medquad-MPlusHealthTopics-0000348-1", "topic": "eye", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Eyelid Disorders?", "url": "https://www.nlm.nih.gov/medlineplus/eyeliddisorders.html", "retrieved": "2026-08-14", "body": "Your eyelids help protect your eyes. When you blink, your eyelids spread moisture over your eyes. Blinking also helps move dirt or other particles off the surface of the eye. You close your eyelids when you see something coming towards your eyes. This can help protect against injuries. Like most other parts of your body, your eyelids can get infected, inflamed, or even develop cancer. There are also specific eyelid problems, including - Eyelids that turn in or out - Eyelids that droop - Abnormal blinking or twitching Treatment of eyelid problems depends on the cause.", "cues": ["what is (are) eyelid disorders?", "eyelid disorders information"]}, {"id": "medquad-MPlusHealthTopics-0000350-1", "topic": "fainting", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Fainting?", "url": "https://www.nlm.nih.gov/medlineplus/fainting.html", "retrieved": "2026-08-14", "body": "Fainting is a temporary loss of consciousness. If you're about to faint, you'll feel dizzy, lightheaded, or nauseous. Your field of vision may \"white out\" or \"black out.\" Your skin may be cold and clammy. You lose muscle control at the same time, and may fall down. Fainting usually happens when your blood pressure drops suddenly, causing a decrease in blood flow to your brain. It is more common in older people. Some causes of fainting include - Heat or dehydration - Emotional distress - Standing up too quickly - Certain medicines - Drop in blood sugar - Heart problems When someone faints, make sure that the airway is clear and check for breathing.", "cues": ["what is (are) fainting?", "fainting information"]}, {"id": "medquad-MPlusHealthTopics-0000355-1", "topic": "fatigue", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Fatigue?", "url": "https://www.nlm.nih.gov/medlineplus/fatigue.html", "retrieved": "2026-08-14", "body": "Everyone feels tired now and then. Sometimes you may just want to stay in bed. But, after a good night's sleep, most people feel refreshed and ready to face a new day. If you continue to feel tired for weeks, it's time to see your doctor. He or she may be able to help you find out what's causing your fatigue and recommend ways to relieve it. Fatigue itself is not a disease. Medical problems, treatments, and personal habits can add to fatigue.", "cues": ["what is (are) fatigue?", "fatigue information"]}, {"id": "medquad-MPlusHealthTopics-0000357-1", "topic": "alcohol", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Fetal Alcohol Spectrum Disorders?", "url": "https://www.nlm.nih.gov/medlineplus/fetalalcoholspectrumdisorders.html", "retrieved": "2026-08-14", "body": "Alcohol can harm your baby at any stage during a pregnancy. That includes the earliest stages before you even know you are pregnant. Drinking alcohol can cause a group of conditions called fetal alcohol spectrum disorders (FASDs). Effects can include physical and behavioral problems such as trouble with - Learning and remembering - Understanding and following directions - Controlling emotions - Communicating and socializing - Daily life skills, such as feeding and bathing Fetal alcohol syndrome is the most serious type of FASD. People with fetal alcohol syndrome have facial abnormalities, including wide-set and narrow eyes, growth problems and nervous system abnormalities.", "cues": ["what is (are) fetal alcohol spectrum disorders?", "fetal alcohol spectrum disorders information"]}, {"id": "medquad-MPlusHealthTopics-0000359-1", "topic": "fever", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Fever?", "url": "https://www.nlm.nih.gov/medlineplus/fever.html", "retrieved": "2026-08-14", "body": "A fever is a body temperature that is higher than normal. It is not an illness. It is part of your body's defense against infection. Most bacteria and viruses that cause infections do well at the body's normal temperature (98.6 F). A slight fever can make it harder for them to survive. Fever also activates your body's immune system. Infections cause most fevers. There can be many other causes, including - Medicines - Heat exhaustion - Cancers - Autoimmune diseases Treatment depends on the cause of your fever. Your health care provider may recommend using over-the-counter medicines such as acetaminophen or ibuprofen to lower a very high fever.", "cues": ["what is (are) fever?", "fever information"]}, {"id": "medquad-MPlusHealthTopics-0000366-1", "topic": "first aid", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about First Aid", "url": "https://www.nlm.nih.gov/medlineplus/firstaid.html", "retrieved": "2026-08-14", "body": "Summary : Accidents happen. Someone chokes on an ice cube or gets stung by a bee. It is important to know when to call 9-1-1 -- it is for life-threatening emergencies. While waiting for help to arrive, you may be able to save someone's life. Cardiopulmonary resuscitation (CPR) is for people whose hearts or breathing has stopped and the Heimlich maneuver is for people who are choking. You can also learn to handle common injuries and wounds. Cuts and scrapes, for example, should be rinsed with cool water. To stop bleeding, apply firm but gentle pressure, using gauze. If blood soaks through, add more gauze, keeping the first layer in place. Continue to apply pressure.", "cues": ["do you have information about first aid", "first aid information"]}, {"id": "medquad-MPlusHealthTopics-0000369-1", "topic": "flu", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Flu?", "url": "https://www.nlm.nih.gov/medlineplus/flu.html", "retrieved": "2026-08-14", "body": "Flu is a respiratory infection caused by a number of viruses. The viruses pass through the air and enter your body through your nose or mouth. Between 5% and 20% of people in the U.S. get the flu each year. The flu can be serious or even deadly for elderly people, newborn babies, and people with certain chronic illnesses. Symptoms of the flu come on suddenly and are worse than those of the common cold. They may include - Body or muscle aches - Chills - Cough - Fever - Headache - Sore throat Is it a cold or the flu? Colds rarely cause a fever or headaches. Flu almost never causes an upset stomach. And \"stomach flu\" isn't really flu at all, but gastroenteritis.", "cues": ["what is (are) flu?", "flu information"]}, {"id": "medquad-MPlusHealthTopics-0000370-1", "topic": "flu", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Flu Shot", "url": "https://www.nlm.nih.gov/medlineplus/flushot.html", "retrieved": "2026-08-14", "body": "Summary : Flu is a respiratory infection caused by a number of viruses. Most people with the flu get better on their own. But it can be serious. It can cause complications and sometimes even death. Getting the flu vaccine every year is the best way to lower your chance of getting the flu and spreading it to others. The flu vaccine causes antibodies to develop in your body about two weeks after you get it. These antibodies provide protection against infection with the viruses that are in the vaccine. Flu vaccines can either be shots or nasal sprays. There is also a high-dose version for people 65 and older. Ask your health care provider which one is right for you.", "cues": ["do you have information about flu shot", "flu shot information"]}, {"id": "medquad-MPlusHealthTopics-0000371-1", "topic": "flu", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Fluid and Electrolyte Balance", "url": "https://www.nlm.nih.gov/medlineplus/fluidandelectrolytebalance.html", "retrieved": "2026-08-14", "body": "Summary : Electrolytes are minerals in your body that have an electric charge. They are in your blood, urine and body fluids. Maintaining the right balance of electrolytes helps your body's blood chemistry, muscle action and other processes. Sodium, calcium, potassium, chlorine, phosphate and magnesium are all electrolytes. You get them from the foods you eat and the fluids you drink. Levels of electrolytes in your body can become too low or too high. That can happen when the amount of water in your body changes, causing dehydration or overhydration. Causes include some medicines, vomiting, diarrhea, sweating or kidney problems.", "cues": ["do you have information about fluid and electrolyte balance", "fluid and electrolyte balance information"]}, {"id": "medquad-MPlusHealthTopics-0000373-1", "topic": "allergy", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Food Allergy?", "url": "https://www.nlm.nih.gov/medlineplus/foodallergy.html", "retrieved": "2026-08-14", "body": "Food allergy is an abnormal response to a food triggered by your body's immune system. In adults, the foods that most often trigger allergic reactions include fish, shellfish, peanuts, and tree nuts, such as walnuts. Problem foods for children can include eggs, milk, peanuts, tree nuts, soy, and wheat. The allergic reaction may be mild. In rare cases it can cause a severe reaction called anaphylaxis.", "cues": ["what is (are) food allergy?", "food allergy information"]}, {"id": "medquad-MPlusHealthTopics-0000403-1", "topic": "hygiene", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Germs and Hygiene", "url": "https://www.nlm.nih.gov/medlineplus/germsandhygiene.html", "retrieved": "2026-08-14", "body": "Summary : When you cough or sneeze, you send tiny germ-filled droplets into the air. Colds and flu usually spread that way. You can help stop the spread of germs by - Covering your mouth and nose when you sneeze or cough. Sneeze or cough into your elbow, not your hands. - Cleaning your hands often - always before you eat or prepare food, and after you use the bathroom or change a diaper - Avoiding touching your eyes, nose or mouth Hand washing is one of the most effective and most overlooked ways to stop disease. Soap and water work well to kill germs. Wash for at least 20 seconds and rub your hands briskly. Disposable hand wipes or gel sanitizers also work well.", "cues": ["do you have information about germs and hygiene", "germs and hygiene information"]}, {"id": "medquad-MPlusHealthTopics-0000405-1", "topic": "infection", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Giardia Infections?", "url": "https://www.nlm.nih.gov/medlineplus/giardiainfections.html", "retrieved": "2026-08-14", "body": "Giardiasis is an illness caused by a parasite called Giardia intestinalis. It lives in soil, food, and water. It may also be on surfaces that have been contaminated with waste. You can become infected if you swallow the parasite. You can also get it if you're exposed to human feces (poop) through sexual contact. The risk of getting giardia is higher for travelers to countries where it is common, people in child care settings, and those who drink untreated water. Diarrhea is the main symptom of giardia infection. Others include - Passing gas - Greasy stools - Stomach cramps - Upset stomach or nausea These symptoms may lead to weight loss and loss of body fluids.", "cues": ["what is (are) giardia infections?", "giardia infections information"]}, {"id": "medquad-MPlusHealthTopics-0000415-1", "topic": "flu", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) H1N1 Flu (Swine Flu)?", "url": "https://www.nlm.nih.gov/medlineplus/h1n1fluswineflu.html", "retrieved": "2026-08-14", "body": "Swine flu is an infection caused by a virus. It's named for a virus that pigs can get. People do not normally get swine flu, but human infections can and do happen. In 2009 a strain of swine flu called H1N1 infected many people around the world. The virus is contagious and can spread from human to human. Symptoms of swine flu in people are similar to the symptoms of regular human flu and include fever, cough, sore throat, body aches, headache, chills and fatigue. There are antiviral medicines you can take to prevent or treat swine flu. There is a vaccine available to protect against swine flu.", "cues": ["what is (are) h1n1 flu (swine flu)?", "h1n1 flu (swine flu) information"]}, {"id": "medquad-MPlusHealthTopics-0000421-1", "topic": "fever", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Hay Fever?", "url": "https://www.nlm.nih.gov/medlineplus/hayfever.html", "retrieved": "2026-08-14", "body": "Each spring, summer, and fall, trees, weeds, and grasses release tiny pollen grains into the air. Some of the pollen ends up in your nose and throat. This can trigger a type of allergy called hay fever. Symptoms can include - Sneezing, often with a runny or clogged nose - Coughing and postnasal drip - Itching eyes, nose and throat - Red and watery eyes - Dark circles under the eyes Your health care provider may diagnose hay fever based on a physical exam and your symptoms. Sometimes skin or blood tests are used. Taking medicines and using nasal sprays can relieve symptoms. You can also rinse out your nose, but be sure to use distilled or sterilized water with saline.", "cues": ["what is (are) hay fever?", "hay fever information"]}, {"id": "medquad-MPlusHealthTopics-0000426-1", "topic": "headache", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Headache?", "url": "https://www.nlm.nih.gov/medlineplus/headache.html", "retrieved": "2026-08-14", "body": "Almost everyone has had a headache. Headache is the most common form of pain. It's a major reason people miss days at work or school or visit the doctor. The most common type of headache is a tension headache. Tension headaches are due to tight muscles in your shoulders, neck, scalp and jaw. They are often related to stress, depression or anxiety. You are more likely to get tension headaches if you work too much, don't get enough sleep, miss meals, or use alcohol. Other common types of headaches include migraines, cluster headaches, and sinus headaches. Most people can feel much better by making lifestyle changes, learning ways to relax and taking pain relievers.", "cues": ["what is (are) headache?", "headache information"]}, {"id": "medquad-MPlusHealthTopics-0000439-1", "topic": "hearing", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Hearing Aids?", "url": "https://www.nlm.nih.gov/medlineplus/hearingaids.html", "retrieved": "2026-08-14", "body": "A hearing aid is a small electronic device that you wear in or behind your ear. It makes some sounds louder. A hearing aid can help people hear more in both quiet and noisy situations. Hearing aids help people who have hearing loss from damage to the small sensory cells in the inner ear. The damage can occur as a result of disease, aging, or injury from noise or certain medicines. Only about one out of five people who would benefit from a hearing aid actually uses one. If you think a hearing aid could help you, visit your doctor. There are different kinds of hearing aids. They differ by size, their placement on or inside the ear, and how much they amplify sound.", "cues": ["what is (are) hearing aids?", "hearing aids information"]}, {"id": "medquad-MPlusHealthTopics-0000440-1", "topic": "hearing", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Hearing Disorders and Deafness?", "url": "https://www.nlm.nih.gov/medlineplus/hearingdisordersanddeafness.html", "retrieved": "2026-08-14", "body": "It's frustrating to be unable to hear well enough to enjoy talking with friends or family. Hearing disorders make it hard, but not impossible, to hear. They can often be helped. Deafness can keep you from hearing sound at all. What causes hearing loss? Some possibilities are - Heredity - Diseases such as ear infections and meningitis - Trauma - Certain medicines - Long-term exposure to loud noise - Aging There are two main types of hearing loss. One happens when your inner ear or auditory nerve is damaged. This type is usually permanent. The other kind happens when sound waves cannot reach your inner ear. Earwax build-up, fluid, or a punctured eardrum can cause it.", "cues": ["what is (are) hearing disorders and deafness?", "hearing disorders and deafness information"]}, {"id": "medquad-MPlusHealthTopics-0000441-1", "topic": "hearing", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Hearing Problems in Children?", "url": "https://www.nlm.nih.gov/medlineplus/hearingproblemsinchildren.html", "retrieved": "2026-08-14", "body": "Most children hear and listen from the moment they are born. They learn to talk by imitating the sounds around them and the voices of their parents and caregivers. But about 2 or 3 out of every 1,000 children in the United States are born deaf or hard-of-hearing. More lose their hearing later during childhood. Babies should have a hearing screening before they are a month old. If your child has a hearing loss, it is important to consider the use of hearing devices and other communication options by age 6 months. That's because children start learning speech and language long before they talk. Hearing problems can be temporary or permanent.", "cues": ["what is (are) hearing problems in children?", "hearing problems in children information"]}, {"id": "medquad-MPlusHealthTopics-0000446-1", "topic": "heart", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Heart Failure?", "url": "https://www.nlm.nih.gov/medlineplus/heartfailure.html", "retrieved": "2026-08-14", "body": "Heart failure is a condition in which the heart can't pump enough blood to meet the body's needs. Heart failure does not mean that your heart has stopped or is about to stop working. It means that your heart is not able to pump blood the way it should. It can affect one or both sides of the heart. The weakening of the heart's pumping ability causes - Blood and fluid to back up into the lungs - The buildup of fluid in the feet, ankles and legs - called edema - Tiredness and shortness of breath Common causes of heart failure are coronary artery disease, high blood pressure and diabetes.", "cues": ["what is (are) heart failure?", "heart failure information"]}, {"id": "medquad-MPlusHealthTopics-0000447-1", "topic": "heart", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Heart Surgery", "url": "https://www.nlm.nih.gov/medlineplus/heartsurgery.html", "retrieved": "2026-08-14", "body": "Summary : Heart surgery can correct problems with the heart if other treatments haven't worked or can't be used. The most common type of heart surgery for adults is coronary artery bypass grafting (CABG). During CABG, a healthy artery or vein from the body is connected, or grafted, to a blocked coronary (heart) artery.", "cues": ["do you have information about heart surgery", "heart surgery information"]}, {"id": "medquad-MPlusHealthTopics-0000448-1", "topic": "heart", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Heart Transplantation", "url": "https://www.nlm.nih.gov/medlineplus/hearttransplantation.html", "retrieved": "2026-08-14", "body": "Summary : A heart transplant removes a damaged or diseased heart and replaces it with a healthy one. The healthy heart comes from a donor who has died. It is the last resort for people with heart failure when all other treatments have failed. The heart failure might have been caused by coronary heart disease, damaged heart valves or heart muscles, congenital heart defects, or viral infections of the heart. Although heart transplant surgery is a life-saving measure, it has many risks. Careful monitoring, treatment, and regular medical care can prevent or help manage some of these risks. After the surgery, most heart transplant patients can return to their normal levels of activity.", "cues": ["do you have information about heart transplantation", "heart transplantation information"]}, {"id": "medquad-MPlusHealthTopics-0000449-1", "topic": "heart", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Heart Valve Diseases?", "url": "https://www.nlm.nih.gov/medlineplus/heartvalvediseases.html", "retrieved": "2026-08-14", "body": "Your heart has four valves. Normally, these valves open to let blood flow through or out of your heart, and then shut to keep it from flowing backward. But sometimes they don't work properly. If they don't, you could have - Regurgitation - when blood leaks back through the valve in the wrong direction - Mitral valve prolapse - when one of the valves, the mitral valve, has \"floppy\" flaps and doesn't close tightly. It's one of the most common heart valve conditions. Sometimes it causes regurgitation. - Stenosis - when the valve doesn't open enough and blocks blood flow Valve problems can be present at birth or caused by infections, heart attacks, or heart disease or damage.", "cues": ["what is (are) heart valve diseases?", "heart valve diseases information"]}, {"id": "medquad-MPlusHealthTopics-0000450-1", "topic": "heartburn", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Heartburn?", "url": "https://www.nlm.nih.gov/medlineplus/heartburn.html", "retrieved": "2026-08-14", "body": "Heartburn is a painful burning feeling in your chest or throat. It happens when stomach acid backs up into your esophagus, the tube that carries food from your mouth to your stomach. If you have heartburn more than twice a week, you may have GERD. But you can have GERD without having heartburn. Pregnancy, certain foods, alcohol, and some medications can bring on heartburn. Treating heartburn is important because over time reflux can damage the esophagus. Over-the-counter medicines may help. If the heartburn continues, you may need prescription medicines or surgery. If you have other symptoms such as crushing chest pain, it could be a heart attack. Get help immediately.", "cues": ["what is (are) heartburn?", "heartburn information"]}, {"id": "medquad-MPlusHealthTopics-0000456-1", "topic": "fever", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Hemorrhagic Fevers?", "url": "https://www.nlm.nih.gov/medlineplus/hemorrhagicfevers.html", "retrieved": "2026-08-14", "body": "Viral hemorrhagic fevers (VHFs) are a group of illnesses caused by four families of viruses. These include the Ebola and Marburg, Lassa fever, and yellow fever viruses. VHFs have common features: they affect many organs, they damage the blood vessels, and they affect the body's ability to regulate itself. Some VHFs cause mild disease, but some, like Ebola or Marburg, cause severe disease and death. VHFs are found around the world. Specific diseases are usually limited to areas where the animals that carry them live. For example, Lassa fever is limited to rural areas of West Africa where rats and mice carry the virus.", "cues": ["what is (are) hemorrhagic fevers?", "hemorrhagic fevers information"]}, {"id": "medquad-MPlusHealthTopics-0000471-1", "topic": "high blood pressure", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) High Blood Pressure?", "url": "https://www.nlm.nih.gov/medlineplus/highbloodpressure.html", "retrieved": "2026-08-14", "body": "Blood pressure is the force of your blood pushing against the walls of your arteries. Each time your heart beats, it pumps blood into the arteries. Your blood pressure is highest when your heart beats, pumping the blood. This is called systolic pressure. When your heart is at rest, between beats, your blood pressure falls. This is called diastolic pressure. Your blood pressure reading uses these two numbers. Usually the systolic number comes before or above the diastolic number. A reading of - 119/79 or lower is normal blood pressure - 140/90 or higher is high blood pressure - Between 120 and 139 for the top number, or between 80 and 89 for the bottom number is called prehypertension.", "cues": ["what is (are) high blood pressure?", "high blood pressure information"]}, {"id": "medquad-MPlusHealthTopics-0000472-1", "topic": "high blood pressure", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) High Blood Pressure in Pregnancy?", "url": "https://www.nlm.nih.gov/medlineplus/highbloodpressureinpregnancy.html", "retrieved": "2026-08-14", "body": "If you are pregnant, high blood pressure can cause problems for you and your unborn baby. You may have had high blood pressure before you got pregnant. Or you may get it once you are pregnant - a condition called gestational hypertension. Either one can cause low birth weight or premature delivery of the baby. Controlling your blood pressure during pregnancy and getting regular prenatal care are important for the health of you and your baby. Treatments for high blood pressure in pregnancy may include close monitoring of the baby, lifestyle changes, and certain medicines. Some pregnant women with high blood pressure develop preeclampsia.", "cues": ["what is (are) high blood pressure in pregnancy?", "high blood pressure in pregnancy information"]}, {"id": "medquad-MPlusHealthTopics-0000479-1", "topic": "pregnancy", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) HIV/AIDS and Pregnancy?", "url": "https://www.nlm.nih.gov/medlineplus/hivaidsandpregnancy.html", "retrieved": "2026-08-14", "body": "If you have HIV/AIDS and find out you are pregnant or think you may be pregnant, you should let your health care provider know as soon as possible. Some HIV/AIDS medicines may harm your baby. Your health care provider may want you to take different medicines or change the doses. It is also possible to give HIV to your baby. This is most likely to happen around the time you give birth. For this reason, treatment during this time is very important for protecting your baby from infection. Several treatments may prevent the virus from spreading from you to your baby. Your health care provider can recommend the best one for you.", "cues": ["what is (are) hiv/aids and pregnancy?", "hiv/aids and pregnancy information"]}, {"id": "medquad-MPlusHealthTopics-0000495-1", "topic": "thyroid", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Hyperthyroidism?", "url": "https://www.nlm.nih.gov/medlineplus/hyperthyroidism.html", "retrieved": "2026-08-14", "body": "Your thyroid is a butterfly-shaped gland in your neck, just above your collarbone. It is one of your endocrine glands, which make hormones. Thyroid hormones control the rate of many activities in your body. These include how fast you burn calories and how fast your heart beats. All of these activities are your body's metabolism. If your thyroid is too active, it makes more thyroid hormones than your body needs. This is called hyperthyroidism. Hyperthyroidism is more common in women, people with other thyroid problems, and those over 60 years old. Grave's disease, an autoimmune disorder, is the most common cause.", "cues": ["what is (are) hyperthyroidism?", "hyperthyroidism information"]}, {"id": "medquad-MPlusHealthTopics-0000498-1", "topic": "thyroid", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Hypothyroidism?", "url": "https://www.nlm.nih.gov/medlineplus/hypothyroidism.html", "retrieved": "2026-08-14", "body": "Your thyroid is a butterfly-shaped gland in your neck, just above your collarbone. It is one of your endocrine glands, which make hormones. Thyroid hormones control the rate of many activities in your body. These include how fast you burn calories and how fast your heart beats. All of these activities are your body's metabolism. If your thyroid gland is not active enough, it does not make enough thyroid hormone to meet your body's needs. This condition is hypothyroidism. Hypothyroidism is more common in women, people with other thyroid problems, and those over 60 years old. Hashimoto's disease, an autoimmune disorder, is the most common cause.", "cues": ["what is (are) hypothyroidism?", "hypothyroidism information"]}, {"id": "medquad-MPlusHealthTopics-0000501-1", "topic": "immunization", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Immunization", "url": "https://www.nlm.nih.gov/medlineplus/immunization.html", "retrieved": "2026-08-14", "body": "Summary : Shots may hurt a little, but the diseases they can prevent are a lot worse. Some are even life-threatening. Immunization shots, or vaccinations, are essential. They protect against things like measles, mumps, rubella, hepatitis B, polio, tetanus, diphtheria, and pertussis (whooping cough). Immunizations are important for adults as well as children. Your immune system helps your body fight germs by producing substances to combat them. Once it does, the immune system \"remembers\" the germ and can fight it again. Vaccines contain germs that have been killed or weakened. When given to a healthy person, the vaccine triggers the immune system to respond and thus build immunity.", "cues": ["do you have information about immunization", "immunization information"]}, {"id": "medquad-MPlusHealthTopics-0000504-1", "topic": "indigestion", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Indigestion?", "url": "https://www.nlm.nih.gov/medlineplus/indigestion.html", "retrieved": "2026-08-14", "body": "Nearly everyone has had indigestion at one time. It's a feeling of discomfort or a burning feeling in your upper abdomen. You may have heartburn or belch and feel bloated. You may also feel nauseated, or even throw up. You might get indigestion from eating too much or too fast, eating high-fat foods, or eating when you're stressed. Smoking, drinking too much alcohol, using some medicines, being tired, and having ongoing stress can also cause indigestion or make it worse. Sometimes the cause is a problem with the digestive tract, like an ulcer or GERD. Avoiding foods and situations that seem to cause it may help.", "cues": ["what is (are) indigestion?", "indigestion information"]}, {"id": "medquad-MPlusHealthTopics-0000508-1", "topic": "nutrition", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Infant and Newborn Nutrition", "url": "https://www.nlm.nih.gov/medlineplus/infantandnewbornnutrition.html", "retrieved": "2026-08-14", "body": "Summary : Food provides the energy and nutrients that babies need to be healthy. For a baby, breast milk is best. It has all the necessary vitamins and minerals. Infant formulas are available for babies whose mothers are not able or decide not to breastfeed. Infants usually start eating solid foods between 4 and 6 months of age. Check with your health care provider for the best time for your baby to start. If you introduce one new food at a time, you will be able to identify any foods that cause allergies in your baby. Some foods to stay away from include - Eggs - Honey - Peanuts (including peanut butter) - Other tree nuts", "cues": ["do you have information about infant and newborn nutrition", "infant and newborn nutrition information"]}, {"id": "medquad-MPlusHealthTopics-0000510-1", "topic": "pregnancy", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Infections and Pregnancy?", "url": "https://www.nlm.nih.gov/medlineplus/infectionsandpregnancy.html", "retrieved": "2026-08-14", "body": "If you are pregnant, an infection can be more than just a problem for you. Some infections can be dangerous to your baby. You can help yourself avoid infections: - Don't eat raw or undercooked meat - Don't share food or drinks with other people - Wash your hands frequently - Don't empty cat litter. Cats can transmit toxoplasmosis. You may need to take medicines or get a vaccine to prevent an infection in your baby. For example, you may need to take antibiotics if you develop an infection with group B strep, or take medicines if you have genital herpes. Only some medicines and vaccines are safe during pregnancy. Ask your health care provider about how best to protect you and your baby.", "cues": ["what is (are) infections and pregnancy?", "infections and pregnancy information"]}, {"id": "medquad-MPlusHealthTopics-0000511-1", "topic": "arthritis", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Infectious Arthritis?", "url": "https://www.nlm.nih.gov/medlineplus/infectiousarthritis.html", "retrieved": "2026-08-14", "body": "Most kinds of arthritis cause pain and swelling in your joints. Joints are places where two bones meet, such as your elbow or knee. Infectious arthritis is an infection in the joint. The infection comes from a bacterial, viral, or fungal infection that spreads from another part of the body. Symptoms of infectious arthritis include - Intense pain in the joint - Joint redness and swelling - Chills and fever - Inability to move the area with the infected joint One type of infectious arthritis is reactive arthritis. The reaction is to an infection somewhere else in your body. The joint is usually the knee, ankle, or toe.", "cues": ["what is (are) infectious arthritis?", "infectious arthritis information"]}, {"id": "medquad-MPlusHealthTopics-0000518-1", "topic": "insomnia", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Insomnia?", "url": "https://www.nlm.nih.gov/medlineplus/insomnia.html", "retrieved": "2026-08-14", "body": "Insomnia is a common sleep disorder. If you have it, you may have trouble falling asleep, staying asleep, or both. As a result, you may get too little sleep or have poor-quality sleep. You may not feel refreshed when you wake up. Symptoms of insomnia include: - Lying awake for a long time before you fall asleep - Sleeping for only short periods - Being awake for much of the night - Feeling as if you haven't slept at all - Waking up too early Your doctor will diagnose insomnia based on your medical and sleep histories and a physical exam. He or she also may recommend a sleep study. A sleep study measures how well you sleep and how your body responds to sleep problems.", "cues": ["what is (are) insomnia?", "insomnia information"]}, {"id": "medquad-MPlusHealthTopics-0000525-1", "topic": "iron", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Iron", "url": "https://www.nlm.nih.gov/medlineplus/iron.html", "retrieved": "2026-08-14", "body": "Summary : Iron is a mineral that our bodies need for many functions. For example, iron is part of hemoglobin, a protein which carries oxygen from our lungs throughout our bodies. It helps our muscles store and use oxygen. Iron is also part of many other proteins and enzymes. Your body needs the right amount of iron. If you have too little iron, you may develop iron deficiency anemia. Causes of low iron levels include blood loss, poor diet, or an inability to absorb enough iron from foods. People at higher risk of having too little iron are young children and women who are pregnant or have periods. Too much iron can damage your body. Taking too many iron supplements can cause iron poisoning.", "cues": ["do you have information about iron", "iron information"]}, {"id": "medquad-MPlusHealthTopics-0000533-1", "topic": "arthritis", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Juvenile Arthritis?", "url": "https://www.nlm.nih.gov/medlineplus/juvenilearthritis.html", "retrieved": "2026-08-14", "body": "Juvenile arthritis (JA) is arthritis that happens in children. It causes joint swelling, pain, stiffness, and loss of motion. It can affect any joint, but is more common in the knees, hands, and feet. In some cases it can affect internal organs as well. The most common type of JA that children get is juvenile idiopathic arthritis. There are several other forms of arthritis affecting children. One early sign of JA may be limping in the morning. Symptoms can come and go. Some children have just one or two flare-ups. Others have symptoms that never go away. JA can cause growth problems and eye inflammation in some children. No one knows exactly what causes JA.", "cues": ["what is (are) juvenile arthritis?", "juvenile arthritis information"]}, {"id": "medquad-MPlusHealthTopics-0000547-1", "topic": "eye", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Laser Eye Surgery", "url": "https://www.nlm.nih.gov/medlineplus/lasereyesurgery.html", "retrieved": "2026-08-14", "body": "Summary : For many people, laser eye surgery can correct their vision so they no longer need glasses or contact lenses. Laser eye surgery reshapes the cornea, the clear front part of the eye. This changes its focusing power. There are different types of laser eye surgery. LASIK - laser-assisted in situ keratomileusis - is one of the most common. Many patients who have LASIK end up with 20/20 vision. But, like all medical procedures, it has both risks and benefits. Only your eye doctor can tell if you are a good candidate for laser eye surgery.", "cues": ["do you have information about laser eye surgery", "laser eye surgery information"]}, {"id": "medquad-MPlusHealthTopics-0000548-1", "topic": "allergy", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Latex Allergy?", "url": "https://www.nlm.nih.gov/medlineplus/latexallergy.html", "retrieved": "2026-08-14", "body": "Latex is a milky fluid that comes from the tropical rubber tree. Hundreds of everyday products contain latex. Repeated exposure to a protein in natural latex can make you more likely to develop a latex allergy. If your immune system detects the protein, a reaction can start in minutes. You could get a rash or asthma. In rare cases you could have a severe reaction called anaphylaxis. Your doctor may use a physical exam and skin and blood tests to diagnose it. There are medicines to treat a reaction, but it is best to try to avoid latex. Common latex products include - Gloves - Condoms - Balloons - Rubber bands - Shoe soles - Pacifiers You can find latex-free versions of these products.", "cues": ["what is (are) latex allergy?", "latex allergy information"]}, {"id": "medquad-MPlusHealthTopics-0000559-1", "topic": "infection", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Listeria Infections?", "url": "https://www.nlm.nih.gov/medlineplus/listeriainfections.html", "retrieved": "2026-08-14", "body": "Listeriosis is a foodborne illness caused by Listeria monocytogenes, bacteria found in soil and water. It can be in a variety of raw foods as well as in processed foods and foods made from unpasteurized milk. Listeria is unlike many other germs because it can grow even in the cold temperature of the refrigerator. Symptoms include fever and chills, headache, upset stomach and vomiting. Treatment is with antibiotics. Anyone can get the illness. But it is most likely to affect pregnant women and unborn babies, older adults, and people with weak immune systems.", "cues": ["what is (are) listeria infections?", "listeria infections information"]}, {"id": "medquad-MPlusHealthTopics-0000599-1", "topic": "infection", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Meningococcal Infections?", "url": "https://www.nlm.nih.gov/medlineplus/meningococcalinfections.html", "retrieved": "2026-08-14", "body": "Meningococci are a type of bacteria that cause serious infections. The most common infection is meningitis, which is an inflammation of the thin tissue that surrounds the brain and spinal cord. Meningococci can also cause other problems, including a serious bloodstream infection called sepsis. Meningococcal infections can spread from person to person. Risk factors include - Age - it is more common in infants, teens, and young adults - Living in close quarters, such as in college dorms or military settings - Certain medical conditions, such as not having a spleen - Travel to areas where meningococcal disease is common In its early stages, you may have flu-like symptoms and a stiff neck.", "cues": ["what is (are) meningococcal infections?", "meningococcal infections information"]}, {"id": "medquad-MPlusHealthTopics-0000600-1", "topic": "menopause", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Menopause?", "url": "https://www.nlm.nih.gov/medlineplus/menopause.html", "retrieved": "2026-08-14", "body": "Menopause is the time in a woman's life when her period stops. It usually occurs naturally, most often after age 45. Menopause happens because the woman's ovaries stop producing the hormones estrogen and progesterone. A woman has reached menopause when she has not had a period for one year. Changes and symptoms can start several years earlier. They include - A change in periods - shorter or longer, lighter or heavier, with more or less time in between - Hot flashes and/or night sweats - Trouble sleeping - Vaginal dryness - Mood swings - Trouble focusing - Less hair on head, more on face Some symptoms require treatment. Talk to your doctor about how to best manage menopause.", "cues": ["what is (are) menopause?", "menopause information"]}, {"id": "medquad-MPlusHealthTopics-0000601-1", "topic": "menstruation", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Menstruation?", "url": "https://www.nlm.nih.gov/medlineplus/menstruation.html", "retrieved": "2026-08-14", "body": "Menstruation, or period, is normal vaginal bleeding that occurs as part of a woman's monthly cycle. Every month, your body prepares for pregnancy. If no pregnancy occurs, the uterus, or womb, sheds its lining. The menstrual blood is partly blood and partly tissue from inside the uterus. It passes out of the body through the vagina. Periods usually start between age 11 and 14 and continue until menopause at about age 51. They usually last from three to five days.", "cues": ["what is (are) menstruation?", "menstruation information"]}, {"id": "medquad-MPlusHealthTopics-0000603-1", "topic": "mental health", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Mental Health", "url": "https://www.nlm.nih.gov/medlineplus/mentalhealth.html", "retrieved": "2026-08-14", "body": "Summary : Mental health includes our emotional, psychological, and social well-being. It affects how we think, feel and act as we cope with life. It also helps determine how we handle stress, relate to others, and make choices. Mental health is important at every stage of life, from childhood and adolescence through adulthood. Mental illnesses are serious disorders which can affect your thinking, mood, and behavior. There are many causes of mental disorders. Your genes and family history may play a role. Your life experiences, such as stress or a history of abuse, may also matter. Biological factors can also be part of the cause. Mental disorders are common, but treatments are available.", "cues": ["do you have information about mental health", "mental health information"]}, {"id": "medquad-MPlusHealthTopics-0000610-1", "topic": "migraine", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Migraine?", "url": "https://www.nlm.nih.gov/medlineplus/migraine.html", "retrieved": "2026-08-14", "body": "If you suffer from migraine headaches, you're not alone. About 12 percent of the U.S. population gets them. Migraines are recurring attacks of moderate to severe pain. The pain is throbbing or pulsing, and is often on one side of the head. During migraines, people are very sensitive to light and sound. They may also become nauseated and vomit. Migraine is three times more common in women than in men. Some people can tell when they are about to have a migraine because they see flashing lights or zigzag lines or they temporarily lose their vision. Many things can trigger a migraine.", "cues": ["what is (are) migraine?", "migraine information"]}, {"id": "medquad-MPlusHealthTopics-0000629-1", "topic": "muscle cramps", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Muscle Cramps?", "url": "https://www.nlm.nih.gov/medlineplus/musclecramps.html", "retrieved": "2026-08-14", "body": "Muscle cramps are sudden, involuntary contractions or spasms in one or more of your muscles. They often occur after exercise or at night, lasting a few seconds to several minutes. It is a very common muscle problem. Muscle cramps can be caused by nerves that malfunction. Sometimes this malfunction is due to a health problem, such as a spinal cord injury or a pinched nerve in the neck or back. Other causes are - Straining or overusing a muscle - Dehydration - A lack of minerals in your diet or the depletion of minerals in your body - Not enough blood getting to your muscles Cramps can be very painful. Stretching or gently massaging the muscle can relieve this pain.", "cues": ["what is (are) muscle cramps?", "muscle cramps information"]}, {"id": "medquad-MPlusHealthTopics-0000640-1", "topic": "nausea", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Nausea and Vomiting?", "url": "https://www.nlm.nih.gov/medlineplus/nauseaandvomiting.html", "retrieved": "2026-08-14", "body": "Nausea is an uneasy or unsettled feeling in the stomach together with an urge to vomit. Nausea and vomiting, or throwing up, are not diseases. They can be symptoms of many different conditions. These include morning sickness during pregnancy, infections, migraine headaches, motion sickness, food poisoning, cancer chemotherapy or other medicines. For vomiting in children and adults, avoid solid foods until vomiting has stopped for at least six hours. Then work back to a normal diet. Drink small amounts of clear liquids to avoid dehydration. Nausea and vomiting are common. Usually, they are not serious.", "cues": ["what is (are) nausea and vomiting?", "nausea and vomiting information"]}, {"id": "medquad-MPlusHealthTopics-0000653-1", "topic": "nutrition", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Nutrition", "url": "https://www.nlm.nih.gov/medlineplus/nutrition.html", "retrieved": "2026-08-14", "body": "Summary : Food provides the energy and nutrients you need to be healthy. Nutrients include proteins, carbohydrates, fats, vitamins, minerals, and water. Healthy eating is not hard. The key is to - Eat a variety of foods, including vegetables, fruits, and whole-grain products - Eat lean meats, poultry, fish, beans, and low-fat dairy products - Drink lots of water - Limit salt, sugar, alcohol, saturated fat, and trans fat in your diet Saturated fats are usually fats that come from animals. Look for trans fat on the labels of processed foods, margarines, and shortenings. Centers for Disease Control and Prevention", "cues": ["do you have information about nutrition", "nutrition information"]}, {"id": "medquad-MPlusHealthTopics-0000654-1", "topic": "nutrition", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Nutrition for Seniors", "url": "https://www.nlm.nih.gov/medlineplus/nutritionforseniors.html", "retrieved": "2026-08-14", "body": "Summary : Food provides the energy and nutrients you need to be healthy. Nutrients include proteins, carbohydrates, fats, vitamins, minerals and water. Studies show that a good diet in your later years reduces your risk of osteoporosis, high blood pressure, heart diseases and certain cancers. As you age, you might need less energy. But you still need just as many of the nutrients in food.", "cues": ["do you have information about nutrition for seniors", "nutrition for seniors information"]}, {"id": "medquad-MPlusHealthTopics-0000655-1", "topic": "nutrition", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Nutritional Support", "url": "https://www.nlm.nih.gov/medlineplus/nutritionalsupport.html", "retrieved": "2026-08-14", "body": "Summary : Nutritional support is therapy for people who cannot get enough nourishment by eating or drinking. You may need it if you - Can't swallow - Have problems with your appetite - Are severely malnourished - Can't absorb nutrients through your digestive system You receive nutritional support through a needle or catheter placed in your vein or with a feeding tube, which goes into your stomach.", "cues": ["do you have information about nutritional support", "nutritional support information"]}, {"id": "medquad-MPlusHealthTopics-0000656-1", "topic": "obesity", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Obesity?", "url": "https://www.nlm.nih.gov/medlineplus/obesity.html", "retrieved": "2026-08-14", "body": "Obesity means having too much body fat. It is different from being overweight, which means weighing too much. The weight may come from muscle, bone, fat, and/or body water. Both terms mean that a person's weight is greater than what's considered healthy for his or her height. Obesity occurs over time when you eat more calories than you use. The balance between calories-in and calories-out differs for each person. Factors that might affect your weight include your genetic makeup, overeating, eating high-fat foods, and not being physically active. Being obese increases your risk of diabetes, heart disease, stroke, arthritis, and some cancers.", "cues": ["what is (are) obesity?", "obesity information"]}, {"id": "medquad-MPlusHealthTopics-0000657-1", "topic": "obesity", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Obesity in Children?", "url": "https://www.nlm.nih.gov/medlineplus/obesityinchildren.html", "retrieved": "2026-08-14", "body": "Obesity means having too much body fat. It is different from being overweight, which means weighing too much. Both terms mean that a person's weight is greater than what's considered healthy for his or her height. Children grow at different rates, so it isn't always easy to know when a child is obese or overweight. Ask your health care provider to check whether your child's weight and height are in a healthy range. If a weight-loss program is necessary, involve the whole family in healthy habits so your child doesn't feel singled out.", "cues": ["what is (are) obesity in children?", "obesity in children information"]}, {"id": "medquad-MPlusHealthTopics-0000666-1", "topic": "arthritis", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Osteoarthritis?", "url": "https://www.nlm.nih.gov/medlineplus/osteoarthritis.html", "retrieved": "2026-08-14", "body": "Osteoarthritis is the most common form of arthritis. It causes pain, swelling, and reduced motion in your joints. It can occur in any joint, but usually it affects your hands, knees, hips or spine. Osteoarthritis breaks down the cartilage in your joints. Cartilage is the slippery tissue that covers the ends of bones in a joint. Healthy cartilage absorbs the shock of movement. When you lose cartilage, your bones rub together. Over time, this rubbing can permanently damage the joint. Risk factors for osteoarthritis include - Being overweight - Getting older - Injuring a joint No single test can diagnose osteoarthritis.", "cues": ["what is (are) osteoarthritis?", "osteoarthritis information"]}, {"id": "medquad-MPlusHealthTopics-0000680-1", "topic": "pain", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Pain?", "url": "https://www.nlm.nih.gov/medlineplus/pain.html", "retrieved": "2026-08-14", "body": "Pain is a feeling triggered in the nervous system. Pain may be sharp or dull. It may come and go, or it may be constant. You may feel pain in one area of your body, such as your back, abdomen or chest or you may feel pain all over, such as when your muscles ache from the flu. Pain can be helpful in diagnosing a problem. Without pain, you might seriously hurt yourself without knowing it, or you might not realize you have a medical problem that needs treatment. Once you take care of the problem, pain usually goes away. However, sometimes pain goes on for weeks, months or even years. This is called chronic pain. Sometimes chronic pain is due to an ongoing cause, such as cancer or arthritis.", "cues": ["what is (are) pain?", "pain information"]}, {"id": "medquad-MPlusHealthTopics-0000681-1", "topic": "pain", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Pain Relievers", "url": "https://www.nlm.nih.gov/medlineplus/painrelievers.html", "retrieved": "2026-08-14", "body": "Summary : Pain relievers are medicines that reduce or relieve headaches, sore muscles, arthritis, or other aches and pains. There are many different pain medicines, and each one has advantages and risks. Some types of pain respond better to certain medicines than others. Each person may also have a slightly different response to a pain reliever. Over-the-counter (OTC) medicines are good for many types of pain. There are two main types of OTC pain medicines: acetaminophen (Tylenol) and nonsteroidal anti-inflammatory drugs (NSAIDs). Aspirin, naproxen (Aleve), and ibuprofen (Advil, Motrin) are examples of OTC NSAIDs.", "cues": ["do you have information about pain relievers", "pain relievers information"]}, {"id": "medquad-MPlusHealthTopics-0000687-1", "topic": "panic disorder", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Panic Disorder?", "url": "https://www.nlm.nih.gov/medlineplus/panicdisorder.html", "retrieved": "2026-08-14", "body": "Panic disorder is a type of anxiety disorder. It causes panic attacks, which are sudden feelings of terror when there is no real danger. You may feel as if you are losing control. You may also have physical symptoms, such as - Fast heartbeat - Chest or stomach pain - Breathing difficulty - Weakness or dizziness - Sweating - Feeling hot or a cold chill - Tingly or numb hands Panic attacks can happen anytime, anywhere, and without warning. You may live in fear of another attack and may avoid places where you have had an attack. For some people, fear takes over their lives and they cannot leave their homes. Panic disorder is more common in women than men.", "cues": ["what is (are) panic disorder?", "panic disorder information"]}, {"id": "medquad-MPlusHealthTopics-0000690-1", "topic": "thyroid", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Parathyroid Disorders?", "url": "https://www.nlm.nih.gov/medlineplus/parathyroiddisorders.html", "retrieved": "2026-08-14", "body": "Most people have four pea-sized glands, called parathyroid glands, on the thyroid gland in the neck. Though their names are similar, the thyroid and parathyroid glands are completely different. The parathyroid glands make parathyroid hormone (PTH), which helps your body keep the right balance of calcium and phosphorous. If your parathyroid glands make too much or too little hormone, it disrupts this balance. If they secrete extra PTH, you have hyperparathyroidism, and your blood calcium rises. In many cases, a benign tumor on a parathyroid gland makes it overactive. Or, the extra hormones can come from enlarged parathyroid glands. Very rarely, the cause is cancer.", "cues": ["what is (are) parathyroid disorders?", "parathyroid disorders information"]}, {"id": "medquad-MPlusHealthTopics-0000696-1", "topic": "pain", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Pelvic Pain?", "url": "https://www.nlm.nih.gov/medlineplus/pelvicpain.html", "retrieved": "2026-08-14", "body": "Pelvic pain occurs mostly in the lower abdomen area. The pain might be steady, or it might come and go. If the pain is severe, it might get in the way of your daily activities. If you're a woman, you might feel a dull pain during your period. It could also happen during sex. Pelvic pain can be a sign that there is a problem with one of the organs in your pelvic area, such as the uterus, ovaries, fallopian tubes, cervix or vagina. It could also be a symptom of infection, or a problem with the urinary tract, lower intestines, rectum, muscle or bone. If you're a man, the cause is often a problem with the prostate. You might have to undergo a lot of medical tests to find the cause of the pain.", "cues": ["what is (are) pelvic pain?", "pelvic pain information"]}, {"id": "medquad-MPlusHealthTopics-0000713-1", "topic": "eye", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Pinkeye?", "url": "https://www.nlm.nih.gov/medlineplus/pinkeye.html", "retrieved": "2026-08-14", "body": "Conjunctivitis is the medical name for pink eye. It involves inflammation of the outer layer of the eye and inside of the eyelid. It can cause swelling, itching, burning, discharge, and redness. Causes include - Bacterial or viral infection - Allergies - Substances that cause irritation - Contact lens products, eye drops, or eye ointments Pinkeye usually does not affect vision. Infectious pink eye can easily spread from one person to another. The infection will clear in most cases without medical care, but bacterial pinkeye needs treatment with antibiotic eye drops or ointment. NIH: National Eye Institute", "cues": ["what is (are) pinkeye?", "pinkeye information"]}, {"id": "medquad-MPlusHealthTopics-0000723-1", "topic": "pneumonia", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Pneumonia?", "url": "https://www.nlm.nih.gov/medlineplus/pneumonia.html", "retrieved": "2026-08-14", "body": "Pneumonia is an infection in one or both of the lungs. Many germs, such as bacteria, viruses, and fungi, can cause pneumonia. You can also get pneumonia by inhaling a liquid or chemical. People most at risk are older than 65 or younger than 2 years of age, or already have health problems. Symptoms of pneumonia vary from mild to severe.", "cues": ["what is (are) pneumonia?", "pneumonia information"]}, {"id": "medquad-MPlusHealthTopics-0000730-1", "topic": "stress", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Post-Traumatic Stress Disorder?", "url": "https://www.nlm.nih.gov/medlineplus/posttraumaticstressdisorder.html", "retrieved": "2026-08-14", "body": "Post-traumatic stress disorder (PTSD) is a real illness. You can get PTSD after living through or seeing a traumatic event, such as war, a hurricane, sexual assault, physical abuse, or a bad accident. PTSD makes you feel stressed and afraid after the danger is over. It affects your life and the people around you. PTSD can cause problems like - Flashbacks, or feeling like the event is happening again - Trouble sleeping or nightmares - Feeling alone - Angry outbursts - Feeling worried, guilty, or sad PTSD starts at different times for different people. Signs of PTSD may start soon after a frightening event and then continue.", "cues": ["what is (are) post-traumatic stress disorder?", "post-traumatic stress disorder information"]}, {"id": "medquad-MPlusHealthTopics-0000732-1", "topic": "depression", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Postpartum Depression?", "url": "https://www.nlm.nih.gov/medlineplus/postpartumdepression.html", "retrieved": "2026-08-14", "body": "Many women have the baby blues after childbirth. If you have the baby blues, you may have mood swings, feel sad, anxious or overwhelmed, have crying spells, lose your appetite, or have trouble sleeping. The baby blues most often go away within a few days or a week. The symptoms are not severe and do not need treatment. The symptoms of postpartum depression last longer and are more severe. You may also feel hopeless and worthless, and lose interest in the baby. You may have thoughts of hurting yourself or the baby. Very rarely, new mothers develop something even more serious. They may have hallucinations or try to hurt themselves or the baby.", "cues": ["what is (are) postpartum depression?", "postpartum depression information"]}, {"id": "medquad-MPlusHealthTopics-0000738-1", "topic": "pregnancy", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Pregnancy and Medicines", "url": "https://www.nlm.nih.gov/medlineplus/pregnancyandmedicines.html", "retrieved": "2026-08-14", "body": "Summary : Not all medicines are safe to take when you are pregnant. Some medicines can harm your baby. That includes over-the-counter or prescription drugs, herbs, and supplements. Always speak with your health care provider before you start or stop any medicine. Not using medicine that you need may be more harmful to you and your baby than using the medicine. For example, many pregnant women take prescription medicines for health problems like diabetes, asthma, seizures, and heartburn. The decision about whether or not to take a medicine depends on the risks and benefits. You and your health care provider should make this choice together. Pregnant women should not take regular vitamins.", "cues": ["do you have information about pregnancy and medicines", "pregnancy and medicines information"]}, {"id": "medquad-MPlusHealthTopics-0000739-1", "topic": "nutrition", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Pregnancy and Nutrition", "url": "https://www.nlm.nih.gov/medlineplus/pregnancyandnutrition.html", "retrieved": "2026-08-14", "body": "Summary : When you're pregnant, eating healthy foods is more important than ever. You need more protein, iron, calcium, and folic acid than you did before pregnancy. You also need more calories. But \"eating for two\" doesn't mean eating twice as much. It means that the foods you eat are the main source of nutrients for your baby. Sensible, balanced meals will be best for you and your baby. You should gain weight gradually during your pregnancy, with most of the weight gained in the last trimester.", "cues": ["do you have information about pregnancy and nutrition", "pregnancy and nutrition information"]}, {"id": "medquad-MPlusHealthTopics-0000749-1", "topic": "ear", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Progressive Supranuclear Palsy?", "url": "https://www.nlm.nih.gov/medlineplus/progressivesupranuclearpalsy.html", "retrieved": "2026-08-14", "body": "Progressive supranuclear palsy (PSP) is a rare brain disease. It affects brain cells that control the movement of your eyes. This leads to serious and permanent problems with balance and the way you walk. It usually occurs in middle-aged or elderly people. Symptoms are very different in each person, but may include personality changes, speech, vision and swallowing problems. Doctors sometimes confuse PSP with Parkinson's disease or Alzheimer's disease. PSP has no cure and no effective treatments. Walking aids, special glasses and certain medicines might help somewhat. Although the disease gets worse over time, it isn't fatal on its own.", "cues": ["what is (are) progressive supranuclear palsy?", "progressive supranuclear palsy information"]}, {"id": "medquad-MPlusHealthTopics-0000754-1", "topic": "arthritis", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Psoriatic Arthritis?", "url": "https://www.nlm.nih.gov/medlineplus/psoriaticarthritis.html", "retrieved": "2026-08-14", "body": "Psoriasis is a skin disease that causes itchy or sore patches of thick, red skin with silvery scales. You usually get them on your elbows, knees, scalp, back, face, palms and feet, but they can show up on other parts of your body. Some people with psoriasis have psoriatic arthritis. It causes pain, stiffness, and swelling of the joints. It is often mild, but can sometimes be serious and affect many joints. The joint and skin problems don't always happen at the same time. Your doctor will do a physical exam and imaging tests to diagnose psoriatic arthritis. There is no cure, but medicines can help control inflammation and pain.", "cues": ["what is (are) psoriatic arthritis?", "psoriatic arthritis information"]}, {"id": "medquad-MPlusHealthTopics-0000759-1", "topic": "hypertension", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Pulmonary Hypertension?", "url": "https://www.nlm.nih.gov/medlineplus/pulmonaryhypertension.html", "retrieved": "2026-08-14", "body": "Pulmonary hypertension (PH) is high blood pressure in the arteries to your lungs. It is a serious condition. If you have it, the blood vessels that carry blood from your heart to your lungs become hard and narrow. Your heart has to work harder to pump the blood through. Over time, your heart weakens and cannot do its job and you can develop heart failure. Symptoms of PH include - Shortness of breath during routine activity, such as climbing two flights of stairs - Tiredness - Chest pain - A racing heartbeat - Pain on the upper right side of the abdomen - Decreased appetite As PH worsens, you may find it hard to do any physical activities. There are two main kinds of PH.", "cues": ["what is (are) pulmonary hypertension?", "pulmonary hypertension information"]}, {"id": "medquad-MPlusHealthTopics-0000761-1", "topic": "smoking", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Quitting Smoking", "url": "https://www.nlm.nih.gov/medlineplus/quittingsmoking.html", "retrieved": "2026-08-14", "body": "Summary : Tobacco use is the most common preventable cause of death. About half of the people who don't quit smoking will die of smoking-related problems. Quitting smoking is important for your health. Soon after you quit, your circulation begins to improve, and your blood pressure starts to return to normal. Your sense of smell and taste return, and it's easier for you to breathe. In the long term, giving up tobacco can help you live longer. Your risk of getting cancer decreases with each year you stay smoke-free. Quitting is not easy. You may have short-term affects such as weight gain, irritability, and anxiety. Some people try several times before they succeed.", "cues": ["do you have information about quitting smoking", "quitting smoking information"]}, {"id": "medquad-MPlusHealthTopics-0000768-1", "topic": "rash", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Rashes?", "url": "https://www.nlm.nih.gov/medlineplus/rashes.html", "retrieved": "2026-08-14", "body": "A rash is an area of irritated or swollen skin. Many rashes are itchy, red, painful, and irritated. Some rashes can also lead to blisters or patches of raw skin. Rashes are a symptom of many different medical problems. Other causes include irritating substances and allergies. Certain genes can make people more likely to get rashes. Contact dermatitis is a common type of rash. It causes redness, itching, and sometimes small bumps. You get the rash where you have touched an irritant, such as a chemical, or something you are allergic to, like poison ivy. Some rashes develop right away. Others form over several days.", "cues": ["what is (are) rashes?", "rashes information"]}, {"id": "medquad-MPlusHealthTopics-0000775-1", "topic": "infection", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Respiratory Syncytial Virus Infections?", "url": "https://www.nlm.nih.gov/medlineplus/respiratorysyncytialvirusinfections.html", "retrieved": "2026-08-14", "body": "Respiratory syncytial virus (RSV) causes mild, cold-like symptoms in adults and older healthy children. It can cause serious problems in young babies, including pneumonia and severe breathing problems. Premature babies and those with other health problems have the highest risk. A child with RSV may have a fever, stuffy nose, cough, and trouble breathing. Lab tests can tell if your child has the virus. There is no specific treatment. You should give your child fluids to prevent dehydration. If needed, you can also give a pain reliever (not aspirin) for fever and headache. RSV easily spreads from person to person.", "cues": ["what is (are) respiratory syncytial virus infections?", "respiratory syncytial virus infections information"]}, {"id": "medquad-MPlusHealthTopics-0000782-1", "topic": "arthritis", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Rheumatoid Arthritis?", "url": "https://www.nlm.nih.gov/medlineplus/rheumatoidarthritis.html", "retrieved": "2026-08-14", "body": "Rheumatoid arthritis (RA) is a form of arthritis that causes pain, swelling, stiffness and loss of function in your joints. It can affect any joint but is common in the wrist and fingers. More women than men get rheumatoid arthritis. It often starts in middle age and is most common in older people. You might have the disease for only a short time, or symptoms might come and go. The severe form can last a lifetime. Rheumatoid arthritis is different from osteoarthritis, the common arthritis that often comes with older age. RA can affect body parts besides joints, such as your eyes, mouth and lungs.", "cues": ["what is (are) rheumatoid arthritis?", "rheumatoid arthritis information"]}, {"id": "medquad-MPlusHealthTopics-0000815-1", "topic": "anemia", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Sickle Cell Anemia?", "url": "https://www.nlm.nih.gov/medlineplus/sicklecellanemia.html", "retrieved": "2026-08-14", "body": "Sickle cell anemia is a disease in which your body produces abnormally shaped red blood cells. The cells are shaped like a crescent or sickle. They don't last as long as normal, round red blood cells. This leads to anemia. The sickle cells also get stuck in blood vessels, blocking blood flow. This can cause pain and organ damage. A genetic problem causes sickle cell anemia. People with the disease are born with two sickle cell genes, one from each parent. If you only have one sickle cell gene, it's called sickle cell trait. About 1 in 12 African Americans has sickle cell trait. The most common symptoms are pain and problems from anemia. Anemia can make you feel tired or weak.", "cues": ["what is (are) sickle cell anemia?", "sickle cell anemia information"]}, {"id": "medquad-MPlusHealthTopics-0000816-1", "topic": "sinusitis", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Sinusitis?", "url": "https://www.nlm.nih.gov/medlineplus/sinusitis.html", "retrieved": "2026-08-14", "body": "Sinusitis means your sinuses are inflamed. The cause can be an infection or another problem. Your sinuses are hollow air spaces within the bones surrounding the nose. They produce mucus, which drains into the nose. If your nose is swollen, this can block the sinuses and cause pain. There are several types of sinusitis, including - Acute, which lasts up to 4 weeks - Subacute, which lasts 4 to 12 weeks - Chronic, which lasts more than 12 weeks and can continue for months or even years - Recurrent, with several attacks within a year Acute sinusitis often starts as a cold, which then turns into a bacterial infection.", "cues": ["what is (are) sinusitis?", "sinusitis information"]}, {"id": "medquad-MPlusHealthTopics-0000818-1", "topic": "skin", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Skin Aging", "url": "https://www.nlm.nih.gov/medlineplus/skinaging.html", "retrieved": "2026-08-14", "body": "Summary : Your skin changes as you age. You might notice wrinkles, age spots and dryness. Your skin also becomes thinner and loses fat, making it less plump and smooth. It might take longer to heal, too. Sunlight is a major cause of skin aging. You can protect yourself by staying out of the sun when it is strongest, using sunscreen with an SPF of 15 or higher, wearing protective clothing, and avoiding sunlamps and tanning beds. Cigarette smoking also contributes to wrinkles. The wrinkling increases with the amount of cigarettes and number of years a person has smoked.", "cues": ["do you have information about skin aging", "skin aging information"]}, {"id": "medquad-MPlusHealthTopics-0000819-1", "topic": "skin", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Skin Cancer?", "url": "https://www.nlm.nih.gov/medlineplus/skincancer.html", "retrieved": "2026-08-14", "body": "Skin cancer is the most common form of cancer in the United States. The two most common types are basal cell cancer and squamous cell cancer. They usually form on the head, face, neck, hands, and arms. Another type of skin cancer, melanoma, is more dangerous but less common. Anyone can get skin cancer, but it is more common in people who - Spend a lot of time in the sun or have been sunburned - Have light-colored skin, hair and eyes - Have a family member with skin cancer - Are over age 50 You should have your doctor check any suspicious skin markings and any changes in the way your skin looks. Treatment is more likely to work well when cancer is found early.", "cues": ["what is (are) skin cancer?", "skin cancer information"]}, {"id": "medquad-MPlusHealthTopics-0000820-1", "topic": "skin", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Skin Conditions?", "url": "https://www.nlm.nih.gov/medlineplus/skinconditions.html", "retrieved": "2026-08-14", "body": "Your skin is your body's largest organ. It covers and protects your body. Your skin - Holds body fluids in, preventing dehydration - Keeps harmful microbes out, preventing infections - Helps you feel things like heat, cold, and pain - Keeps your body temperature even - Makes vitamin D when the sun shines on it Anything that irritates, clogs, or inflames your skin can cause symptoms such as redness, swelling, burning, and itching. Allergies, irritants, your genetic makeup, and certain diseases and immune system problems can cause rashes, hives, and other skin conditions. Many skin problems, such as acne, also affect your appearance.", "cues": ["what is (are) skin conditions?", "skin conditions information"]}, {"id": "medquad-MPlusHealthTopics-0000821-1", "topic": "skin", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Skin Infections?", "url": "https://www.nlm.nih.gov/medlineplus/skininfections.html", "retrieved": "2026-08-14", "body": "Your skin helps protect you from germs, but sometimes it can get infected by them. Some common types of skin infections are - Bacterial: Cellulitis and impetigo. Staphylococcal infections can also affect the skin. - Viral: Shingles, warts, and herpes simplex - Fungal: Athlete's foot and yeast infections - Parasitic: Body lice, head lice, and scabies Treatment of skin infections depends on the cause.", "cues": ["what is (are) skin infections?", "skin infections information"]}, {"id": "medquad-MPlusHealthTopics-0000822-1", "topic": "skin", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Skin Pigmentation Disorders?", "url": "https://www.nlm.nih.gov/medlineplus/skinpigmentationdisorders.html", "retrieved": "2026-08-14", "body": "Pigmentation means coloring. Skin pigmentation disorders affect the color of your skin. Your skin gets its color from a pigment called melanin. Special cells in the skin make melanin. When these cells become damaged or unhealthy, it affects melanin production. Some pigmentation disorders affect just patches of skin. Others affect your entire body. If your body makes too much melanin, your skin gets darker. Pregnancy, Addison's disease, and sun exposure all can make your skin darker. If your body makes too little melanin, your skin gets lighter. Vitiligo is a condition that causes patches of light skin. Albinism is a genetic condition affecting a person's skin.", "cues": ["what is (are) skin pigmentation disorders?", "skin pigmentation disorders information"]}, {"id": "medquad-MPlusHealthTopics-0000823-1", "topic": "sleep", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Sleep Apnea?", "url": "https://www.nlm.nih.gov/medlineplus/sleepapnea.html", "retrieved": "2026-08-14", "body": "Sleep apnea is a common disorder that causes your breathing to stop or get very shallow. Breathing pauses can last from a few seconds to minutes. They may occur 30 times or more an hour. The most common type is obstructive sleep apnea. It causes your airway to collapse or become blocked during sleep. Normal breathing starts again with a snort or choking sound. People with sleep apnea often snore loudly. However, not everyone who snores has sleep apnea. You are more at risk for sleep apnea if you are overweight, male, or have a family history or small airways. Children with enlarged tonsils may also get it.", "cues": ["what is (are) sleep apnea?", "sleep apnea information"]}, {"id": "medquad-MPlusHealthTopics-0000824-1", "topic": "sleep", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Sleep Disorders?", "url": "https://www.nlm.nih.gov/medlineplus/sleepdisorders.html", "retrieved": "2026-08-14", "body": "Is it hard for you to fall asleep or stay asleep through the night? Do you wake up feeling tired or feel very sleepy during the day, even if you have had enough sleep? You might have a sleep disorder. The most common kinds are - Insomnia - a hard time falling or staying asleep - Sleep apnea - breathing interruptions during sleep - Restless legs syndrome - a tingling or prickly sensation in the legs - Narcolepsy - daytime \"sleep attacks\" Nightmares, night terrors, sleepwalking, sleep talking, head banging, wetting the bed and grinding your teeth are kinds of sleep problems called parasomnias. There are treatments for most sleep disorders. Sometimes just having regular sleep habits can help.", "cues": ["what is (are) sleep disorders?", "sleep disorders information"]}, {"id": "medquad-MPlusHealthTopics-0000828-1", "topic": "smoking", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Smoking?", "url": "https://www.nlm.nih.gov/medlineplus/smoking.html", "retrieved": "2026-08-14", "body": "There's no way around it. Smoking is bad for your health. Smoking harms nearly every organ of the body. Cigarette smoking causes 87 percent of lung cancer deaths. It is also responsible for many other cancers and health problems. These include lung disease, heart and blood vessel disease, stroke and cataracts. Women who smoke have a greater chance of certain pregnancy problems or having a baby die from sudden infant death syndrome (SIDS). Your smoke is also bad for other people - they breathe in your smoke secondhand and can get many of the same problems as smokers do. E-cigarettes often look like cigarettes, but they work differently. They are battery-operated smoking devices.", "cues": ["what is (are) smoking?", "smoking information"]}, {"id": "medquad-MPlusHealthTopics-0000829-1", "topic": "smoking", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Smoking and Youth?", "url": "https://www.nlm.nih.gov/medlineplus/smokingandyouth.html", "retrieved": "2026-08-14", "body": "Smoking cigarettes has many health risks for everyone. However, the younger you are when you start smoking, the more problems it can cause. People who start smoking before the age of 21 have the hardest time quitting. Teens who smoke are also more likely to use alcohol and illegal drugs. The problem is not just cigarettes. Spit tobacco, e-cigarettes, and cigars are not safe alternatives to cigarettes. Low-tar and additive-free tobacco products are not safe either. Young people who do not start using tobacco by age 18 will most likely never start. Centers for Disease Control and Prevention", "cues": ["what is (are) smoking and youth?", "smoking and youth information"]}, {"id": "medquad-MPlusHealthTopics-0000833-1", "topic": "sore throat", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Sore Throat?", "url": "https://www.nlm.nih.gov/medlineplus/sorethroat.html", "retrieved": "2026-08-14", "body": "Your throat is a tube that carries food to your esophagus and air to your windpipe and larynx (also called the voice box). The technical name for the throat is pharynx. You can have a sore throat for many reasons. Often, colds and flu cause sore throats. Other causes can include: - Allergies - Mononucleosis - Smoking - Strep throat - Tonsillitis - an infection in the tonsils Treatment depends on the cause. Sucking on lozenges, drinking lots of liquids, and gargling may ease the pain. Over-the-counter pain relievers can also help, but children should not take aspirin.", "cues": ["what is (are) sore throat?", "sore throat information"]}, {"id": "medquad-MPlusHealthTopics-0000847-1", "topic": "sprains", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Sprains and Strains?", "url": "https://www.nlm.nih.gov/medlineplus/sprainsandstrains.html", "retrieved": "2026-08-14", "body": "A sprain is a stretched or torn ligament. Ligaments are tissues that connect bones at a joint. Falling, twisting, or getting hit can all cause a sprain. Ankle and wrist sprains are common. Symptoms include pain, swelling, bruising, and being unable to move your joint. You might feel a pop or tear when the injury happens. A strain is a stretched or torn muscle or tendon. Tendons are tissues that connect muscle to bone. Twisting or pulling these tissues can cause a strain. Strains can happen suddenly or develop over time. Back and hamstring muscle strains are common. Many people get strains playing sports. Symptoms include pain, muscle spasms, swelling, and trouble moving the muscle.", "cues": ["what is (are) sprains and strains?", "sprains and strains information"]}, {"id": "medquad-MPlusHealthTopics-0000853-1", "topic": "stomach", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Stomach Cancer?", "url": "https://www.nlm.nih.gov/medlineplus/stomachcancer.html", "retrieved": "2026-08-14", "body": "The stomach is an organ between the esophagus and the small intestine. It mixes food with stomach acid and helps digest protein. Stomach cancer mostly affects older people - two-thirds of people who have it are over age 65. Your risk of getting it is also higher if you - Have had a Helicobacter pylori infection - Have had stomach inflammation - Are a man - Eat lots of salted, smoked, or pickled foods - Smoke cigarettes - Have a family history of stomach cancer It is hard to diagnose stomach cancer in its early stages. Indigestion and stomach discomfort can be symptoms of early cancer, but other problems can cause the same symptoms.", "cues": ["what is (are) stomach cancer?", "stomach cancer information"]}, {"id": "medquad-MPlusHealthTopics-0000854-1", "topic": "stomach", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Stomach Disorders?", "url": "https://www.nlm.nih.gov/medlineplus/stomachdisorders.html", "retrieved": "2026-08-14", "body": "Your stomach is an organ between your esophagus and small intestine. It is where digestion of protein begins. The stomach has three tasks. It stores swallowed food. It mixes the food with stomach acids. Then it sends the mixture on to the small intestine. Most people have a problem with their stomach at one time or another. Indigestion and heartburn are common problems. You can relieve some stomach problems with over-the-counter medicines and lifestyle changes, such as avoiding fatty foods or eating more slowly. Other problems like peptic ulcers or GERD require medical attention.", "cues": ["what is (are) stomach disorders?", "stomach disorders information"]}, {"id": "medquad-MPlusHealthTopics-0000856-1", "topic": "stress", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Stress?", "url": "https://www.nlm.nih.gov/medlineplus/stress.html", "retrieved": "2026-08-14", "body": "Everyone feels stressed from time to time. Not all stress is bad. All animals have a stress response, and it can be life-saving. But chronic stress can cause both physical and mental harm. There are at least three different types of stress: - Routine stress related to the pressures of work, family, and other daily responsibilities - Stress brought about by a sudden negative change, such as losing a job, divorce, or illness - Traumatic stress, which happens when you are in danger of being seriously hurt or killed. Examples include a major accident, war, assault, or a natural disaster. This type of stress can cause post-traumatic stress disorder (PTSD).", "cues": ["what is (are) stress?", "stress information"]}, {"id": "medquad-MPlusHealthTopics-0000875-1", "topic": "mental health", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Teen Mental Health", "url": "https://www.nlm.nih.gov/medlineplus/teenmentalhealth.html", "retrieved": "2026-08-14", "body": "Summary : Being a teenager is hard. You're under stress to be liked, do well in school, get along with your family, and make big decisions. You can't avoid most of these pressures, and worrying about them is normal. But feeling very sad, hopeless or worthless could be warning signs of a mental health problem. Mental health problems are real, painful, and sometimes severe.", "cues": ["do you have information about teen mental health", "teen mental health information"]}, {"id": "medquad-MPlusHealthTopics-0000878-1", "topic": "pregnancy", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Teenage Pregnancy?", "url": "https://www.nlm.nih.gov/medlineplus/teenagepregnancy.html", "retrieved": "2026-08-14", "body": "Most teenage girls don't plan to get pregnant, but many do. Teen pregnancies carry extra health risks to both the mother and the baby. Often, teens don't get prenatal care soon enough, which can lead to problems later on. They have a higher risk for pregnancy-related high blood pressure and its complications. Risks for the baby include premature birth and a low birth weight.", "cues": ["what is (are) teenage pregnancy?", "teenage pregnancy information"]}, {"id": "medquad-MPlusHealthTopics-0000885-1", "topic": "vaccines", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Tetanus, Diphtheria, and Pertussis Vaccines?", "url": "https://www.nlm.nih.gov/medlineplus/tetanusdiphtheriaandpertussisvaccines.html", "retrieved": "2026-08-14", "body": "Tetanus, diphtheria, and pertussis (whooping cough) are serious bacterial infections. Tetanus causes painful tightening of the muscles, usually all over the body. It can lead to \"locking\" of the jaw. Diphtheria usually affects the nose and throat. Whooping cough causes uncontrollable coughing. Vaccines can protect you from these diseases. In the U.S., there are four combination vaccines: - DTaP prevents all three diseases. It is for children younger than seven years old. - Tdap also prevents all three. It is for older children and adults. - DT prevents diphtheria and tetanus. It is for children younger than seven who cannot tolerate the pertussis vaccine.", "cues": ["what is (are) tetanus, diphtheria, and pertussis vaccines?", "tetanus, diphtheria, and pertussis vaccines information"]}, {"id": "medquad-MPlusHealthTopics-0000891-1", "topic": "thyroid", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Thyroid Cancer?", "url": "https://www.nlm.nih.gov/medlineplus/thyroidcancer.html", "retrieved": "2026-08-14", "body": "Your thyroid is a butterfly-shaped gland in your neck, just above your collarbone. It makes hormones that help the body work normally. There are several types of cancer of the thyroid gland. You are at greater risk if you - Are between ages 25 and 65 - Are a woman - Are Asian - Have a family member who has had thyroid disease - Have had radiation treatments to your head or neck You should see a doctor if you have a lump or swelling in your neck. Doctors use a physical exam, blood tests, imaging tests, and a biopsy to diagnose thyroid cancer. Treatment depends on the type of cancer you have and how far the cancer has spread. Many patients receive a combination of treatments.", "cues": ["what is (are) thyroid cancer?", "thyroid cancer information"]}, {"id": "medquad-MPlusHealthTopics-0000892-1", "topic": "thyroid", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Thyroid Diseases?", "url": "https://www.nlm.nih.gov/medlineplus/thyroiddiseases.html", "retrieved": "2026-08-14", "body": "Your thyroid is a butterfly-shaped gland in your neck, just above your collarbone. It is one of your endocrine glands, which make hormones. Thyroid hormones control the rate of many activities in your body. These include how fast you burn calories and how fast your heart beats. All of these activities are your body's metabolism. Thyroid problems include - Goiter - enlargement of the thyroid gland - Hyperthyroidism - when your thyroid gland makes more thyroid hormones than your body needs - Hypothyroidism - when your thyroid gland does not make enough thyroid hormones - Thyroid cancer - Thyroid nodules - lumps in the thyroid gland - Thyroiditis - swelling of the thyroid Dept.", "cues": ["what is (are) thyroid diseases?", "thyroid diseases information"]}, {"id": "medquad-MPlusHealthTopics-0000898-1", "topic": "nutrition", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Toddler Nutrition", "url": "https://www.nlm.nih.gov/medlineplus/toddlernutrition.html", "retrieved": "2026-08-14", "body": "Summary : Food provides the energy and nutrients that young children need to be healthy. Toddlers are learning to feed themselves and to eat new foods. They should eat a variety of foods from all of the food groups. Each day, toddlers need enough nutrients, including - 7 milligrams of iron - 700 milligrams of calcium - 600 IU of vitamin D", "cues": ["do you have information about toddler nutrition", "toddler nutrition information"]}, {"id": "medquad-MPlusHealthTopics-0000910-1", "topic": "traumatic brain injury", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Traumatic Brain Injury?", "url": "https://www.nlm.nih.gov/medlineplus/traumaticbraininjury.html", "retrieved": "2026-08-14", "body": "Traumatic brain injury (TBI) happens when a bump, blow, jolt, or other head injury causes damage to the brain. Every year, millions of people in the U.S. suffer brain injuries. More than half are bad enough that people must go to the hospital. The worst injuries can lead to permanent brain damage or death. Half of all TBIs are from motor vehicle accidents. Military personnel in combat zones are also at risk. Symptoms of a TBI may not appear until days or weeks following the injury. A concussion is the mildest type. It can cause a headache or neck pain, nausea, ringing in the ears, dizziness, and tiredness.", "cues": ["what is (are) traumatic brain injury?", "traumatic brain injury information"]}, {"id": "medquad-MPlusHealthTopics-0000920-1", "topic": "pregnancy", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Tumors and Pregnancy?", "url": "https://www.nlm.nih.gov/medlineplus/tumorsandpregnancy.html", "retrieved": "2026-08-14", "body": "Tumors during pregnancy are rare, but they can happen. Tumors can be either benign or malignant. Benign tumors aren't cancer. Malignant ones are. The most common cancers in pregnancy are breast cancer, cervical cancer, lymphoma, and melanoma. Cancer itself rarely harms the baby, and some cancer treatments are safe during pregnancy. You and your health care provider will work together to find the best treatment. Your options will depend on how far along the pregnancy is, as well as the type, size, and stage of your cancer. Another type of tumor that women can get is called a gestational trophoblastic disease (GTD). It happens when a fertilized egg doesn't become a fetus.", "cues": ["what is (are) tumors and pregnancy?", "tumors and pregnancy information"]}, {"id": "medquad-MPlusHealthTopics-0000927-1", "topic": "ear", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Understanding Medical Research", "url": "https://www.nlm.nih.gov/medlineplus/understandingmedicalresearch.html", "retrieved": "2026-08-14", "body": "Summary : It seems to happen almost every day - you hear about the results of a new medical research study. Sometimes the results of one study seem to disagree with the results of another study. It's important to be critical when reading or listening to reports of new medical findings. Some questions that can help you evaluate health information include: - Was the study in animals or people? - Does the study include people like you? - How big was the study? - Was it a randomized controlled clinical trial? - Where was the research done? - If a new treatment was being tested, were there side effects? - Who paid for the research? - Who is reporting the results?", "cues": ["do you have information about understanding medical research", "understanding medical research information"]}, {"id": "medquad-MPlusHealthTopics-0000941-1", "topic": "fever", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Valley Fever?", "url": "https://www.nlm.nih.gov/medlineplus/valleyfever.html", "retrieved": "2026-08-14", "body": "Valley Fever is a disease caused by a fungus (or mold) called Coccidioides. The fungi live in the soil of dry areas like the southwestern U.S. You get it from inhaling the spores of the fungus. The infection cannot spread from person to person. Anyone can get Valley Fever. But it's most common among older adults, especially those 60 and older. People who have recently moved to an area where it occurs are at highest risk for infection. Other people at higher risk include - Workers in jobs that expose them to soil dust. These include construction workers, agricultural workers, and military forces doing field training.", "cues": ["what is (are) valley fever?", "valley fever information"]}, {"id": "medquad-MPlusHealthTopics-0000946-1", "topic": "diet", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Vegetarian Diet", "url": "https://www.nlm.nih.gov/medlineplus/vegetariandiet.html", "retrieved": "2026-08-14", "body": "Summary : A vegetarian diet focuses on plants for food. These include fruits, vegetables, dried beans and peas, grains, seeds and nuts. There is no single type of vegetarian diet. Instead, vegetarian eating patterns usually fall into the following groups: - The vegan diet, which excludes all meat and animal products - The lacto vegetarian diet, which includes plant foods plus dairy products - The lacto-ovo vegetarian diet, which includes both dairy products and eggs People who follow vegetarian diets can get all the nutrients they need. However, they must be careful to eat a wide variety of foods to meet their nutritional needs.", "cues": ["do you have information about vegetarian diet", "vegetarian diet information"]}, {"id": "medquad-MPlusHealthTopics-0000950-1", "topic": "vision", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Vision Impairment and Blindness?", "url": "https://www.nlm.nih.gov/medlineplus/visionimpairmentandblindness.html", "retrieved": "2026-08-14", "body": "If you have low vision, eyeglasses, contact lenses, medicine, or surgery may not help. Activities like reading, shopping, cooking, writing, and watching TV may be hard to do. The leading causes of low vision and blindness in the United States are age-related eye diseases: macular degeneration, cataract and glaucoma. Other eye disorders, eye injuries and birth defects can also cause vision loss. Whatever the cause, lost vision cannot be restored. It can, however, be managed. A loss of vision means that you may have to reorganize your life and learn new ways of doing things. If you have some vision, visual aids such as special glasses and large print books can make life easier.", "cues": ["what is (are) vision impairment and blindness?", "vision impairment and blindness information"]}, {"id": "medquad-MPlusHealthTopics-0000952-1", "topic": "vitamin", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Vitamin A", "url": "https://www.nlm.nih.gov/medlineplus/vitamina.html", "retrieved": "2026-08-14", "body": "Summary : Vitamins are substances that your body needs to grow and develop normally. Vitamin A plays a role in your - Vision - Bone growth - Reproduction - Cell functions - Immune system Vitamin A is an antioxidant. It can come from plant or animal sources. Plant sources include colorful fruits and vegetables. Animal sources include liver and whole milk. Vitamin A is also added to foods like cereals. Vegetarians, young children, and alcoholics may need extra Vitamin A. You might also need more if you have certain conditions, such as liver diseases, cystic fibrosis, and Crohn's disease. Check with your health care provider to see if you need to take vitamin A supplements.", "cues": ["do you have information about vitamin a", "vitamin a information"]}, {"id": "medquad-MPlusHealthTopics-0000953-1", "topic": "vitamin", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Vitamin C", "url": "https://www.nlm.nih.gov/medlineplus/vitaminc.html", "retrieved": "2026-08-14", "body": "Summary : Vitamins are substances that your body needs to grow and develop normally. Vitamin C is an antioxidant. It is important for your skin, bones, and connective tissue. It promotes healing and helps the body absorb iron. Vitamin C comes from fruits and vegetables. Good sources include citrus, red and green peppers, tomatoes, broccoli, and greens. Some juices and cereals have added vitamin C. Some people may need extra vitamin C: - Pregnant/breastfeeding women - Smokers - People recovering from surgery - Burn victims", "cues": ["do you have information about vitamin c", "vitamin c information"]}, {"id": "medquad-MPlusHealthTopics-0000954-1", "topic": "vitamin", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Vitamin D", "url": "https://www.nlm.nih.gov/medlineplus/vitamind.html", "retrieved": "2026-08-14", "body": "Summary : Vitamins are substances that your body needs to grow and develop normally. Vitamin D helps your body absorb calcium. Calcium is one of the main building blocks of bone. A lack of vitamin D can lead to bone diseases such as osteoporosis or rickets. Vitamin D also has a role in your nerve, muscle, and immune systems. You can get vitamin D in three ways: through your skin, from your diet, and from supplements. Your body forms vitamin D naturally after exposure to sunlight. However, too much sun exposure can lead to skin aging and skin cancer. So many people try to get their vitamin D from other sources. Vitamin D-rich foods include egg yolks, saltwater fish, and liver.", "cues": ["do you have information about vitamin d", "vitamin d information"]}, {"id": "medquad-MPlusHealthTopics-0000955-1", "topic": "vitamin", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Vitamin E", "url": "https://www.nlm.nih.gov/medlineplus/vitamine.html", "retrieved": "2026-08-14", "body": "Summary : Vitamins are substances that your body needs to grow and develop normally. Vitamin E is an antioxidant. It plays a role in your immune system and metabolic processes. Good sources of vitamin E include - Vegetable oils - Margarine - Nuts and seeds - Leafy greens Vitamin E is also added to foods like cereals. Most people get enough vitamin E from the foods they eat. People with certain disorders, such as liver diseases, cystic fibrosis, and Crohn's disease may need extra vitamin E. Vitamin E supplements may be harmful for people who take blood thinners and other medicines. Check with your health care provider before taking the supplements.", "cues": ["do you have information about vitamin e", "vitamin e information"]}, {"id": "medquad-MPlusHealthTopics-0000956-1", "topic": "vitamin", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Vitamin K", "url": "https://www.nlm.nih.gov/medlineplus/vitamink.html", "retrieved": "2026-08-14", "body": "Summary : Vitamins are substances that your body needs to grow and develop normally. Vitamin K helps your body by making proteins for healthy bones and tissues. It also makes proteins for blood clotting. If you don't have enough vitamin K, you may bleed too much. Newborns have very little vitamin K. They usually get a shot of vitamin K soon after they are born. If you take blood thinners, you need to be careful about how much vitamin K you get. You also need to be careful about taking vitamin E supplements. Vitamin E can interfere with how vitamin K works in your body. Ask your health care provider for recommendations about these vitamins. There are different types of vitamin K.", "cues": ["do you have information about vitamin k", "vitamin k information"]}, {"id": "medquad-MPlusHealthTopics-0000957-1", "topic": "vitamin", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Vitamins", "url": "https://www.nlm.nih.gov/medlineplus/vitamins.html", "retrieved": "2026-08-14", "body": "Summary : Vitamins are substances that your body needs to grow and develop normally. There are 13 vitamins your body needs. They are - Vitamin A - B vitamins (thiamine, riboflavin, niacin, pantothenic acid, biotin, vitamin B-6, vitamin B-12 and folate) - Vitamin C - Vitamin D - Vitamin E - Vitamin K You can usually get all your vitamins from the foods you eat. Your body can also make vitamins D and K. People who eat a vegetarian diet may need to take a vitamin B12 supplement. Each vitamin has specific jobs. If you have low levels of certain vitamins, you may get health problems. For example, if you don't get enough vitamin C, you could become anemic.", "cues": ["do you have information about vitamins", "vitamins information"]}, {"id": "medquad-MPlusHealthTopics-0000966-1", "topic": "water", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Water Pollution", "url": "https://www.nlm.nih.gov/medlineplus/waterpollution.html", "retrieved": "2026-08-14", "body": "Summary : We all need clean water. People need it to grow crops and to operate factories, and for drinking and recreation. Fish and wildlife depend on it to survive. Many different pollutants can harm our rivers, streams, lakes, and oceans. The three most common are soil, nutrients, and bacteria. Rain washes soil into streams and rivers. The soil can kill tiny animals and fish eggs. It can clog the gills of fish and block light, causing plants to die. Nutrients, often from fertilizers, cause problems in lakes, ponds, and reservoirs. Nitrogen and phosphorus make algae grow and can turn water green. Bacteria, often from sewage spills, can pollute fresh or salt water.", "cues": ["do you have information about water pollution", "water pollution information"]}, {"id": "medquad-MPlusHealthTopics-0000967-1", "topic": "water", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Water Safety (Recreational)", "url": "https://www.nlm.nih.gov/medlineplus/watersafetyrecreational.html", "retrieved": "2026-08-14", "body": "Summary : Playing in the water - whether swimming, boating or diving - can be fun. It can also be dangerous, especially for children. Being safe can help prevent injuries and drowning. To stay safe in the water - Avoid alcohol when swimming or boating - Wear a life jacket whenever you're in a boat - Don't swim alone, or in bad weather - Learn CPR - Learn to swim and teach your children to swim - Supervise your children when they are in the water - Prevent sunburns - use plenty of sunscreen", "cues": ["do you have information about water safety (recreational)", "water safety (recreational) information"]}, {"id": "medquad-MPlusHealthTopics-0000968-1", "topic": "weight", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Weight Control", "url": "https://www.nlm.nih.gov/medlineplus/weightcontrol.html", "retrieved": "2026-08-14", "body": "Summary : Keeping a healthy weight is crucial. If you are underweight, overweight, or obese, you may have a higher risk of certain health problems. About two thirds of adults in the U.S. are overweight or obese. Achieving a healthy weight can help you control your cholesterol, blood pressure and blood sugar. It might also help you prevent weight-related diseases, such as heart disease, diabetes, arthritis and some cancers. Eating too much or not being physically active enough will make you overweight. To maintain your weight, the calories you eat must equal the energy you burn. To lose weight, you must use more calories than you eat.", "cues": ["do you have information about weight control", "weight control information"]}, {"id": "medquad-MPlusHealthTopics-0000969-1", "topic": "weight", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "Do you have information about Weight Loss Surgery", "url": "https://www.nlm.nih.gov/medlineplus/weightlosssurgery.html", "retrieved": "2026-08-14", "body": "Summary : Weight loss surgery helps people with extreme obesity to lose weight. It may be an option if you cannot lose weight through diet and exercise or have serious health problems caused by obesity. There are different types of weight loss surgery. They often limit the amount of food you can take in. Some types of surgery also affect how you digest food and absorb nutrients. All types have risks and complications, such as infections, hernias, and blood clots. Many people who have the surgery lose weight quickly, but regain some weight later on. If you follow diet and exercise recommendations, you can keep most of the weight off.", "cues": ["do you have information about weight loss surgery", "weight loss surgery information"]}, {"id": "medquad-MPlusHealthTopics-0000971-1", "topic": "cough", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Whooping Cough?", "url": "https://www.nlm.nih.gov/medlineplus/whoopingcough.html", "retrieved": "2026-08-14", "body": "Whooping cough is an infectious bacterial disease that causes uncontrollable coughing. The name comes from the noise you make when you take a breath after you cough. You may have choking spells or may cough so hard that you vomit. Anyone can get whooping cough, but it is more common in infants and children. It's especially dangerous for infants. The coughing spells can be so bad that it is hard for infants to eat, drink, or breathe. To make a diagnosis, your doctor may do a physical exam, blood tests, chest x-rays, or nose or throat cultures. Before there was a vaccine, whooping cough was one of the most common childhood diseases and a major cause of childhood deaths in the U.S.", "cues": ["what is (are) whooping cough?", "whooping cough information"]}, {"id": "medquad-MPlusHealthTopics-0000977-1", "topic": "wound", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Wounds and Injuries?", "url": "https://www.nlm.nih.gov/medlineplus/woundsandinjuries.html", "retrieved": "2026-08-14", "body": "An injury is damage to your body. It is a general term that refers to harm caused by accidents, falls, hits, weapons, and more. In the U.S., millions of people injure themselves every year. These injuries range from minor to life-threatening. Injuries can happen at work or play, indoors or outdoors, driving a car, or walking across the street. Wounds are injuries that break the skin or other body tissues. They include cuts, scrapes, scratches, and punctured skin. They often happen because of an accident, but surgery, sutures, and stitches also cause wounds. Minor wounds usually aren't serious, but it is important to clean them.", "cues": ["what is (are) wounds and injuries?", "wounds and injuries information"]}, {"id": "medquad-MPlusHealthTopics-0000980-1", "topic": "infection", "intent": "general-health", "type": "public-health", "org": "MedlinePlus", "title": "What is (are) Yeast Infections?", "url": "https://www.nlm.nih.gov/medlineplus/yeastinfections.html", "retrieved": "2026-08-14", "body": "Candida is the scientific name for yeast. It is a fungus that lives almost everywhere, including in your body. Usually, your immune system keeps yeast under control. If you are sick or taking antibiotics, it can multiply and cause an infection. Yeast infections affect different parts of the body in different ways: - Thrush is a yeast infection that causes white patches in your mouth - Candida esophagitis is thrush that spreads to your esophagus, the tube that takes food from your mouth to your stomach. It can make it hard or painful to swallow.", "cues": ["what is (are) yeast infections?", "yeast infections information"]}, {"id": "medquad-NHLBI-0000010-2", "topic": "asthma", "intent": "symptom", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "What causes Asthma?", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/asthma", "retrieved": "2026-08-14", "body": "The exact cause of asthma isn't known. Researchers think some genetic and environmental factors interact to cause asthma, most often early in life. These factors include: An inherited tendency to develop allergies, called atopy (AT-o-pe) Parents who have asthma Certain respiratory infections during childhood Contact with some airborne allergens or exposure to some viral infections in infancy or in early childhood when the immune system is developing If asthma or atopy runs in your family, exposure to irritants (for example, tobacco smoke) may make your airways more reactive to substances in the air. Some factors may be more likely to cause asthma in some people than in others.", "cues": ["what causes asthma?", "asthma causes"]}, {"id": "medquad-NHLBI-0000010-3", "topic": "asthma", "intent": "preventive", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "Who is at risk for Asthma??", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/asthma", "retrieved": "2026-08-14", "body": "Asthma affects people of all ages, but it most often starts during childhood. In the United States, more than 22 million people are known to have asthma. Nearly 6 million of these people are children. Young children who often wheeze and have respiratory infectionsas well as certain other risk factorsare at highest risk of developing asthma that continues beyond 6 years of age. The other risk factors include having allergies, eczema (an allergic skin condition), or parents who have asthma. Among children, more boys have asthma than girls. But among adults, more women have the disease than men. It's not clear whether or how sex and sex hormones play a role in causing asthma.", "cues": ["who is at risk for asthma??", "asthma susceptibility"]}, {"id": "medquad-NHLBI-0000010-4", "topic": "asthma", "intent": "symptom", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "What are the symptoms of Asthma?", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/asthma", "retrieved": "2026-08-14", "body": "Common signs and symptoms of asthma include: Coughing. Coughing from asthma often is worse at night or early in the morning, making it hard to sleep. Wheezing. Wheezing is a whistling or squeaky sound that occurs when you breathe. Chest tightness. This may feel like something is squeezing or sitting on your chest. Shortness of breath. Some people who have asthma say they can't catch their breath or they feel out of breath. You may feel like you can't get air out of your lungs. Not all people who have asthma have these symptoms. Likewise, having these symptoms doesn't always mean that you have asthma.", "cues": ["what are the symptoms of asthma?", "asthma symptoms"]}, {"id": "medquad-NHLBI-0000010-5", "topic": "asthma", "intent": "general-health", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "How to diagnose Asthma?", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/asthma", "retrieved": "2026-08-14", "body": "Your primary care doctor will diagnose asthma based on your medical and family histories, a physical exam, and test results. Your doctor also will figure out the severity of your asthmathat is, whether it's intermittent, mild, moderate, or severe. The level of severity will determine what treatment you'll start on.", "cues": ["how to diagnose asthma?", "asthma exams and tests"]}, {"id": "medquad-NHLBI-0000021-1", "topic": "bronchitis", "intent": "general-health", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "What is (are) Bronchitis?", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/brnchi", "retrieved": "2026-08-14", "body": "Espaol Bronchitis (bron-KI-tis) is a condition in which the bronchial tubes become inflamed. These tubes carry air to your lungs. (For more information about the bronchial tubes and airways, go to the Diseases and Conditions Index How the Lungs Work article.) People who have bronchitis often have a cough that brings up mucus. Mucus is a slimy substance made by the lining of the bronchial tubes. Bronchitis also may cause wheezing (a whistling or squeaky sound when you breathe), chest pain or discomfort, a low fever, and shortness of breath. Bronchitis Overview The two main types of bronchitis are acute (short term) and chronic (ongoing).", "cues": ["what is (are) bronchitis?", "bronchitis information"]}, {"id": "medquad-NHLBI-0000021-3", "topic": "bronchitis", "intent": "symptom", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "What causes Bronchitis?", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/brnchi", "retrieved": "2026-08-14", "body": "Acute Bronchitis Infections or lung irritants cause acute bronchitis. The same viruses that cause colds and the flu are the most common cause of acute bronchitis. Sometimes bacteria can cause the condition. Certain substances can irritate your lungs and airways and raise your risk for acute bronchitis. For example, inhaling or being exposed to tobacco smoke, dust, fumes, vapors, or air pollution raises your risk for the condition. These lung irritants also can make symptoms worse. Being exposed to a high level of dust or fumes, such as from an explosion or a big fire, also may lead to acute bronchitis.", "cues": ["what causes bronchitis?", "bronchitis causes"]}, {"id": "medquad-NHLBI-0000021-4", "topic": "bronchitis", "intent": "preventive", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "Who is at risk for Bronchitis??", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/brnchi", "retrieved": "2026-08-14", "body": "Bronchitis is a very common condition. Millions of cases occur every year. Elderly people, infants, and young children are at higher risk for acute bronchitis than people in other age groups. People of all ages can develop chronic bronchitis, but it occurs more often in people who are older than 45. Also, many adults who develop chronic bronchitis are smokers. Women are more than twice as likely as men to be diagnosed with chronic bronchitis. Smoking and having an existing lung disease greatly increase your risk for bronchitis. Contact with dust, chemical fumes, and vapors from certain jobs also increases your risk for the condition.", "cues": ["who is at risk for bronchitis??", "bronchitis susceptibility"]}, {"id": "medquad-NHLBI-0000021-5", "topic": "bronchitis", "intent": "symptom", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "What are the symptoms of Bronchitis?", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/brnchi", "retrieved": "2026-08-14", "body": "Acute Bronchitis Acute bronchitis caused by an infection usually develops after you already have a cold or the flu. Symptoms of a cold or the flu include sore throat, fatigue (tiredness), fever, body aches, stuffy or runny nose, vomiting, and diarrhea. The main symptom of acute bronchitis is a persistent cough, which may last 10 to 20 days. The cough may produce clear mucus (a slimy substance). If the mucus is yellow or green, you may have a bacterial infection as well. Even after the infection clears up, you may still have a dry cough for days or weeks.", "cues": ["what are the symptoms of bronchitis?", "bronchitis symptoms"]}, {"id": "medquad-NHLBI-0000047-2", "topic": "cough", "intent": "symptom", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "What causes Cough?", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/cough", "retrieved": "2026-08-14", "body": "Coughing occurs when the nerve endings in your airways become irritated. Certain irritants and allergens, medical conditions, and medicines can irritate these nerve endings. Irritants and Allergens An irritant is something you're sensitive to. For example, smoking or inhaling secondhand smoke can irritate your lungs. Smoking also can lead to medical conditions that can cause a cough. Other irritants include air pollution, paint fumes, or scented products like perfumes or air fresheners. An allergen is something you're allergic to, such as dust, animal dander, mold, or pollens from trees, grasses, and flowers. Coughing helps clear your airways of irritants and allergens.", "cues": ["what causes cough?", "cough causes"]}, {"id": "medquad-NHLBI-0000047-3", "topic": "cough", "intent": "preventive", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "Who is at risk for Cough??", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/cough", "retrieved": "2026-08-14", "body": "People at risk for cough include those who: Are exposed to things that irritate their airways (called irritants) or things that they're allergic to (called allergens). Examples of irritants are cigarette smoke, air pollution, paint fumes, and scented products. Examples of allergens are dust, animal dander, mold, and pollens from trees, grasses, and flowers. Have certain conditions that irritate the lungs, such as asthma, sinus infections, colds, or gastroesophageal reflux disease. Smoke. Smoking can irritate your lungs and cause coughing. Smoking and/or exposure to secondhand smoke also can lead to medical conditions that can cause a cough.", "cues": ["who is at risk for cough??", "cough susceptibility"]}, {"id": "medquad-NHLBI-0000047-4", "topic": "cough", "intent": "symptom", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "What are the symptoms of Cough?", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/cough", "retrieved": "2026-08-14", "body": "When you cough, mucus (a slimy substance) may come up. Coughing helps clear the mucus in your airways from a cold, bronchitis, or other condition. Rarely, people cough up blood. If this happens, you should call your doctor right away. A cough may be a symptom of a medical condition. Thus, it may occur with other signs and symptoms of that condition. For example, if you have a cold, you may have a runny or stuffy nose. If you have gastroesophageal reflux disease, you may have a sour taste in your mouth. A chronic cough can make you feel tired because you use a lot of energy to cough. It also can prevent you from sleeping well and interfere with work and socializing.", "cues": ["what are the symptoms of cough?", "cough symptoms"]}, {"id": "medquad-NHLBI-0000047-5", "topic": "cough", "intent": "general-health", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "How to diagnose Cough?", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/cough", "retrieved": "2026-08-14", "body": "Your doctor will diagnose the cause of your cough based on your medical history, a physical exam, and test results. Medical History Your doctor will likely ask questions about your cough. He or she may ask how long you've had it, whether you're coughing anything up (such as mucus, a slimy substance), and how much you cough. Your doctor also may ask: About your medical history, including whether you have allergies, asthma, or other medical conditions. Whether you have heartburn or a sour taste in your mouth. These may be signs of gastroesophageal reflux disease (GERD). Whether you've recently had a cold or the flu. Whether you smoke or spend time around others who smoke.", "cues": ["how to diagnose cough?", "cough exams and tests"]}, {"id": "medquad-NHLBI-0000070-1", "topic": "cholesterol", "intent": "general-health", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "What is (are) High Blood Cholesterol?", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/hbc", "retrieved": "2026-08-14", "body": "To understand high blood cholesterol (ko-LES-ter-ol), it helps to learn about cholesterol. Cholesterol is a waxy, fat-like substance thats found in all cells of the body. Your body needs some cholesterol to make hormones, vitamin D, and substances that help you digest foods. Your body makes all the cholesterol it needs. However, cholesterol also is found in some of the foods you eat. Cholesterol travels through your bloodstream in small packages called lipoproteins (lip-o-PRO-teens). These packages are made of fat (lipid) on the inside and proteins on the outside.", "cues": ["what is (are) high blood cholesterol?", "high blood cholesterol information"]}, {"id": "medquad-NHLBI-0000070-3", "topic": "cholesterol", "intent": "symptom", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "What causes High Blood Cholesterol?", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/hbc", "retrieved": "2026-08-14", "body": "Many factors can affect the cholesterol levels in your blood. You can control some factors, but not others. Factors You Can Control Diet Cholesterol is found in foods that come from animal sources, such as egg yolks, meat, and cheese. Some foods have fats that raise your cholesterol level. For example, saturated fat raises your low-density lipoprotein (LDL) cholesterol level more than anything else in your diet. Saturated fat is found in some meats, dairy products, chocolate, baked goods, and deep-fried and processed foods. Trans fatty acids (trans fats) raise your LDL cholesterol and lower your high-density lipoprotein (HDL) cholesterol.", "cues": ["what causes high blood cholesterol?", "high blood cholesterol causes"]}, {"id": "medquad-NHLBI-0000070-4", "topic": "cholesterol", "intent": "symptom", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "What are the symptoms of High Blood Cholesterol?", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/hbc", "retrieved": "2026-08-14", "body": "High blood cholesterol usually has no signs or symptoms. Thus, many people don't know that their cholesterol levels are too high. If you're 20 years old or older, have your cholesterol levels checked at least once every 5 years. Talk with your doctor about how often you should be tested.", "cues": ["what are the symptoms of high blood cholesterol?", "high blood cholesterol symptoms"]}, {"id": "medquad-NHLBI-0000070-5", "topic": "cholesterol", "intent": "general-health", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "How to diagnose High Blood Cholesterol?", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/hbc", "retrieved": "2026-08-14", "body": "Your doctor will diagnose high blood cholesterol by checking the cholesterol levels in your blood. A blood test called a lipoprotein panel can measure your cholesterol levels. Before the test, youll need to fast (not eat or drink anything but water) for 9 to 12 hours. The lipoprotein panel will give your doctor information about your: Total cholesterol. Total cholesterol is a measure of the total amount of cholesterol in your blood, including low-density lipoprotein (LDL) cholesterol and high-density lipoprotein (HDL) cholesterol. LDL cholesterol. LDL, or bad, cholesterol is the main source of cholesterol buildup and blockages in the arteries. HDL cholesterol.", "cues": ["how to diagnose high blood cholesterol?", "high blood cholesterol exams and tests"]}, {"id": "medquad-NHLBI-0000070-6", "topic": "cholesterol", "intent": "general-health", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "What are the treatments for High Blood Cholesterol?", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/hbc", "retrieved": "2026-08-14", "body": "High blood cholesterol is treated with lifestyle changes and medicines. The main goal of treatment is to lower your low-density lipoprotein (LDL) cholesterol level enough to reduce your risk for coronary heart disease, heart attack, and other related health problems. Your risk for heart disease and heart attack goes up as your LDL cholesterol level rises and your number of heart disease risk factors increases. Some people are at high risk for heart attacks because they already have heart disease. Other people are at high risk for heart disease because they have diabetes or more than one heart disease risk factor.", "cues": ["what are the treatments for high blood cholesterol?", "high blood cholesterol treatment"]}, {"id": "medquad-NHLBI-0000081-2", "topic": "insomnia", "intent": "symptom", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "What causes Insomnia?", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/inso", "retrieved": "2026-08-14", "body": "Secondary Insomnia Secondary insomnia is the symptom or side effect of another problem. This type of insomnia often is a symptom of an emotional, neurological, or other medical or sleep disorder. Emotional disorders that can cause insomnia include depression, anxiety, and posttraumatic stress disorder. Alzheimer's disease and Parkinson's disease are examples of neurological disorders that can cause insomnia.", "cues": ["what causes insomnia?", "insomnia causes"]}, {"id": "medquad-NHLBI-0000081-3", "topic": "insomnia", "intent": "preventive", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "Who is at risk for Insomnia??", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/inso", "retrieved": "2026-08-14", "body": "Insomnia is a common disorder. It affects women more often than men. The disorder can occur at any age. However, older adults are more likely to have insomnia than younger people. People who might be at increased risk for insomnia include those who: Have a lot of stress. Are depressed or have other emotional distress, such as divorce or death of a spouse. Have lower incomes. Work at night or have frequent major shifts in their work hours. Travel long distances with time changes. Have certain medical conditions or sleep disorders that can disrupt sleep. For more information, go to \"What Causes Insomnia?\" Have an inactive lifestyle.", "cues": ["who is at risk for insomnia??", "insomnia susceptibility"]}, {"id": "medquad-NHLBI-0000081-4", "topic": "insomnia", "intent": "symptom", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "What are the symptoms of Insomnia?", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/inso", "retrieved": "2026-08-14", "body": "The main symptom of insomnia is trouble falling or staying asleep, which leads to lack of sleep. If you have insomnia, you may: Lie awake for a long time before you fall asleep Sleep for only short periods Be awake for much of the night Feel as if you haven't slept at all Wake up too early The lack of sleep can cause other symptoms. You may wake up feeling tired or not well-rested, and you may feel tired during the day. You also may have trouble focusing on tasks. Insomnia can cause you to feel anxious, depressed, or irritable. Insomnia also can affect your daily activities and cause serious problems. For example, you may feel drowsy while driving.", "cues": ["what are the symptoms of insomnia?", "insomnia symptoms"]}, {"id": "medquad-NHLBI-0000081-5", "topic": "insomnia", "intent": "general-health", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "How to diagnose Insomnia?", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/inso", "retrieved": "2026-08-14", "body": "Your doctor will likely diagnose insomnia based on your medical and sleep histories and a physical exam. He or she also may recommend a sleep study. For example, you may have a sleep study if the cause of your insomnia is unclear. Medical History To find out what's causing your insomnia, your doctor may ask whether you: Have any new or ongoing health problems Have painful injuries or health conditions, such as arthritis Take any medicines, either over-the-counter or prescription Have symptoms or a history of depression, anxiety, or psychosis Are coping with highly stressful life events, such as divorce or death Your doctor also may ask questions about your work and leisure habits.", "cues": ["how to diagnose insomnia?", "insomnia exams and tests"]}, {"id": "medquad-NHLBI-0000081-6", "topic": "insomnia", "intent": "general-health", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "What are the treatments for Insomnia?", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/inso", "retrieved": "2026-08-14", "body": "Lifestyle changes often can help relieve acute (short-term) insomnia. These changes might make it easier to fall asleep and stay asleep. A type of counseling called cognitive-behavioral therapy (CBT) can help relieve the anxiety linked to chronic (ongoing) insomnia. Anxiety tends to prolong insomnia. Several medicines also can help relieve insomnia and re-establish a regular sleep schedule. However, if your insomnia is the symptom or side effect of another problem, it's important to treat the underlying cause (if possible). Lifestyle Changes If you have insomnia, avoid substances that make it worse, such as: Caffeine, tobacco, and other stimulants.", "cues": ["what are the treatments for insomnia?", "insomnia treatment"]}, {"id": "medquad-NHLBI-0000094-1", "topic": "obesity", "intent": "general-health", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "What is (are) Obesity Hypoventilation Syndrome?", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/ohs", "retrieved": "2026-08-14", "body": "Obesity hypoventilation (HI-po-ven-tih-LA-shun) syndrome (OHS) is a breathing disorder that affects some obese people. In OHS, poor breathing results in too much carbon dioxide (hypoventilation) and too little oxygen in the blood (hypoxemia). OHS sometimes is called Pickwickian syndrome. Overview To understand OHS, it helps to understand how the lungs work. When you breathe, air passes through your nose and mouth into your windpipe. The air then travels to your lungs' air sacs. These sacs are called alveoli (al-VEE-uhl-eye). Small blood vessels called capillaries (KAP-ih-lare-ees) run through the walls of the air sacs.", "cues": ["what is (are) obesity hypoventilation syndrome?", "obesity hypoventilation syndrome information"]}, {"id": "medquad-NHLBI-0000094-2", "topic": "obesity", "intent": "symptom", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "What causes Obesity Hypoventilation Syndrome?", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/ohs", "retrieved": "2026-08-14", "body": "Obesity hypoventilation syndrome (OHS) is a breathing disorder that affects some obese people. Why these people develop OHS isn't fully known. Researchers think that several factors may work together to cause OHS. These factors include: A respiratory (RES-pih-rah-tor-e) system that has to work harder than normal and perhaps differently because of excess body weight. (The respiratory system is a group of organs and tissues, including the lungs, that helps you breathe.) A slow response by the body to fix the problem of too much carbon dioxide and too little oxygen in the blood. The presence of sleep apnea, usually obstructive sleep apnea.", "cues": ["what causes obesity hypoventilation syndrome?", "obesity hypoventilation syndrome causes"]}, {"id": "medquad-NHLBI-0000094-3", "topic": "obesity", "intent": "preventive", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "Who is at risk for Obesity Hypoventilation Syndrome??", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/ohs", "retrieved": "2026-08-14", "body": "People who are obese are at risk for obesity hypoventilation syndrome (OHS). \"Obesity\" refers to having too much body fat. People who are obese have body weight that's greater than what is considered healthy for a certain height. The most useful measure of obesity is body mass index (BMI). BMI is calculated from your height and weight. In adults, a BMI of 30 or more is considered obese. You can use the National Heart, Lung, and Blood Institute's (NHLBI's) online BMI calculator to figure out your BMI, or your doctor can help you. If you are obese, you're at greater risk for OHS if your BMI is 40 or higher.", "cues": ["who is at risk for obesity hypoventilation syndrome??", "obesity hypoventilation syndrome susceptibility"]}, {"id": "medquad-NHLBI-0000094-4", "topic": "obesity", "intent": "symptom", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "What are the symptoms of Obesity Hypoventilation Syndrome?", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/ohs", "retrieved": "2026-08-14", "body": "Many of the signs and symptoms of obesity hypoventilation syndrome (OHS) are the same as those of obstructive sleep apnea. This is because many people who have OHS also have obstructive sleep apnea. One of the most common signs of obstructive sleep apnea is loud and chronic (ongoing) snoring. Pauses may occur in the snoring. Choking or gasping may follow the pauses. Other symptoms include: Daytime sleepiness Morning headaches Memory, learning, or concentration problems Feeling irritable or depressed, or having mood swings or personality changes You also may have rapid, shallow breathing.", "cues": ["what are the symptoms of obesity hypoventilation syndrome?", "obesity hypoventilation syndrome symptoms"]}, {"id": "medquad-NHLBI-0000095-1", "topic": "weight", "intent": "general-health", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "What is (are) Overweight and Obesity?", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/obe", "retrieved": "2026-08-14", "body": "Espaol The terms \"overweight\" and \"obesity\" refer to body weight thats greater than what is considered healthy for a certain height. The most useful measure of overweight and obesity is body mass index (BMI). BMI is calculated from your height and weight. For more information about BMI, go to \"How Are Overweight and Obesity Diagnosed?\" Overview Millions of Americans and people worldwide are overweight or obese. Being overweight or obese puts you at risk for many health problems.", "cues": ["what is (are) overweight and obesity?", "overweight and obesity information"]}, {"id": "medquad-NHLBI-0000095-2", "topic": "weight", "intent": "symptom", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "What causes Overweight and Obesity?", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/obe", "retrieved": "2026-08-14", "body": "Lack of Energy Balance A lack of energy balance most often causes overweight and obesity. Energy balance means that your energy IN equals your energy OUT. Energy IN is the amount of energy or calories you get from food and drinks. Energy OUT is the amount of energy your body uses for things like breathing, digesting, and being physically active. To maintain a healthy weight, your energy IN and OUT don't have to balance exactly every day. It's the balance over time that helps you maintain a healthy weight.", "cues": ["what causes overweight and obesity?", "overweight and obesity causes"]}, {"id": "medquad-NHLBI-0000105-4", "topic": "pneumonia", "intent": "symptom", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "What causes Pneumonia?", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/pnu", "retrieved": "2026-08-14", "body": "Many germs can cause pneumonia. Examples include different kinds of bacteria, viruses, and, less often, fungi. Most of the time, the body filters germs out of the air that we breathe to protect the lungs from infection. Your immune system, the shape of your nose and throat, your ability to cough, and fine, hair-like structures called cilia (SIL-e-ah) help stop the germs from reaching your lungs. (For more information, go to the Diseases and Conditions Index How the Lungs Work article.) Sometimes, though, germs manage to enter the lungs and cause infections.", "cues": ["what causes pneumonia?", "pneumonia causes"]}, {"id": "medquad-NHLBI-0000105-5", "topic": "pneumonia", "intent": "preventive", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "Who is at risk for Pneumonia??", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/pnu", "retrieved": "2026-08-14", "body": "Pneumonia can affect people of all ages. However, two age groups are at greater risk of developing pneumonia: Infants who are 2 years old or younger (because their immune systems are still developing during the first few years of life) People who are 65 years old or older Other conditions and factors also raise your risk for pneumonia. You're more likely to get pneumonia if you have a lung disease or other serious disease. Examples include cystic fibrosis, asthma, COPD (chronic obstructive pulmonary disease), bronchiectasis, diabetes, heart failure, and sickle cell anemia.", "cues": ["who is at risk for pneumonia??", "pneumonia susceptibility"]}, {"id": "medquad-NHLBI-0000105-6", "topic": "pneumonia", "intent": "symptom", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "What are the symptoms of Pneumonia?", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/pnu", "retrieved": "2026-08-14", "body": "The signs and symptoms of pneumonia vary from mild to severe. Many factors affect how serious pneumonia is, including the type of germ causing the infection and your age and overall health. (For more information, go to \"Who Is at Risk for Pneumonia?\") See your doctor promptly if you: Have a high fever Have shaking chills Have a cough with phlegm (a slimy substance), which doesn't improve or worsens Develop shortness of breath with normal daily activities Have chest pain when you breathe or cough Feel suddenly worse after a cold or the flu People who have pneumonia may have other symptoms, including nausea (feeling sick to the stomach), vomiting, and diarrhea.", "cues": ["what are the symptoms of pneumonia?", "pneumonia symptoms"]}, {"id": "medquad-NHLBI-0000105-7", "topic": "pneumonia", "intent": "general-health", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "How to diagnose Pneumonia?", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/pnu", "retrieved": "2026-08-14", "body": "Pneumonia can be hard to diagnose because it may seem like a cold or the flu. You may not realize it's more serious until it lasts longer than these other conditions. Your doctor will diagnose pneumonia based on your medical history, a physical exam, and test results. Medical History Your doctor will ask about your signs and symptoms and how and when they began.", "cues": ["how to diagnose pneumonia?", "pneumonia exams and tests"]}, {"id": "medquad-NHLBI-0000105-8", "topic": "pneumonia", "intent": "general-health", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "What are the treatments for Pneumonia?", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/pnu", "retrieved": "2026-08-14", "body": "Treatment for pneumonia depends on the type of pneumonia you have and how severe it is. Most people who have community-acquired pneumoniathe most common type of pneumoniaare treated at home. The goals of treatment are to cure the infection and prevent complications. General Treatment If you have pneumonia, follow your treatment plan, take all medicines as prescribed, and get ongoing medical care. Ask your doctor when you should schedule followup care. Your doctor may want you to have a chest x ray to make sure the pneumonia is gone. Although you may start feeling better after a few days or weeks, fatigue (tiredness) can persist for up to a month or more.", "cues": ["what are the treatments for pneumonia?", "pneumonia treatment"]}, {"id": "medquad-NHLBI-0000109-4", "topic": "hypertension", "intent": "symptom", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "What causes Pulmonary Hypertension?", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/pah", "retrieved": "2026-08-14", "body": "Pulmonary hypertension (PH) begins with inflammation and changes in the cells that line your pulmonary arteries. Other factors also can affect the pulmonary arteries and cause PH. For example, the condition may develop if: The walls of the arteries tighten. The walls of the arteries are stiff at birth or become stiff from an overgrowth of cells. Blood clots form in the arteries. These changes make it hard for your heart to push blood through your pulmonary arteries and into your lungs. Thus, the pressure in the arteries rises, causing PH. Many factors can contribute to the process that leads to the different types of PH.", "cues": ["what causes pulmonary hypertension?", "pulmonary hypertension causes"]}, {"id": "medquad-NHLBI-0000109-5", "topic": "hypertension", "intent": "preventive", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "Who is at risk for Pulmonary Hypertension??", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/pah", "retrieved": "2026-08-14", "body": "The exact number of people who have pulmonary hypertension (PH) isn't known. Group 1 pulmonary arterial hypertension (PAH) without a known cause is rare. It affects women more often than men. People who have group 1 PAH tend to be overweight. PH that occurs with another disease or condition is more common. PH usually develops between the ages of 20 and 60, but it can occur at any age. People who are at increased risk for PH include: Those who have a family history of the condition. Those who have certain diseases or conditions, such as heart and lung diseases, liver disease, HIV infection, or blood clots in the pulmonary arteries.", "cues": ["who is at risk for pulmonary hypertension??", "pulmonary hypertension susceptibility"]}, {"id": "medquad-NHLBI-0000109-6", "topic": "hypertension", "intent": "symptom", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "What are the symptoms of Pulmonary Hypertension?", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/pah", "retrieved": "2026-08-14", "body": "Signs and symptoms of pulmonary hypertension (PH) may include: Shortness of breath during routine activity, such as climbing two flights of stairs Tiredness Chest pain A racing heartbeat Pain on the upper right side of the abdomen Decreased appetite As PH worsens, you may find it hard to do any physical activities. At this point, other signs and symptoms may include: Feeling light-headed, especially during physical activity Fainting at times Swelling in your legs and ankles A bluish color on your lips and skin", "cues": ["what are the symptoms of pulmonary hypertension?", "pulmonary hypertension symptoms"]}, {"id": "medquad-NHLBI-0000109-7", "topic": "hypertension", "intent": "general-health", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "How to diagnose Pulmonary Hypertension?", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/pah", "retrieved": "2026-08-14", "body": "Your doctor will diagnose pulmonary hypertension (PH) based on your medical and family histories, a physical exam, and the results from tests and procedures. PH can develop slowly. In fact, you may have it for years and not know it. This is because the condition has no early signs or symptoms. When symptoms do occur, they're often like those of other heart and lung conditions, such as asthma. This makes PH hard to diagnose. Medical and Family Histories Your doctor may ask about your signs and symptoms and how and when they began. He or she also may ask whether you have other medical conditions that can cause PH.", "cues": ["how to diagnose pulmonary hypertension?", "pulmonary hypertension exams and tests"]}, {"id": "medquad-NHLBI-0000109-8", "topic": "hypertension", "intent": "general-health", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "What are the treatments for Pulmonary Hypertension?", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/pah", "retrieved": "2026-08-14", "body": "Pulmonary hypertension (PH) has no cure. However, treatment may help relieve symptoms and slow the progress of the disease. PH is treated with medicines, procedures, and other therapies. Treatment will depend on what type of PH you have and its severity. (For more information, go to \"Types of Pulmonary Hypertension.\") Group 1 Pulmonary Arterial Hypertension Group 1 pulmonary arterial hypertension (PAH) includes PH that's inherited, that has no known cause, or that's caused by certain drugs or conditions. Treatments for group 1 PAH include medicines and medical procedures.", "cues": ["what are the treatments for pulmonary hypertension?", "pulmonary hypertension treatment"]}, {"id": "medquad-NHLBI-0000112-1", "topic": "stress", "intent": "general-health", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "What is (are) Respiratory Distress Syndrome?", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/rds", "retrieved": "2026-08-14", "body": "Respiratory distress syndrome (RDS) is a breathing disorder that affects newborns. RDS rarely occurs in full-term infants. The disorder is more common in premature infants born about 6 weeks or more before their due dates. RDS is more common in premature infants because their lungs aren't able to make enough surfactant (sur-FAK-tant). Surfactant is a liquid that coats the inside of the lungs. It helps keep them open so that infants can breathe in air once they're born. Without enough surfactant, the lungs collapse and the infant has to work hard to breathe. He or she might not be able to breathe in enough oxygen to support the body's organs.", "cues": ["what is (are) respiratory distress syndrome?", "respiratory distress syndrome information"]}, {"id": "medquad-NHLBI-0000112-3", "topic": "stress", "intent": "symptom", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "What causes Respiratory Distress Syndrome?", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/rds", "retrieved": "2026-08-14", "body": "The main cause of respiratory distress syndrome (RDS) is a lack of surfactant in the lungs. Surfactant is a liquid that coats the inside of the lungs. A fetus's lungs start making surfactant during the third trimester of pregnancy (weeks 26 through labor and delivery). The substance coats the insides of the air sacs in the lungs. This helps keep the lungs open so breathing can occur after birth. Without enough surfactant, the lungs will likely collapse when the infant exhales (breathes out). The infant then has to work harder to breathe. He or she might not be able to get enough oxygen to support the body's organs.", "cues": ["what causes respiratory distress syndrome?", "respiratory distress syndrome causes"]}, {"id": "medquad-NHLBI-0000112-4", "topic": "stress", "intent": "preventive", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "Who is at risk for Respiratory Distress Syndrome??", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/rds", "retrieved": "2026-08-14", "body": "Certain factors may increase the risk that your infant will have respiratory distress syndrome (RDS). These factors include: Premature delivery. The earlier your baby is born, the greater his or her risk for RDS. Most cases of RDS occur in babies born before 28 weeks of pregnancy. Stress during your baby's delivery, especially if you lose a lot of blood. Infection. Your having diabetes. Your baby also is at greater risk for RDS if you require an emergency cesarean delivery (C-section) before your baby is full term. You may need an emergency C-section because of a condition, such as a detached placenta, that puts you or your infant at risk.", "cues": ["who is at risk for respiratory distress syndrome??", "respiratory distress syndrome susceptibility"]}, {"id": "medquad-NHLBI-0000112-5", "topic": "stress", "intent": "symptom", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "What are the symptoms of Respiratory Distress Syndrome?", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/rds", "retrieved": "2026-08-14", "body": "Signs and symptoms of respiratory distress syndrome (RDS) usually occur at birth or within the first few hours that follow. They include: Rapid, shallow breathing Sharp pulling in of the chest below and between the ribs with each breath Grunting sounds Flaring of the nostrils The infant also may have pauses in breathing that last for a few seconds. This condition is called apnea (AP-ne-ah). Respiratory Distress Syndrome Complications Depending on the severity of an infant's RDS, he or she may develop other medical problems.", "cues": ["what are the symptoms of respiratory distress syndrome?", "respiratory distress syndrome symptoms"]}, {"id": "medquad-NHLBI-0000119-1", "topic": "sleep", "intent": "general-health", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "What is (are) Sleep Deprivation and Deficiency?", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/sdd", "retrieved": "2026-08-14", "body": "Sleep deprivation (DEP-rih-VA-shun) is a condition that occurs if you don't get enough sleep. Sleep deficiency is a broader concept. It occurs if you have one or more of the following: You don't get enough sleep (sleep deprivation) You sleep at the wrong time of day (that is, you're out of sync with your body's natural clock) You don't sleep well or get all of the different types of sleep that your body needs You have a sleep disorder that prevents you from getting enough sleep or causes poor quality sleep This article focuses on sleep deficiency, unless otherwise noted. Sleeping is a basic human need, like eating, drinking, and breathing.", "cues": ["what is (are) sleep deprivation and deficiency?", "sleep deprivation and deficiency information"]}, {"id": "medquad-NHLBI-0000119-5", "topic": "sleep", "intent": "preventive", "type": "public-health", "org": "NHLBI (US National Heart, Lung, and Blood Institute)", "title": "Who is at risk for Sleep Deprivation and Deficiency??", "url": "https://www.nhlbi.nih.gov/health/health-topics/topics/sdd", "retrieved": "2026-08-14", "body": "Sleep deficiency, which includes sleep deprivation, affects people of all ages, races, and ethnicities. Certain groups of people may be more likely to be sleep deficient.", "cues": ["who is at risk for sleep deprivation and deficiency??", "sleep deprivation and deficiency susceptibility"]}, {"id": "medquad-NIDDK-0000014-1", "topic": "thyroid", "intent": "general-health", "type": "public-health", "org": "NIDDK (US National Institute of Diabetes and Digestive and Kidney Diseases)", "title": "What is (are) Primary Hyperparathyroidism?", "url": "https://www.niddk.nih.gov/health-information/health-topics/endocrine/primary-hyperparathyroidism/Pages/fact-sheet.aspx", "retrieved": "2026-08-14", "body": "Primary hyperparathyroidism is a disorder of the parathyroid glands, also called parathyroids. Primary means this disorder originates in the parathyroid glands. In primary hyperparathyroidism, one or more of the parathyroid glands are overactive. As a result, the gland releases too much parathyroid hormone (PTH). The disorder includes the problems that occur in the rest of the body as a result of too much PTHfor example, loss of calcium from bones.", "cues": ["what is (are) primary hyperparathyroidism?", "primary hyperparathyroidism information"]}, {"id": "medquad-NIDDK-0000016-1", "topic": "anemia", "intent": "general-health", "type": "public-health", "org": "NIDDK (US National Institute of Diabetes and Digestive and Kidney Diseases)", "title": "What is (are) Anemia of Inflammation and Chronic Disease?", "url": "https://www.niddk.nih.gov/health-information/health-topics/blood-diseases/anemia-inflammation-chronic-disease/Pages/fact-sheet.aspx", "retrieved": "2026-08-14", "body": "Anemia is a condition in which a person has a lower than normal number of red blood cells or the amount of hemoglobin in the red blood cells drops below normal, which prevents the bodys cells from getting enough oxygen. Hemoglobin is an iron-rich protein that gives blood its red color and lets red blood cells transport oxygen from the lungs to the bodys tissues. Therefore, low numbers of red blood cells or low levels of hemoglobin also cause low blood iron levels. People with anemia may feel tired because their blood does not supply enough oxygen to the bodys organs and tissues.", "cues": ["what is (are) anemia of inflammation and chronic disease?", "anemia of inflammation and chronic disease information"]}, {"id": "medquad-NIDDK-0000016-3", "topic": "anemia", "intent": "preventive", "type": "public-health", "org": "NIDDK (US National Institute of Diabetes and Digestive and Kidney Diseases)", "title": "Who is at risk for Anemia of Inflammation and Chronic Disease??", "url": "https://www.niddk.nih.gov/health-information/health-topics/blood-diseases/anemia-inflammation-chronic-disease/Pages/fact-sheet.aspx", "retrieved": "2026-08-14", "body": "While AI/ACD can affect people at any age, older adults are especially at risk because they have the highest rates of chronic disease. AI/ACD is also common among hospitalized patients, particularly those with chronic illnesses. More than 130 million Americans live with at least one chronic illness.2 Addressing the causes of anemia in people with chronic disease can help improve their health and quality of life.", "cues": ["who is at risk for anemia of inflammation and chronic disease??", "anemia of inflammation and chronic disease susceptibility"]}, {"id": "medquad-NIDDK-0000016-4", "topic": "anemia", "intent": "symptom", "type": "public-health", "org": "NIDDK (US National Institute of Diabetes and Digestive and Kidney Diseases)", "title": "What causes Anemia of Inflammation and Chronic Disease?", "url": "https://www.niddk.nih.gov/health-information/health-topics/blood-diseases/anemia-inflammation-chronic-disease/Pages/fact-sheet.aspx", "retrieved": "2026-08-14", "body": "Anemia of inflammation and chronic disease is caused by red blood cells not functioning normally, so they cannot absorb and use iron efficiently. In addition, the body cannot respond normally to erythropoietin (EPO), a hormone made by the kidneys that stimulates bone marrow to produce red blood cells. Over time, this abnormal functioning causes a lower than normal number of red blood cells in the body. Some of the chronic diseases that lead to AI/ACD include infectious and inflammatory diseases, kidney disease, and cancer. Certain treatments for chronic diseases may also impair red blood cell production and contribute to AI/ACD. Infectious and inflammatory diseases.", "cues": ["what causes anemia of inflammation and chronic disease?", "anemia of inflammation and chronic disease causes"]}, {"id": "medquad-NIDDK-0000079-6", "topic": "physical activity", "intent": "general-health", "type": "public-health", "org": "NIDDK (US National Institute of Diabetes and Digestive and Kidney Diseases)", "title": "What to do for What I need to know about Physical Activity and Diabetes?", "url": "https://www.niddk.nih.gov/health-information/health-topics/Diabetes/physical-activity-diabetes/Pages/physical-activity-diabetes.aspx", "retrieved": "2026-08-14", "body": "- Starting a physical activity program can help you lose weight or keep a healthy weight and keep your blood glucose levels on target. - Always talk with your health care team before you start a new physical activity program. - Ask your health care team if you need to change the amount of medicine you take or the food you eat before any physical activity. - Talk with your health care team about what types of physical activity are safe for you, such as walking, weightlifting, or housework. - To make sure you stay active, find activities you like to do. Ask a friend or family member to be your exercise buddy.", "cues": ["what to do for what i need to know about physical activity and diabetes?", "what i need to know about physical activity and diabetes considerations"]}, {"id": "medquad-NIDDK-0000089-1", "topic": "diarrhea", "intent": "general-health", "type": "public-health", "org": "NIDDK (US National Institute of Diabetes and Digestive and Kidney Diseases)", "title": "What is (are) Chronic Diarrhea in Children?", "url": "https://www.niddk.nih.gov/health-information/health-topics/digestive-diseases/diarrhea/Pages/diarrhea-in-children-facts.aspx", "retrieved": "2026-08-14", "body": "Diarrhea is loose, watery stools. Chronic, or long lasting, diarrhea typically lasts for more than 4 weeks. Children with chronic diarrhea may have loose, watery stools continually, or diarrhea may come and go. Chronic diarrhea may go away without treatment, or it may be a symptom of a chronic disease or disorder. Treating the disease or disorder can relieve chronic diarrhea. Chronic diarrhea can affect children of any age: - infantsages 0 to 12 months - toddlersages 1 to 3 years - preschool-age childrenages 3 to 5 years - grade school-age childrenages 5 to 12 years - adolescentsages 12 to 18 years Diarrhea that lasts only a short time is called acute diarrhea.", "cues": ["what is (are) chronic diarrhea in children?", "chronic diarrhea in children information"]}, {"id": "medquad-NIDDK-0000089-2", "topic": "diarrhea", "intent": "symptom", "type": "public-health", "org": "NIDDK (US National Institute of Diabetes and Digestive and Kidney Diseases)", "title": "What causes Chronic Diarrhea in Children?", "url": "https://www.niddk.nih.gov/health-information/health-topics/digestive-diseases/diarrhea/Pages/diarrhea-in-children-facts.aspx", "retrieved": "2026-08-14", "body": "Many diseases and disorders can cause chronic diarrhea in children. Common causes include - infections - functional gastrointestinal (GI) disorders - food allergies and intolerances - inflammatory bowel disease (IBD) Infections, food allergies and intolerances, and IBD may cause chronic diarrhea along with malabsorption, meaning the small intestine does not absorb nutrients from food. If children do not absorb enough nutrients from the food they eat, they may become malnourished. Functional GI disorders do not cause malabsorption. Infections Infections from viruses, bacteria, or parasites sometimes lead to chronic diarrhea.", "cues": ["what causes chronic diarrhea in children?", "chronic diarrhea in children causes"]}, {"id": "medquad-NIDDK-0000089-3", "topic": "diarrhea", "intent": "symptom", "type": "public-health", "org": "NIDDK (US National Institute of Diabetes and Digestive and Kidney Diseases)", "title": "What are the symptoms of Chronic Diarrhea in Children?", "url": "https://www.niddk.nih.gov/health-information/health-topics/digestive-diseases/diarrhea/Pages/diarrhea-in-children-facts.aspx", "retrieved": "2026-08-14", "body": "Symptoms that accompany chronic diarrhea in children depend on the cause of the diarrhea. Symptoms can include - cramping - abdominal pain - nausea or vomiting - fever - chills - bloody stools Children with chronic diarrhea who have malabsorption can experience - bloating and swelling, also called distention, of the abdomen - changes in appetite - weight loss or poor weight gain Consult a Health Care Provider A childs parent or caretaker should consult a health care provider if the child - has diarrhea for more than 24 hours - is younger than 6 months old - has received treatment and the diarrhea persists Children with any of the following symptoms should see a health care provider right awa…", "cues": ["what are the symptoms of chronic diarrhea in children?", "chronic diarrhea in children symptoms"]}, {"id": "medquad-NIDDK-0000089-6", "topic": "diarrhea", "intent": "general-health", "type": "public-health", "org": "NIDDK (US National Institute of Diabetes and Digestive and Kidney Diseases)", "title": "What are the treatments for Chronic Diarrhea in Children?", "url": "https://www.niddk.nih.gov/health-information/health-topics/digestive-diseases/diarrhea/Pages/diarrhea-in-children-facts.aspx", "retrieved": "2026-08-14", "body": "The treatment for chronic diarrhea will depend on the cause. Some common causes of chronic diarrhea are treated as follows: - Infections. If a child has prolonged problems digesting certain carbohydrates or proteins after an acute infection, a health care provider may recommend changes in diet. A child may need antibiotics or medications that target parasites to treat infections that do not go away on their own. A health care provider may also prescribe antibiotics to treat small intestinal bacterial overgrowth. - Functional GI disorders. For toddlers diarrhea, treatment is usually not needed. Most children outgrow toddlers diarrhea by the time they start school.", "cues": ["what are the treatments for chronic diarrhea in children?", "chronic diarrhea in children treatment"]}, {"id": "medquad-NIDDK-0000089-7", "topic": "diarrhea", "intent": "general-health", "type": "public-health", "org": "NIDDK (US National Institute of Diabetes and Digestive and Kidney Diseases)", "title": "What to do for Chronic Diarrhea in Children?", "url": "https://www.niddk.nih.gov/health-information/health-topics/digestive-diseases/diarrhea/Pages/diarrhea-in-children-facts.aspx", "retrieved": "2026-08-14", "body": "A health care provider may recommend changing a childs diet to treat the cause of chronic diarrhea. Making sure that children receive proper nutrition is important for growth and development. A childs parent or caretaker should talk with a health care provider about changing the childs diet to treat chronic diarrhea.", "cues": ["what to do for chronic diarrhea in children?", "chronic diarrhea in children considerations"]}, {"id": "medquad-NIDDK-0000094-1", "topic": "vomiting", "intent": "general-health", "type": "public-health", "org": "NIDDK (US National Institute of Diabetes and Digestive and Kidney Diseases)", "title": "What is (are) Cyclic Vomiting Syndrome?", "url": "https://www.niddk.nih.gov/health-information/health-topics/digestive-diseases/cyclic-vomiting-syndrome/Pages/facts.aspx", "retrieved": "2026-08-14", "body": "Cyclic vomiting syndrome, sometimes referred to as CVS, is an increasingly recognized disorder with sudden, repeated attacksalso called episodesof severe nausea, vomiting, and physical exhaustion that occur with no apparent cause. The episodes can last from a few hours to several days. Episodes can be so severe that a person has to stay in bed for days, unable to go to school or work. A person may need treatment at an emergency room or a hospital during episodes. After an episode, a person usually experiences symptom-free periods lasting a few weeks to several months.", "cues": ["what is (are) cyclic vomiting syndrome?", "cyclic vomiting syndrome information"]}, {"id": "medquad-NIDDK-0000094-10", "topic": "vomiting", "intent": "general-health", "type": "public-health", "org": "NIDDK (US National Institute of Diabetes and Digestive and Kidney Diseases)", "title": "What are the treatments for Cyclic Vomiting Syndrome?", "url": "https://www.niddk.nih.gov/health-information/health-topics/digestive-diseases/cyclic-vomiting-syndrome/Pages/facts.aspx", "retrieved": "2026-08-14", "body": "A health care provider may refer patients to a gastroenterologist for treatment. People with cyclic vomiting syndrome should get plenty of rest and take medications to prevent a vomiting episode, stop an episode in progress, speed up recovery, or relieve associated symptoms. The health care team tailors treatment to the symptoms experienced during each of the four cyclic vomiting syndrome phases: - Prodrome phase treatment. The goal during the prodrome phase is to stop an episode before it progresses. Taking medication early in the phase can help stop an episode from moving to the vomiting phase or becoming severe; however, people do not always realize an episode is coming.", "cues": ["what are the treatments for cyclic vomiting syndrome?", "cyclic vomiting syndrome treatment"]}, {"id": "medquad-NIDDK-0000094-3", "topic": "vomiting", "intent": "symptom", "type": "public-health", "org": "NIDDK (US National Institute of Diabetes and Digestive and Kidney Diseases)", "title": "What causes Cyclic Vomiting Syndrome?", "url": "https://www.niddk.nih.gov/health-information/health-topics/digestive-diseases/cyclic-vomiting-syndrome/Pages/facts.aspx", "retrieved": "2026-08-14", "body": "The cause of cyclic vomiting syndrome is unknown. However, some experts believe that some possible problems with bodily functions may contribute to the cause, such as the following: - gastrointestinal motilitythe way food moves through the digestive system - central nervous system functionincludes the brain, spinal cord, and nerves that control bodily responses - autonomic nervous system functionnerves that control internal organs such as the heart - hormone imbalanceshormones are a chemical produced in one part of the body and released into the blood to trigger or regulate particular bodily functions - in children, an abnormal inherited gene may also contribute to the condition Specific con…", "cues": ["what causes cyclic vomiting syndrome?", "cyclic vomiting syndrome causes"]}, {"id": "medquad-NIDDK-0000094-6", "topic": "vomiting", "intent": "symptom", "type": "public-health", "org": "NIDDK (US National Institute of Diabetes and Digestive and Kidney Diseases)", "title": "What are the symptoms of Cyclic Vomiting Syndrome?", "url": "https://www.niddk.nih.gov/health-information/health-topics/digestive-diseases/cyclic-vomiting-syndrome/Pages/facts.aspx", "retrieved": "2026-08-14", "body": "The main symptoms of cyclic vomiting syndrome are severe nausea and sudden vomiting lasting hours to days. A person may also experience one or more of the following symptoms: - retching, or making an attempt to vomit - heaving or gagging - lack of appetite - abdominal pain - diarrhea - fever - dizziness - headache - sensitivity to light Intensity of symptoms will vary as a person cycles through four distinct phases of an episode: - Prodrome phase. During the prodrome phase, the person feels that an episode of nausea and vomiting is about to start. Often marked by intense sweating and nauseawith or without abdominal painthis phase can last from a few minutes to several hours.", "cues": ["what are the symptoms of cyclic vomiting syndrome?", "cyclic vomiting syndrome symptoms"]}, {"id": "medquad-NIDDK-0000094-7", "topic": "vomiting", "intent": "general-health", "type": "public-health", "org": "NIDDK (US National Institute of Diabetes and Digestive and Kidney Diseases)", "title": "What are the complications of Cyclic Vomiting Syndrome?", "url": "https://www.niddk.nih.gov/health-information/health-topics/digestive-diseases/cyclic-vomiting-syndrome/Pages/facts.aspx", "retrieved": "2026-08-14", "body": "The severe vomiting and retching that define cyclic vomiting syndrome increase the chance of developing several complications, including dehydration, esophagitis, a Mallory-Weiss tear, and tooth decay. - Dehydration may occur when a person does not replace fluids that were lost because of vomiting and diarrhea. When dehydrated, the body lacks enough fluid and electrolytesminerals in salts, including sodium, potassium, and chlorideto function properly. Severe dehydration may require intravenous (IV) fluids and hospitalization. - Esophagitisinflammation or irritation of the esophaguscan result from the stomach acid that exits through the esophagus during vomiting.", "cues": ["what are the complications of cyclic vomiting syndrome?", "cyclic vomiting syndrome complications"]}, {"id": "medquad-NIDDK-0000094-9", "topic": "vomiting", "intent": "general-health", "type": "public-health", "org": "NIDDK (US National Institute of Diabetes and Digestive and Kidney Diseases)", "title": "How to diagnose Cyclic Vomiting Syndrome?", "url": "https://www.niddk.nih.gov/health-information/health-topics/digestive-diseases/cyclic-vomiting-syndrome/Pages/facts.aspx", "retrieved": "2026-08-14", "body": "A specific test to diagnose cyclic vomiting syndrome does not exist; instead, a health care provider will rule out other conditions and diagnose the syndrome based upon - a medical and family history - a physical exam - a pattern or cycle of symptoms - blood tests - urine tests - imaging tests - upper GI endoscopy - a gastric emptying test Often, it is suspected that one of the following is causing their symptoms: - gastroparesisa disorder that slows or stops the movement of food from the stomach to the small intestine - gastroenteritisinflammation of the lining of the stomach, small intestine, and large intestine A diagnosis of cyclic vomiting syndrome may be difficult to make until the per…", "cues": ["how to diagnose cyclic vomiting syndrome?", "cyclic vomiting syndrome exams and tests"]}, {"id": "medquad-NIDDK-0000095-1", "topic": "skin", "intent": "symptom", "type": "public-health", "org": "NIDDK (US National Institute of Diabetes and Digestive and Kidney Diseases)", "title": "What are the symptoms of Dermatitis Herpetiformis: Skin Manifestation of Celiac Disease (For Health Care Professionals)?", "url": "https://www.niddk.nih.gov/health-information/health-topics/digestive-diseases/dermatitis-herpetiformis/Pages/facts.aspx", "retrieved": "2026-08-14", "body": "Dermatitis herpetiformis is characterized by small, clustered papules and vesicles that erupt symmetrically on the elbows, knees, buttocks, back, or scalp. The face and groin can also be involved. A burning sensation may precede lesion formation. Lesions are usually scratched off by the time a patient comes in for a physical exam, and the rash may appear as erosions and excoriations. Patients with DH may also experience dental enamel defects to permanent teeth, which is another manifestation of celiac disease. Less than 20 percent of people with DH have symptoms of celiac disease.3", "cues": ["what are the symptoms of dermatitis herpetiformis: skin manifestation of celiac disease (for health care professionals)?", "dermatitis herpetiformis: skin manifestation of celiac disease (for health care professionals) symptoms"]}, {"id": "medquad-NIDDK-0000109-2", "topic": "indigestion", "intent": "symptom", "type": "public-health", "org": "NIDDK (US National Institute of Diabetes and Digestive and Kidney Diseases)", "title": "What causes Indigestion?", "url": "https://www.niddk.nih.gov/health-information/health-topics/digestive-diseases/indigestion/Pages/facts.aspx", "retrieved": "2026-08-14", "body": "Indigestion can be caused by a condition in the digestive tract such as gastroesophageal reflux disease (GERD), peptic ulcer disease, cancer, or abnormality of the pancreas or bile ducts. If the condition improves or resolves, the symptoms of indigestion usually improve. Sometimes a person has indigestion for which a cause cannot be found. This type of indigestion, called functional dyspepsia, is thought to occur in the area where the stomach meets the small intestine. The indigestion may be related to abnormal motilitythe squeezing or relaxing actionof the stomach muscle as it receives, digests, and moves food into the small intestine.", "cues": ["what causes indigestion?", "indigestion causes"]}, {"id": "medquad-NIDDK-0000109-3", "topic": "indigestion", "intent": "symptom", "type": "public-health", "org": "NIDDK (US National Institute of Diabetes and Digestive and Kidney Diseases)", "title": "What are the symptoms of Indigestion?", "url": "https://www.niddk.nih.gov/health-information/health-topics/digestive-diseases/indigestion/Pages/facts.aspx", "retrieved": "2026-08-14", "body": "Most people with indigestion experience more than one of the following symptoms: - Fullness during a meal. The person feels overly full soon after the meal starts and cannot finish the meal. - Bothersome fullness after a meal. The person feels overly full after a mealit may feel like the food is staying in the stomach too long. - Epigastric pain. The epigastric area is between the lower end of the chest bone and the navel. The person may experience epigastric pain ranging from mild to severe. - Epigastric burning. The person feels an unpleasant sensation of heat in the epigastric area.", "cues": ["what are the symptoms of indigestion?", "indigestion symptoms"]}, {"id": "medquad-NIDDK-0000109-4", "topic": "indigestion", "intent": "general-health", "type": "public-health", "org": "NIDDK (US National Institute of Diabetes and Digestive and Kidney Diseases)", "title": "How to diagnose Indigestion?", "url": "https://www.niddk.nih.gov/health-information/health-topics/digestive-diseases/indigestion/Pages/facts.aspx", "retrieved": "2026-08-14", "body": "To diagnose indigestion, the doctor asks about the person's current symptoms and medical history and performs a physical examination. The doctor may order x rays of the stomach and small intestine. The doctor may perform blood, breath, or stool tests if the type of bacteria that causes peptic ulcer disease is suspected as the cause of indigestion. The doctor may perform an upper endoscopy. After giving a sedative to help the person become drowsy, the doctor passes an endoscopea long, thin tube that has a light and small camera on the endthrough the mouth and gently guides it down the esophagus into the stomach.", "cues": ["how to diagnose indigestion?", "indigestion exams and tests"]}, {"id": "medquad-NIDDK-0000109-5", "topic": "indigestion", "intent": "general-health", "type": "public-health", "org": "NIDDK (US National Institute of Diabetes and Digestive and Kidney Diseases)", "title": "What are the treatments for Indigestion?", "url": "https://www.niddk.nih.gov/health-information/health-topics/digestive-diseases/indigestion/Pages/facts.aspx", "retrieved": "2026-08-14", "body": "Some people may experience relief from symptoms of indigestion by - eating several small, low-fat meals throughout the day at a slow pace - refraining from smoking - abstaining from consuming coffee, carbonated beverages, and alcohol - stopping use of medications that may irritate the stomach liningsuch as aspirin or anti-inflammatory drugs - getting enough rest - finding ways to decrease emotional and physical stress, such as relaxation therapy or yoga The doctor may recommend over-the-counter antacids or medications that reduce acid production or help the stomach move food more quickly into the small intestine. Many of these medications can be purchased without a prescription.", "cues": ["what are the treatments for indigestion?", "indigestion treatment"]}, {"id": "medquad-NIDDK-0000109-6", "topic": "indigestion", "intent": "general-health", "type": "public-health", "org": "NIDDK (US National Institute of Diabetes and Digestive and Kidney Diseases)", "title": "What to do for Indigestion?", "url": "https://www.niddk.nih.gov/health-information/health-topics/digestive-diseases/indigestion/Pages/facts.aspx", "retrieved": "2026-08-14", "body": "- Indigestion, also known as dyspepsia, is a term used to describe one or more symptoms including a feeling of fullness during a meal, uncomfortable fullness after a meal, and burning or pain in the upper abdomen. - Indigestion can be caused by a condition in the digestive tract such as gastroesophageal reflux disease (GERD), peptic ulcer disease, cancer, or abnormality of the pancreas or bile ducts. - Sometimes a person has indigestion for which a cause cannot be found. This type of indigestion is called functional dyspepsia. - Indigestion and heartburn are different conditions, but a person can have symptoms of both.", "cues": ["what to do for indigestion?", "indigestion considerations"]}, {"id": "medquad-NIDDK-0000121-1", "topic": "smoking", "intent": "general-health", "type": "public-health", "org": "NIDDK (US National Institute of Diabetes and Digestive and Kidney Diseases)", "title": "What is (are) Smoking and the Digestive System?", "url": "https://www.niddk.nih.gov/health-information/health-topics/digestive-diseases/smoking/Pages/facts.aspx", "retrieved": "2026-08-14", "body": "The digestive system is made up of the gastrointestinal (GI) tractalso called the digestive tractand the liver, pancreas, and gallbladder. The GI tract is a series of hollow organs joined in a long, twisting tube from the mouth to the anus. The hollow organs that make up the GI tract are the mouth, esophagus, stomach, small intestine, large intestinewhich includes the colon and rectumand anus. Food enters the mouth and passes to the anus through the hollow organs of the GI tract. The liver, pancreas, and gallbladder are the solid organs of the digestive system. The digestive system helps the body digest food, which includes breaking food down into nutrients the body needs.", "cues": ["what is (are) smoking and the digestive system?", "smoking and the digestive system information"]}, {"id": "medquad-NIDDK-0000121-12", "topic": "smoking", "intent": "general-health", "type": "public-health", "org": "NIDDK (US National Institute of Diabetes and Digestive and Kidney Diseases)", "title": "What to do for Smoking and the Digestive System?", "url": "https://www.niddk.nih.gov/health-information/health-topics/digestive-diseases/smoking/Pages/facts.aspx", "retrieved": "2026-08-14", "body": "Eating, diet, and nutrition can play a role in causing, preventing, and treating some of the diseases and disorders of the digestive system that are affected by smoking, including heartburn and GERD, liver diseases, Crohns disease, colon polyps, pancreatitis, and gallstones. More information about eating, diet, and nutrition and these conditions can be found on the Digestive Diseases A-Z list.", "cues": ["what to do for smoking and the digestive system?", "smoking and the digestive system considerations"]}, {"id": "medquad-NIDDK-0000121-2", "topic": "smoking", "intent": "preventive", "type": "public-health", "org": "NIDDK (US National Institute of Diabetes and Digestive and Kidney Diseases)", "title": "Who is at risk for Smoking and the Digestive System??", "url": "https://www.niddk.nih.gov/health-information/health-topics/digestive-diseases/smoking/Pages/facts.aspx", "retrieved": "2026-08-14", "body": "Smoking has been found to increase the risk of cancers of the3 - mouth - esophagus - stomach - pancreas 3 , 4 , 5 - liver - colon - rectum More information about the link between smoking and cancers of the digestive system can be found on the National Cancer Institute website at www.cancer.gov/cancertopics/tobacco/smoking.", "cues": ["who is at risk for smoking and the digestive system??", "smoking and the digestive system susceptibility"]}, {"id": "medquad-NIDDK-0000150-1", "topic": "high blood pressure", "intent": "general-health", "type": "public-health", "org": "NIDDK (US National Institute of Diabetes and Digestive and Kidney Diseases)", "title": "What is (are) High Blood Pressure and Kidney Disease?", "url": "https://www.niddk.nih.gov/health-information/health-topics/kidney-disease/high-blood-pressure-and-kidney-disease/Pages/facts.aspx", "retrieved": "2026-08-14", "body": "Blood pressure is the force of blood pushing against blood vessel walls as the heart pumps out blood, and high blood pressure, also called hypertension, is an increase in the amount of force that blood places on blood vessels as it moves through the body. Factors that can increase this force include higher blood volume due to extra fluid in the blood and blood vessels that are narrow, stiff, or clogged. Blood pressure test results are written with two numbers separated by a slash. For example, a health care provider will write a blood pressure result as 120/80. A health care provider will say this blood pressure result as 120 over 80.", "cues": ["what is (are) high blood pressure and kidney disease?", "high blood pressure and kidney disease information"]}, {"id": "medquad-NIDDK-0000150-4", "topic": "high blood pressure", "intent": "symptom", "type": "public-health", "org": "NIDDK (US National Institute of Diabetes and Digestive and Kidney Diseases)", "title": "What are the symptoms of High Blood Pressure and Kidney Disease?", "url": "https://www.niddk.nih.gov/health-information/health-topics/kidney-disease/high-blood-pressure-and-kidney-disease/Pages/facts.aspx", "retrieved": "2026-08-14", "body": "Most people with high blood pressure do not have symptoms. In rare cases, high blood pressure can cause headaches. Kidney disease also does not have symptoms in the early stages. A person may have swelling called edema, which happens when the kidneys cannot get rid of extra fluid and salt. Edema can occur in the legs, feet, or ankles and less often in the hands or face.", "cues": ["what are the symptoms of high blood pressure and kidney disease?", "high blood pressure and kidney disease symptoms"]}, {"id": "medquad-NIDDK-0000150-5", "topic": "high blood pressure", "intent": "general-health", "type": "public-health", "org": "NIDDK (US National Institute of Diabetes and Digestive and Kidney Diseases)", "title": "How to diagnose High Blood Pressure and Kidney Disease?", "url": "https://www.niddk.nih.gov/health-information/health-topics/kidney-disease/high-blood-pressure-and-kidney-disease/Pages/facts.aspx", "retrieved": "2026-08-14", "body": "A health care provider diagnoses high blood pressure when multiple blood pressure testsoften repeated over several visits to a health care providers officeshow that a systolic blood pressure is consistently above 140 or a diastolic blood pressure is consistently above 90. Health care providers measure blood pressure with a blood pressure cuff. People can also buy blood pressure cuffs at discount chain stores and drugstores to monitor their blood pressure at home. Kidney disease is diagnosed with urine and blood tests. Urine Tests Dipstick test for albumin. A dipstick test performed on a urine sample can detect the presence of albumin in the urine.", "cues": ["how to diagnose high blood pressure and kidney disease?", "high blood pressure and kidney disease exams and tests"]}, {"id": "medquad-NIDDK-0000150-6", "topic": "high blood pressure", "intent": "preventive", "type": "public-health", "org": "NIDDK (US National Institute of Diabetes and Digestive and Kidney Diseases)", "title": "How to prevent High Blood Pressure and Kidney Disease?", "url": "https://www.niddk.nih.gov/health-information/health-topics/kidney-disease/high-blood-pressure-and-kidney-disease/Pages/facts.aspx", "retrieved": "2026-08-14", "body": "The best way to slow or prevent kidney disease from high blood pressure is to take steps to lower blood pressure. These steps include a combination of medication and lifestyle changes, such as - healthy eating - physical activity - maintaining a healthy weight - quitting smoking - managing stress No matter what the cause of the kidney disease, high blood pressure can increase damage to the kidneys. People with kidney disease should keep their blood pressure below 140/90.4 Medication Medications that lower blood pressure can also significantly slow the progression of kidney disease.", "cues": ["how to prevent high blood pressure and kidney disease?", "high blood pressure and kidney disease prevention"]}, {"id": "medquad-NIDDK-0000188-1", "topic": "alcohol", "intent": "general-health", "type": "public-health", "org": "NIDDK (US National Institute of Diabetes and Digestive and Kidney Diseases)", "title": "How to diagnose Nonalcoholic Steatohepatitis?", "url": "https://www.niddk.nih.gov/health-information/health-topics/liver-disease/nonalcoholic-steatohepatitis/Pages/facts.aspx", "retrieved": "2026-08-14", "body": "NASH is usually first suspected in a person who is found to have elevations in liver tests that are included in routine blood test panels, such as alanine aminotransferase (ALT) or aspartate aminotransferase (AST). When further evaluation shows no apparent reason for liver disease (such as medications, viral hepatitis, or excessive use of alcohol) and when x rays or imaging studies of the liver show fat, NASH is suspected. The only means of proving a diagnosis of NASH and separating it from simple fatty liver is a liver biopsy. For a liver biopsy, a needle is inserted through the skin to remove a small piece of the liver.", "cues": ["how to diagnose nonalcoholic steatohepatitis?", "nonalcoholic steatohepatitis exams and tests"]}, {"id": "medquad-NIDDK-0000188-2", "topic": "alcohol", "intent": "symptom", "type": "public-health", "org": "NIDDK (US National Institute of Diabetes and Digestive and Kidney Diseases)", "title": "What are the symptoms of Nonalcoholic Steatohepatitis?", "url": "https://www.niddk.nih.gov/health-information/health-topics/liver-disease/nonalcoholic-steatohepatitis/Pages/facts.aspx", "retrieved": "2026-08-14", "body": "NASH is usually a silent disease with few or no symptoms. Patients generally feel well in the early stages and only begin to have symptomssuch as fatigue, weight loss, and weaknessonce the disease is more advanced or cirrhosis develops. The progression of NASH can take years, even decades. The process can stop and, in some cases, reverse on its own without specific therapy. Or NASH can slowly worsen, causing scarring or fibrosis to appear and accumulate in the liver. As fibrosis worsens, cirrhosis develops; the liver becomes seriously scarred, hardened, and unable to function normally.", "cues": ["what are the symptoms of nonalcoholic steatohepatitis?", "nonalcoholic steatohepatitis symptoms"]}, {"id": "medquad-NIDDK-0000188-3", "topic": "alcohol", "intent": "symptom", "type": "public-health", "org": "NIDDK (US National Institute of Diabetes and Digestive and Kidney Diseases)", "title": "What causes Nonalcoholic Steatohepatitis?", "url": "https://www.niddk.nih.gov/health-information/health-topics/liver-disease/nonalcoholic-steatohepatitis/Pages/facts.aspx", "retrieved": "2026-08-14", "body": "Although NASH has become more common, its underlying cause is still not clear. It most often occurs in persons who are middle-aged and overweight or obese. Many patients with NASH have elevated blood lipids, such as cholesterol and triglycerides, and many have diabetes or prediabetes, but not every obese person or every patient with diabetes has NASH. Furthermore, some patients with NASH are not obese, do not have diabetes, and have normal blood cholesterol and lipids. NASH can occur without any apparent risk factor and can even occur in children. Thus, NASH is not simply obesity that affects the liver.", "cues": ["what causes nonalcoholic steatohepatitis?", "nonalcoholic steatohepatitis causes"]}, {"id": "medquad-NIDDK-0000217-1", "topic": "flu", "intent": "general-health", "type": "public-health", "org": "NIDDK (US National Institute of Diabetes and Digestive and Kidney Diseases)", "title": "What is (are) Vesicoureteral Reflux?", "url": "https://www.niddk.nih.gov/health-information/health-topics/urologic-disease/vesicoureteral-reflux-vur/Pages/facts.aspx", "retrieved": "2026-08-14", "body": "Vesicoureteral reflux is the abnormal flow of urine from the bladder to the upper urinary tract. The urinary tract is the bodys drainage system for removing wastes and extra water. The urinary tract includes two kidneys, two ureters, a bladder, and a urethra. Blood flows through the kidneys, and the kidneys filter out wastes and extra water, making urine. The urine travels down two narrow tubes called the ureters. The urine is then stored in a balloonlike organ called the bladder. When the bladder empties, urine flows out of the body through a tube called the urethra at the bottom of the bladder.", "cues": ["what is (are) vesicoureteral reflux?", "vesicoureteral reflux information"]}, {"id": "medquad-NIHSeniorHealth-0000005-1", "topic": "anxiety", "intent": "general-health", "type": "public-health", "org": "NIH SeniorHealth", "title": "What is (are) Anxiety Disorders?", "url": "https://nihseniorhealth.gov/anxietydisorders/toc.html", "retrieved": "2026-08-14", "body": "Occasional anxiety is a normal part of life. You might feel anxious when faced with a problem at work, before taking a test, or making an important decision. However, anxiety disorders involve more than temporary worry or fear. For a person with an anxiety disorder, the anxiety does not go away and can get worse over time. These feelings can interfere with daily activities such as job performance, school work, and relationships. (Watch the video to learn about the types of anxiety disorders. To enlarge the video, click the brackets in the lower right-hand corner.", "cues": ["what is (are) anxiety disorders?", "anxiety disorders information"]}, {"id": "medquad-NIHSeniorHealth-0000005-17", "topic": "anxiety", "intent": "preventive", "type": "public-health", "org": "NIH SeniorHealth", "title": "Who is at risk for Anxiety Disorders??", "url": "https://nihseniorhealth.gov/anxietydisorders/toc.html", "retrieved": "2026-08-14", "body": "Generalized anxiety disorder (GAD) affects about 6.8 million American adults, including twice as many women as men. The disorder develops gradually and can begin at any point in the life cycle, although the years of highest risk are between childhood and middle age. The average age of onset is 31 years old. Social phobia affects about 15 million American adults. Women and men are equally likely to develop the disorder, which usually begins in childhood or early adolescence. There is some evidence that genetic factors are involved. Panic disorder affects about 6 million American adults and is twice as common in women as men.", "cues": ["who is at risk for anxiety disorders??", "anxiety disorders susceptibility"]}, {"id": "medquad-NIHSeniorHealth-0000005-19", "topic": "anxiety", "intent": "general-health", "type": "public-health", "org": "NIH SeniorHealth", "title": "What are the treatments for Anxiety Disorders?", "url": "https://nihseniorhealth.gov/anxietydisorders/toc.html", "retrieved": "2026-08-14", "body": "Most insurance plans, including health maintenance organizations (HMOs), will cover treatment for anxiety disorders. Check with your insurance company and find out. If you dont have insurance, the Health and Human Services division of your county government may offer mental health care at a public mental health center that charges people according to how much they are able to pay. If you are on public assistance, you may be able to get care through your state Medicaid plan. To learn about more mental health resources, see Help for Mental Illness, from the National Institute of Mental Health at NIH.", "cues": ["what are the treatments for anxiety disorders?", "anxiety disorders treatment"]}, {"id": "medquad-NIHSeniorHealth-0000005-2", "topic": "anxiety", "intent": "symptom", "type": "public-health", "org": "NIH SeniorHealth", "title": "What are the symptoms of Anxiety Disorders?", "url": "https://nihseniorhealth.gov/anxietydisorders/toc.html", "retrieved": "2026-08-14", "body": "Excessive, Irrational Fear Each anxiety disorder has different symptoms, but all the symptoms cluster around excessive, irrational fear and dread. Unlike the relatively mild, brief anxiety caused by a specific event (such as speaking in public or a first date), severe anxiety that lasts at least six months is generally considered to be problem that might benefit from evaluation and treatment. Anxiety disorders commonly occur along with other mental or physical illnesses, including alcohol or substance abuse, which may mask anxiety symptoms or make them worse. In older adults, anxiety disorders often occur at the same time as depression, heart disease, diabetes, and other medical problems.", "cues": ["what are the symptoms of anxiety disorders?", "anxiety disorders symptoms"]}, {"id": "medquad-NIHSeniorHealth-0000005-3", "topic": "anxiety", "intent": "general-health", "type": "public-health", "org": "NIH SeniorHealth", "title": "How to diagnose Anxiety Disorders?", "url": "https://nihseniorhealth.gov/anxietydisorders/toc.html", "retrieved": "2026-08-14", "body": "Anxiety disorders sometimes run in families, but no one knows for sure why some people have them while others don't. Anxiety disorders are more common among younger adults than older adults, and they typically start in early life. However, anyone can develop an anxiety disorder at any time. Below are risk factors for these anxiety disorders. - Generalized Anxiety Disorder (GAD) - Social Anxiety Disorder (Social Phobia) - Panic Disorder Generalized Anxiety Disorder (GAD) Social Anxiety Disorder (Social Phobia) Panic Disorder Generalized Anxiety Disorder - Risk Factors Generalized anxiety disorder (GAD) affects about 6.8 million American adults, including twice as many women as men.", "cues": ["how to diagnose anxiety disorders?", "anxiety disorders exams and tests"]}, {"id": "medquad-NIHSeniorHealth-0000014-14", "topic": "depression", "intent": "preventive", "type": "public-health", "org": "NIH SeniorHealth", "title": "Who is at risk for Depression??", "url": "https://nihseniorhealth.gov/depression/toc.html", "retrieved": "2026-08-14", "body": "The risk factors for depression are family history, life experiences, and environment. If you have depression, you may have experienced it when you were younger, and may have a family history of the illness. You may also be going through difficult life events, such as physical or psychological trauma, losing a loved one, a difficult relationship with a family member or friend, or financial troubles. Any of these stressful experiences can lead to depression. For older adults who experience depression for the first time later in life, other factors may be at play. Depression may be related to changes that occur in the brain and body as a person ages.", "cues": ["who is at risk for depression??", "depression susceptibility"]}, {"id": "medquad-NIHSeniorHealth-0000014-19", "topic": "depression", "intent": "general-health", "type": "public-health", "org": "NIH SeniorHealth", "title": "What are the treatments for Depression?", "url": "https://nihseniorhealth.gov/depression/toc.html", "retrieved": "2026-08-14", "body": "Medications called antidepressants work to normalize brain chemicals called neurotransmitters, notably serotonin, norepinephrine, and dopamine. Scientists studying depression have found that these chemicals, and possibly others, are involved in regulating mood, but they are unsure of exactly how they work. Newer Antidepressants. The newest and most popular types of antidepressant medications are called selective serotonin reuptake inhibitors (SSRIs). They include fluoxetine (Prozac), citalopram (Celexa) and several others. Similar to SSRIs are serotonin and norepinephrine reuptake inhibitors (SNRIs) and include venlafaxine (Effexor) and duloxetine (Cymbalta).", "cues": ["what are the treatments for depression?", "depression treatment"]}, {"id": "medquad-NIHSeniorHealth-0000014-2", "topic": "depression", "intent": "symptom", "type": "public-health", "org": "NIH SeniorHealth", "title": "What causes Depression?", "url": "https://nihseniorhealth.gov/depression/toc.html", "retrieved": "2026-08-14", "body": "Several lines of research have shown that depressive illnesses are disorders of the brain. But the exact causes for these illnesses are not yet clear and are still being studied. Changes in the Brain Imaging technologies show that the brains of people with depression look different or are working differently than those who do not have the illness. The areas of the brain that control moods, thinking, sleep, appetite, and behavior appear not to be functioning well. The scans also show very high or very low levels of important brain chemicals. But these images do not reveal WHY the depression has occurred. Many Possible Causes In general, there is no one cause or risk factor for depression.", "cues": ["what causes depression?", "depression causes"]}, {"id": "medquad-NIHSeniorHealth-0000014-4", "topic": "depression", "intent": "symptom", "type": "public-health", "org": "NIH SeniorHealth", "title": "What are the symptoms of Depression?", "url": "https://nihseniorhealth.gov/depression/toc.html", "retrieved": "2026-08-14", "body": "Common Symptoms There are many symptoms associated with depression, and some will vary depending on the individual. However, some of the most common symptoms are listed below. If you have several of these symptoms for more than two weeks, you may have depression.", "cues": ["what are the symptoms of depression?", "depression symptoms"]}, {"id": "medquad-NIHSeniorHealth-0000032-1", "topic": "hearing", "intent": "general-health", "type": "public-health", "org": "NIH SeniorHealth", "title": "What is (are) Hearing Loss?", "url": "https://nihseniorhealth.gov/hearingloss/toc.html", "retrieved": "2026-08-14", "body": "Hearing loss is a common problem caused by noise, aging, disease, and heredity. Hearing is a complex sense involving both the ear's ability to detect sounds and the brain's ability to interpret those sounds, including the sounds of speech.", "cues": ["what is (are) hearing loss?", "hearing loss information"]}, {"id": "medquad-NIHSeniorHealth-0000032-2", "topic": "hearing", "intent": "preventive", "type": "public-health", "org": "NIH SeniorHealth", "title": "How to prevent Hearing Loss?", "url": "https://nihseniorhealth.gov/hearingloss/toc.html", "retrieved": "2026-08-14", "body": "Causes of Hearing Loss Hearing loss happens for many reasons. Some people lose their hearing slowly as they age. This condition is called presbycusis. Doctors do not know why presbycusis happens, but it seems to run in families. Another cause is the ear infection otitis media, which can lead to long-term hearing loss if it is not treated. Hearing loss can also result from taking certain medications. \"Ototoxic\" medications damage the inner ear, sometimes permanently. Some antibiotics are ototoxic. Even aspirin at some dosages can cause problems, but they are temporary. Check with your doctor if you notice a problem while taking a medication.", "cues": ["how to prevent hearing loss?", "hearing loss prevention"]}, {"id": "medquad-NIHSeniorHealth-0000032-3", "topic": "hearing", "intent": "symptom", "type": "public-health", "org": "NIH SeniorHealth", "title": "What are the symptoms of Hearing Loss?", "url": "https://nihseniorhealth.gov/hearingloss/toc.html", "retrieved": "2026-08-14", "body": "Don't Ignore Hearing Problems Some people have a hearing problem without realizing it. Others might think they have a problem, but are too embarrassed to tell their doctor, friends, or family. You can help identify a possible hearing problem by asking yourself some key questions and, if necessary, having your hearing checked by a doctor. If a hearing loss is ignored or untreated, it can get worse. But a hearing loss that is identified early can be helped through treatment, such as hearing aids, certain medications, and surgery. Do You Have A Hearing Problem? Ask yourself the following questions.", "cues": ["what are the symptoms of hearing loss?", "hearing loss symptoms"]}, {"id": "medquad-NIHSeniorHealth-0000042-1", "topic": "vision", "intent": "general-health", "type": "public-health", "org": "NIH SeniorHealth", "title": "What is (are) Low Vision?", "url": "https://nihseniorhealth.gov/lowvision/toc.html", "retrieved": "2026-08-14", "body": "Everyday Tasks Are Challenging Low vision means that even with regular glasses, contact lenses, medicine, or surgery, people find everyday tasks difficult to do. Reading the mail, shopping, cooking, seeing the TV, and writing can seem challenging. Millions of Americans lose some of their vision every year. Irreversible vision loss is most common among people over age 65. (Watch the video to learn more about low vision. To enlarge the video, click the brackets in the lower right-hand corner. To reduce the video, press the Escape (Esc) button on your keyboard.) Not a Normal Part of Aging Losing vision is not just part of getting older. Some normal changes occur as we get older.", "cues": ["what is (are) low vision?", "low vision information"]}, {"id": "medquad-NIHSeniorHealth-0000042-2", "topic": "vision", "intent": "symptom", "type": "public-health", "org": "NIH SeniorHealth", "title": "What causes Low Vision?", "url": "https://nihseniorhealth.gov/lowvision/toc.html", "retrieved": "2026-08-14", "body": "Eye Diseases and Health Conditions Most people develop low vision because of eye diseases and health conditions like macular degeneration, cataracts, glaucoma, and diabetes. Your eye care professional can tell the difference between normal changes in the aging eye and those caused by eye diseases. Injuries and Birth Defects A few people develop vision loss after eye injuries or from birth defects. Although vision that is lost usually cannot be restored, many people can make the most of the vision they have. How a Scene Looks to People With Normal and Low Vision Scene as viewed by a person with normal vision. Scene as viewed by a person with diabetic retinopathy.", "cues": ["what causes low vision?", "low vision causes"]}, {"id": "medquad-NIHSeniorHealth-0000042-3", "topic": "vision", "intent": "symptom", "type": "public-health", "org": "NIH SeniorHealth", "title": "What are the symptoms of Low Vision?", "url": "https://nihseniorhealth.gov/lowvision/toc.html", "retrieved": "2026-08-14", "body": "There are many signs that can signal vision loss. For example, even with your regular glasses, do you have difficulty - recognizing faces of friends and relatives? - doing things that require you to see well up close, such as reading, cooking, sewing, fixing things around the house, or picking out and matching the color of your clothes? - doing things at work or home because lights seem dimmer than they used to? - reading street and bus signs or the names of stores? recognizing faces of friends and relatives? doing things that require you to see well up close, such as reading, cooking, sewing, fixing things around the house, or picking out and matching the color of your clothes?", "cues": ["what are the symptoms of low vision?", "low vision symptoms"]}, {"id": "medquad-NIHSeniorHealth-0000042-9", "topic": "vision", "intent": "preventive", "type": "public-health", "org": "NIH SeniorHealth", "title": "Who is at risk for Low Vision??", "url": "https://nihseniorhealth.gov/lowvision/toc.html", "retrieved": "2026-08-14", "body": "People age 60 and older, as well as African Americans and Hispanics over age 45, are at higher risk. African Americans and Hispanics are at higher risk for low vision because they are at higher risk for developing diabetes and diabetic retinopathy, and African Americans are at a higher risk for developing glaucoma.", "cues": ["who is at risk for low vision??", "low vision susceptibility"]}, {"id": "medquad-NINDS-0000037-2", "topic": "back pain", "intent": "general-health", "type": "public-health", "org": "NINDS (US National Institute of Neurological Disorders and Stroke)", "title": "What are the treatments for Back Pain?", "url": "https://www.ninds.nih.gov/disorders/backpain/backpain.htm", "retrieved": "2026-08-14", "body": "Most low back pain can be treated without surgery. Treatment involves using over-the-counter pain relievers to reduce discomfort and anti-inflammatory drugs to reduce inflammation. The goal of treatment is to restore proper function and strength to the back, and prevent recurrence of the injury. Medications are often used to treat acute and chronic low back pain. Effective pain relief may involve a combination of prescription drugs and over-the-counter remedies. Although the use of cold and hot compresses has never been scientifically proven to quickly resolve low back injury, compresses may help reduce pain and inflammation and allow greater mobility for some individuals.", "cues": ["what are the treatments for back pain?", "back pain treatment"]}, {"id": "medquad-NINDS-0000037-3", "topic": "back pain", "intent": "recovery", "type": "public-health", "org": "NINDS (US National Institute of Neurological Disorders and Stroke)", "title": "What is the outlook for Back Pain?", "url": "https://www.ninds.nih.gov/disorders/backpain/backpain.htm", "retrieved": "2026-08-14", "body": "Most patients with back pain recover without residual functional loss, but individuals should contact a doctor if there is not a noticeable reduction in pain and inflammation after 72 hours of self-care. Recurring back pain resulting from improper body mechanics or other nontraumatic causes is often preventable. Engaging in exercises that don't jolt or strain the back, maintaining correct posture, and lifting objects properly can help prevent injuries. Many work-related injuries are caused or aggravated by stressors such as heavy lifting, vibration, repetitive motion, and awkward posture.", "cues": ["what is the outlook for back pain?", "back pain outlook"]}, {"id": "medquad-NINDS-0000053-2", "topic": "traumatic brain injury", "intent": "general-health", "type": "public-health", "org": "NINDS (US National Institute of Neurological Disorders and Stroke)", "title": "What are the treatments for Traumatic Brain Injury?", "url": "https://www.ninds.nih.gov/disorders/tbi/tbi.htm", "retrieved": "2026-08-14", "body": "Anyone with signs of moderate or severe TBI should receive medical attention as soon as possible. Because little can be done to reverse the initial brain damage caused by trauma, medical personnel try to stabilize an individual with TBI and focus on preventing further injury. Primary concerns include insuring proper oxygen supply to the brain and the rest of the body, maintaining adequate blood flow, and controlling blood pressure. Imaging tests help in determining the diagnosis and prognosis of a TBI patient. Patients with mild to moderate injuries may receive skull and neck X-rays to check for bone fractures or spinal instability.", "cues": ["what are the treatments for traumatic brain injury?", "traumatic brain injury treatment"]}, {"id": "medquad-NINDS-0000053-3", "topic": "traumatic brain injury", "intent": "recovery", "type": "public-health", "org": "NINDS (US National Institute of Neurological Disorders and Stroke)", "title": "What is the outlook for Traumatic Brain Injury?", "url": "https://www.ninds.nih.gov/disorders/tbi/tbi.htm", "retrieved": "2026-08-14", "body": "Approximately half of severely head-injured patients will need surgery to remove or repair hematomas (ruptured blood vessels) or contusions (bruised brain tissue). Disabilities resulting from a TBI depend upon the severity of the injury, the location of the injury, and the age and general health of the individual. Some common disabilities include problems with cognition (thinking, memory, and reasoning), sensory processing (sight, hearing, touch, taste, and smell), communication (expression and understanding), and behavior or mental health (depression, anxiety, personality changes, aggression, acting out, and social inappropriateness).", "cues": ["what is the outlook for traumatic brain injury?", "traumatic brain injury outlook"]}, {"id": "medquad-NINDS-0000142-1", "topic": "iron", "intent": "general-health", "type": "public-health", "org": "NINDS (US National Institute of Neurological Disorders and Stroke)", "title": "What is (are) Neurodegeneration with Brain Iron Accumulation?", "url": "https://www.ninds.nih.gov/disorders/nbia/nbia.htm", "retrieved": "2026-08-14", "body": "Neurodegeneration with brain iron accumulation (NBIA) is a rare, inherited, neurological movement disorder characterized by an abnormal accumulation of iron in the brain and progressive degeneration of the nervous system.", "cues": ["what is (are) neurodegeneration with brain iron accumulation?", "neurodegeneration with brain iron accumulation information"]}, {"id": "medquad-NINDS-0000142-2", "topic": "iron", "intent": "general-health", "type": "public-health", "org": "NINDS (US National Institute of Neurological Disorders and Stroke)", "title": "What are the treatments for Neurodegeneration with Brain Iron Accumulation?", "url": "https://www.ninds.nih.gov/disorders/nbia/nbia.htm", "retrieved": "2026-08-14", "body": "There is no cure for NBIA, nor is there a standard course of treatment. Treatment is symptomatic and supportive, and may include physical or occupational therapy, exercise physiology, and/or speech pathology. Many medications are available to treat the primary symptoms of dystonia and spasticity, including oral medications, intrathecal baclofen pump (in which a small pump is implanted under the skin and is programmed to deliver a specific amount of medication on a regular basis), deep brain stimulation, and botulinum toxin injection.", "cues": ["what are the treatments for neurodegeneration with brain iron accumulation?", "neurodegeneration with brain iron accumulation treatment"]}, {"id": "medquad-NINDS-0000142-3", "topic": "iron", "intent": "recovery", "type": "public-health", "org": "NINDS (US National Institute of Neurological Disorders and Stroke)", "title": "What is the outlook for Neurodegeneration with Brain Iron Accumulation?", "url": "https://www.ninds.nih.gov/disorders/nbia/nbia.htm", "retrieved": "2026-08-14", "body": "NBIA is a progressive condition. Most individuals experience periods of rapid decline lasting weeks to months, with relatively stable periods in between. The rate of progression correlates with the age at onset, meaning that children with early symptoms tend to fare more poorly. For those with early onset, dystonia and spasticity can eventually limit the ability to walk, usually leading to use of a wheelchair by the midteens. Life expectancy is variable, although premature death does occur in NBIA. Premature death usually occurs due to secondary complications such as impaired swallowing or confinement to a bed or wheelchair, which can lead to poor nutrition or aspiration pneumonia.", "cues": ["what is the outlook for neurodegeneration with brain iron accumulation?", "neurodegeneration with brain iron accumulation outlook"]}, {"id": "medquad-NINDS-0000143-2", "topic": "headache", "intent": "general-health", "type": "public-health", "org": "NINDS (US National Institute of Neurological Disorders and Stroke)", "title": "What are the treatments for Headache?", "url": "https://www.ninds.nih.gov/disorders/headache/headache.htm", "retrieved": "2026-08-14", "body": "When headaches occur three or more times a month, preventive treatment is usually recommended. Drug therapy, biofeedback training, stress reduction, and elimination of certain foods from the diet are the most common methods of preventing and controlling migraine and other vascular headaches. Regular exercise, such as swimming or vigorous walking, can also reduce the frequency and severity of migraine headaches. Drug therapy for migraine is often combined with biofeedback and relaxation training. One of the most commonly used drugs for the relief of migraine symptoms is sumatriptan.", "cues": ["what are the treatments for headache?", "headache treatment"]}, {"id": "medquad-NINDS-0000143-3", "topic": "headache", "intent": "recovery", "type": "public-health", "org": "NINDS (US National Institute of Neurological Disorders and Stroke)", "title": "What is the outlook for Headache?", "url": "https://www.ninds.nih.gov/disorders/headache/headache.htm", "retrieved": "2026-08-14", "body": "Not all headaches require medical attention. But some types of headache are signals of more serious disorders and call for prompt medical care. These include: sudden, severe headache or sudden headache associated with a stiff neck; headaches associated with fever, convulsions, or accompanied by confusion or loss of consciousness; headaches following a blow to the head, or associated with pain in the eye or ear; persistent headache in a person who was previously headache free; and recurring headache in children. Migraine headaches may last a day or more and can strike as often as several times a week or as rarely as once every few years.", "cues": ["what is the outlook for headache?", "headache outlook"]}, {"id": "medquad-NINDS-0000194-2", "topic": "migraine", "intent": "general-health", "type": "public-health", "org": "NINDS (US National Institute of Neurological Disorders and Stroke)", "title": "What are the treatments for Migraine?", "url": "https://www.ninds.nih.gov/disorders/migraine/migraine.htm", "retrieved": "2026-08-14", "body": "There is no absolute cure for migraine since its pathophysiology has yet to be fully understood. There are two ways to approach the treatment of migraine headache with drugs: prevent the attacks, or relieve the symptoms during the attacks. Prevention involves the use of medications and behavioral changes. Drugs originally developed for epilepsy, depression, or high blood pressure to prevent future attacks have been shown to be extremely effective in treating migraine. Botulinum toxin A has been shown to be effective in prevention of chronic migraine.", "cues": ["what are the treatments for migraine?", "migraine treatment"]}, {"id": "medquad-NINDS-0000194-3", "topic": "migraine", "intent": "recovery", "type": "public-health", "org": "NINDS (US National Institute of Neurological Disorders and Stroke)", "title": "What is the outlook for Migraine?", "url": "https://www.ninds.nih.gov/disorders/migraine/migraine.htm", "retrieved": "2026-08-14", "body": "Responsive prevention and treatment of migraine is incredibly important. Evidence shows an increased sensitivity after each successive attack, eventually leading to chronic daily migraine in some individuals With proper combination of drugs for prevention and treatment of migraine attacks most individuals can overcome much of the discomfort from this debilitating disorder. Women whose migraine attacks occur in association with their menstrual cycle are likely to have fewer attacks and milder symptoms after menopause.", "cues": ["what is the outlook for migraine?", "migraine outlook"]}, {"id": "medquad-NINDS-0000254-2", "topic": "sleep", "intent": "general-health", "type": "public-health", "org": "NINDS (US National Institute of Neurological Disorders and Stroke)", "title": "What are the treatments for Sleep Apnea?", "url": "https://www.ninds.nih.gov/disorders/sleep_apnea/sleep_apnea.htm", "retrieved": "2026-08-14", "body": "There are a variety of treatments for sleep apnea, depending on an individuals medical history and the severity of the disorder. Most treatment regimens begin with lifestyle changes, such as avoiding alcohol and medications that relax the central nervous system (for example, sedatives and muscle relaxants), losing weight, and quitting smoking. Some people are helped by special pillows or devices that keep them from sleeping on their backs, or oral appliances to keep the airway open during sleep.", "cues": ["what are the treatments for sleep apnea?", "sleep apnea treatment"]}, {"id": "medquad-NINDS-0000254-3", "topic": "sleep", "intent": "recovery", "type": "public-health", "org": "NINDS (US National Institute of Neurological Disorders and Stroke)", "title": "What is the outlook for Sleep Apnea?", "url": "https://www.ninds.nih.gov/disorders/sleep_apnea/sleep_apnea.htm", "retrieved": "2026-08-14", "body": "Untreated, sleep apnea can be life threatening. Excessive daytime sleepiness can cause people to fall asleep at inappropriate times, such as while driving. Sleep apnea also appears to put individuals at risk for stroke and transient ischemic attacks (TIAs, also known as mini-strokes), and is associated with coronary heart disease, heart failure, irregular heartbeat, heart attack, and high blood pressure. Although there is no cure for sleep apnea, recent studies show that successful treatment can reduce the risk of heart and blood pressure problems.", "cues": ["what is the outlook for sleep apnea?", "sleep apnea outlook"]}, {"id": "medquad-NINDS-0000262-1", "topic": "headache", "intent": "general-health", "type": "public-health", "org": "NINDS (US National Institute of Neurological Disorders and Stroke)", "title": "What is (are) SUNCT Headache?", "url": "https://www.ninds.nih.gov/disorders/sunct/sunct.htm", "retrieved": "2026-08-14", "body": "SUNCT-Short-lasting, Unilateral, Neuralgiform headache attacks with Conjunctival injection and Tearing-is a rare form of headache that is most common in men after age 50. The disorder is marked by bursts of moderate to severe burning, piercing, or throbbing pain, usually on one side of the head and around the eye or temple. The pain usually peaks within seconds of onset and may follow a pattern of increasing and decreasing intensity. Attacks typically occur in daytime hours and last from 5 seconds to 4 minutes per episode. Individuals generally have five to six attacks per hour.", "cues": ["what is (are) sunct headache?", "sunct headache information"]}, {"id": "medquad-NINDS-0000262-2", "topic": "headache", "intent": "general-health", "type": "public-health", "org": "NINDS (US National Institute of Neurological Disorders and Stroke)", "title": "What are the treatments for SUNCT Headache?", "url": "https://www.ninds.nih.gov/disorders/sunct/sunct.htm", "retrieved": "2026-08-14", "body": "These headaches are generally non-responsive to usual treatment for other short-lasting headaches. Corticosteroids and the anti-epileptic drugs gabapentin, lamotrigine, and carbamazepine may help relieve some symptoms in some patients. Studies have shown that injections of glycerol to block nerve signaling along the trigeminal nerve may provide temporary relief in some severe cases, but the headaches recurred in about 40 percent of individuals studied.", "cues": ["what are the treatments for sunct headache?", "sunct headache treatment"]}] as const
